import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`디스패치 활성화, 백엔드 선택, 허용되는 대상 에이전트 제한, 스트리밍 턴 표시 동작 선택을 위한 ACP 런타임 제어 설정입니다.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`ACP 허용 에이전트`},help:{"v1-f2mw0d-3a":`ACP 런타임 세션에서 허용되는 ACP 대상 에이전트 ID의 허용 목록입니다. 비어 있으면 추가적인 허용 목록 제한이 없습니다.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP 백엔드`},help:{"v1-1s1l6bz-2v":`기본 ACP 런타임 백엔드 ID입니다(예: acpx). 등록된 ACP 런타임 플러그인 백엔드와 일치해야 합니다.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`ACP 기본 에이전트`},help:{"v1-7donnu-2c":`ACP 생성 시 대상을 명시적으로 지정하지 않은 경우 사용하는 대체 ACP 대상 에이전트 ID입니다.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACP 디스패치 활성화`},help:{"v1-1ug9t9m-3w":`ACP 세션 턴의 디스패치를 독립적으로 제어하는 설정입니다(기본값: true). ACP 명령은 계속 사용할 수 있도록 하면서 ACP 턴 실행을 차단하려면 false로 설정하세요.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP 활성화`},help:{"v1-1uonl1v-2a":`ACP 기능의 전역 활성화 설정입니다. ACP 런타임과 정책이 구성되지 않았다면 비활성화 상태로 유지하세요.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`ACP 대체 백엔드`},help:{"v1-1wvdifq-5m":`기본 백엔드가 UNAVAILABLE로 실패할 때(예: 요청 제한 / 할당량 소진) 순서대로 시도할 대체 ACP 백엔드 ID 목록입니다. 각 항목은 등록된 ACP 런타임 플러그인 백엔드와 일치해야 합니다.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`ACP 런타임 설치 명령`},help:{"v1-1jjuv9m-39":"ACP 백엔드 연결 설정이 없을 때 `/acp install` 및 `/acp doctor`에서 표시하는 선택적 운영자용 설치/설정 명령입니다."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP 스트림`},help:{"v1-1bka5p-2v":`청크 크기, 메타데이터 표시 여부, 중복 제거 전달 동작을 제어하는 ACP 스트리밍 출력 설정입니다.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`ACP 스트림 전달 모드`},help:{"v1-19gdmx1-3s":`ACP 전달 방식: live는 변환된 출력을 점진적으로 스트리밍하고, final_only는 턴 종료 이벤트가 발생할 때까지 변환된 모든 ACP 출력을 버퍼링합니다.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`ACP 스트림 반복 억제`},help:{"v1-manh32-3d":`true(기본값)이면 원시 ACP 이벤트는 그대로 유지하면서 한 턴 내에서 반복되는 ACP 상태/도구 출력 줄을 억제합니다.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`ACP 스트림 태그 표시 여부`},help:{"v1-1ybhx22-34":`ACP 출력의 sessionUpdate별 표시 여부 재정의 설정입니다(예: usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`에이전트`},help:{"v1-2rc4v8-55":`에이전트 런타임 구성의 루트입니다. 루트의 동일 수준 항목은 인프라와 에이전트 공통 기본값을 관리하고, agents.defaults는 에이전트 루프 동작을 관리합니다. 에이전트 항목은 지원되는 경우 두 설정 모두 재정의할 수 있습니다.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`에이전트 기본값`},help:{"v1-1af7k5b-5a":`agents.entries의 개별 항목에서 재정의하지 않는 한 에이전트가 상속하는 공통 기본 설정입니다. 기본값을 사용하면 일관된 기본 동작을 유지하고 에이전트별 설정의 중복을 줄일 수 있습니다.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`인증 상속 대상`},help:{"v1-2d16wl-2x":`자격 증명이 에이전트별로 재배치될 때까지 상속된 자격 증명 저장소의 업그레이드 호환성을 위한 소유자입니다.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`인증 상속 소유자`},help:{"v1-1a1s7nm-4s":`기본 마커가 폐기된 후에도 기존 자격 증명 저장소가 상속 원본으로 유지되는 에이전트입니다. 이전 소유자가 main이 아니었던 경우 업그레이드 중에 자동으로 기록됩니다.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`부트스트랩 최대 문자 수`},help:{"v1-drlo3i-37":`시스템 프롬프트에 삽입되는 각 작업 공간 부트스트랩 파일의 최대 문자 수입니다. 이 값을 초과하면 잘립니다(기본값: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`부트스트랩 총 최대 문자 수`},help:{"v1-1evwsjb-2c":`삽입되는 모든 작업 공간 부트스트랩 파일의 총 최대 문자 수입니다(기본값: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`압축`},help:{"v1-1qxdwz8-5p":`컨텍스트가 토큰 한도에 가까워졌을 때의 압축 동작으로, 압축 전략과 압축 전 메모리 저장 동작을 포함합니다. 제한된 컨텍스트 창에서도 장시간 실행되는 세션의 연속성을 안정적으로 유지해야 할 때 사용하세요.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`내장 자동 압축`},help:{"v1-1et7vwu-5l":`내장 선제적 자동 압축을 활성화합니다(기본값: true). false로 설정하면 임계값에 따른 내장 압축을 중지하면서 OpenClaw의 오버플로 복구, 사전 압축, 수동 /compact는 유지합니다.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`압축 시 식별자 정책`},help:{"v1-hby01l-4l":`압축 요약의 식별자 보존 정책입니다. "strict"는 불투명 식별자 보존을 위한 내장 지침을 앞에 추가하며(기본값), "off"는 이 접두 지침을 비활성화합니다.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`압축 시 최근 토큰 유지량`},help:{"v1-tgysub-5h":`압축 중 가장 최근 대화 구간에서 보존할 최소 토큰 예산입니다. 값을 높이면 직전 맥락의 연속성을 보호하고, 낮추면 오래된 기록을 더 많이 유지할 수 있습니다.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`압축을 위한 활성 대화 기록 크기 임계값`},help:{"v1-u715n1-90":`모델에 표시되는 대화 기록 구간(마지막 압축 또는 초기화 이후)이 이 크기에 도달하면 일반적인 사전 로컬 압축을 실행하는 바이트 임계값입니다(바이트 수 또는 "20mb" 같은 문자열). 0으로 설정하거나 설정하지 않으면 비활성화됩니다. Codex app-server의 네이티브 롤아웃 대화 기록 크기도 제한하며, 크기를 초과한 네이티브 스레드는 새로 시작됩니다.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`압축 전 메모리 저장`},help:{"v1-18q0ve9-55":`대규모 압축 전에 에이전트가 메모리를 기록하도록 하는 압축 전 메모리 저장 설정입니다. 긴 세션에서는 활성화 상태를 유지하여 기록을 대폭 줄이기 전에 중요한 맥락이 영구 저장되도록 하세요.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`압축 전 메모리 플러시 활성화`},help:{"v1-9xllgp-5o":`토큰 한도에 근접해 런타임이 기록을 더 많이 축소하기 전에 압축 전 메모리 플러시를 실행합니다. 제약이 있는 환경에서 메모리에 대한 부수 효과를 의도적으로 비활성화하는 경우가 아니라면 활성화 상태를 유지하세요.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`압축 전 메모리 플러시 대화 기록 크기 임계값`},help:{"v1-1rzov1e-93":`모델에 표시되는 대화 기록 범위가 이 임계값(바이트 수 또는 "2mb" 같은 문자열)에 도달하면 압축 전 메모리 플러시를 강제로 실행합니다. 압축 후에는 삭제된 기록이 아니라 유지된 끝부분과 이후 대화 턴이 여기에 포함됩니다. 토큰 카운터가 최신 상태가 아니어도 긴 세션이 멈추는 현상을 방지하려면 이 설정을 사용하세요. 비활성화하려면 0으로 설정하세요.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`압축 전 메모리 플러시 모델 재정의`},help:{"v1-1r3ctyu-7w":`압축 전 메모리 플러시 턴에만 사용되는 선택적 제공업체/모델 재정의입니다. 영구 보존할 메모리를 추출할 때 활성 세션의 유료 모델을 사용하지 않으려면 ollama/qwen3:8b 같은 로컬 모델로 설정하세요. 재정의는 지정한 모델만 사용하며 활성 모델의 폴백 체인을 상속하지 않습니다.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`압축 전 메모리 플러시 소프트 임계값`},help:{"v1-1dqo2l1-5c":`압축 전 메모리 플러시 실행을 트리거하는, 압축 시점까지 남은 토큰 수의 임계값입니다. 더 안전하게 영구 저장하려면 더 일찍 실행되는 임계값을, 플러시 빈도를 낮추려면 압축 시점에 더 가까운 임계값을 사용하세요.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`압축 턴 중간 사전 점검`},help:{"v1-am6gbh-6x":`도구 결과가 추가된 후 다음 모델 호출 전에 컨텍스트 용량 부족을 감지하는 선택적 내장 OpenClaw 도구 루프 사전 점검입니다. 활성화하면 OpenClaw가 기존 사전 점검 복구 로직을 재사용하여 도구 결과를 잘라내거나 압축한 후 재시도합니다.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`압축 턴 중간 사전 점검 활성화`},help:{"v1-engbwe-5u":`내장 OpenClaw 도구 루프에서 구조화된 턴 중간 컨텍스트 용량 점검을 활성화합니다. 기본값: false. 도구를 많이 사용하는 긴 세션에서 일반적인 턴 종료 시점의 압축이 실행되기 전에 컨텍스트 용량을 초과하는 경우가 아니라면 비활성화 상태로 유지하세요.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`압축 모드`},help:{"v1-1unahwc-76":`압축 전략 모드: "safeguard"(미설정 시 적용되는 기본값)는 최근 컨텍스트를 보존하는 보호 장치를 적용하고, "default"는 보호 장치 없이 기본 요약을 사용합니다. safeguard 요약이 사용 중인 제공업체에서 문제를 일으키는 경우에만 "default"로 설정하세요.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`압축 모델 재정의`},help:{"v1-cfeys9-6q":`압축 요약에만 사용할 선택적 provider/model 또는 설정된 단독 별칭입니다. 단독 별칭은 요청을 보내기 전에 해석됩니다. 설정된 리터럴 모델 ID가 별칭과 충돌하면 모델 ID가 우선합니다. 기본 에이전트 모델을 계속 사용하려면 설정하지 마세요.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`압축 시 사용자 알림`},help:{"v1-lvymm8-bv":`활성화하면 컨텍스트 압축이 시작되고 완료될 때 사용자에게 간단한 컨텍스트 유지 관리 알림을 보냅니다(예: '🧹 컨텍스트 압축 중...', '🧹 압축 완료'). 또한 압축 전 메모리 플러시 시도가 소진되어 성능이 저하된 상태로 응답을 이어갈 때도 알림을 보냅니다(예: '⚠️ 메모리 유지 관리가 일시적으로 실패했습니다. 응답을 계속합니다.'). 컨텍스트 유지 관리가 사용자를 방해하지 않고 조용히 이루어지도록 기본적으로 비활성화되어 있습니다.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`압축 후 컨텍스트 섹션`},help:{"v1-1n0ln2u-5f":`압축 후 다시 삽입할 AGENTS.md의 H2/H3 섹션 이름을 선택적으로 지정합니다. 설정하지 않거나 []로 설정하면 재삽입이 비활성화됩니다. 기존 기본 섹션 쌍을 활성화하려면 ["Session Startup", "Red Lines"]를 명시적으로 설정하세요.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`압축 후 인덱스 동기화`},help:{"v1-ekpjeq-6l":`압축 후 세션 메모리의 재인덱싱 모드를 제어합니다: "off", "async", "await"(기본값: "async"). 최신 상태를 확실하게 유지하려면 "await"를, 압축 지연 시간을 줄이려면 "async"를 사용하세요. "off"는 세션 메모리 동기화를 다른 곳에서 처리하는 경우에만 사용하세요.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`압축 제공자`},help:{"v1-kiwk91-86":`요약에 사용할 등록된 압축 제공자 플러그인의 ID입니다. 이 값이 설정되어 있고 해당 제공자가 등록되어 있으면 내장 summarizeInStages 파이프라인 대신 제공자의 summarize() 메서드를 호출합니다. 제공자에 오류가 발생하면 내장 기능으로 대체됩니다. 기본 내장 요약 기능을 사용하려면 설정하지 마세요.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`압축 품질 보호`},help:{"v1-u9ognp-4k":`safeguard 압축 요약의 품질 검사를 위한 재시도 설정입니다. safeguard 모드에서는 기본적으로 활성화됩니다. 요약 검사와 재생성을 건너뛰려면 enabled: false로 설정하세요.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`압축 품질 보호 활성화`},help:{"v1-1xk2vt3-36":`safeguard 압축의 요약 품질 검사와 재생성 재시도를 활성화합니다. 기본값: safeguard 모드에서 true.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`압축 품질 보호 최대 재시도 횟수`},help:{"v1-n7l46y-3y":`safeguard 요약 품질 검사에 실패한 후 재생성을 재시도하는 최대 횟수입니다. 추가 지연 시간과 토큰 비용을 제한하려면 작은 값을 사용하세요.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`압축 시 최근 대화 턴 보존`},help:{"v1-y34ihi-5k":`safeguard 요약 대상에서 제외하고 원문 그대로 유지할 최근 사용자/어시스턴트 대화 턴 수입니다(기본값: 3). 최근 대화 맥락을 정확하게 보존하려면 값을 높이고, 압축에 따른 절감 효과를 극대화하려면 값을 낮추세요.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`압축 사고 수준`},help:{"v1-1vafgaw-g1":`내장 OpenClaw 압축 요약에만 사용되는 사고 수준입니다. "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra", "inherit" 중에서 선택합니다. 기본값은 제공자의 압축 기본 설정을 따르며, 해당 설정이 없으면 "low"입니다. 네이티브 로컬 Ollama는 "off"를 우선 사용합니다. 세션 수준을 재사용하려면 "inherit"로 설정하세요. 명시적으로 지정한 설정은 제공자 기본값보다 우선하며, 선택한 수준은 실제 압축 모델 및 런타임이 지원하는 범위로 제한됩니다. 네이티브 Codex app-server 압축은 compact 요청에서 작업별 사고 수준 재정의를 지원하지 않으므로 이 설정을 무시하며, OpenClaw는 경고를 기록합니다.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`압축 제한 시간(초)`},help:{"v1-2bhn29-7m":`각 내장 압축 모델 요청에 적용되는 안전 제한 시간(초)입니다(기본값: 180). 다단계 압축에서는 순차 요청이 시작될 때마다 제한 시간이 갱신되므로 전체 압축에는 더 오래 걸릴 수 있습니다. 플러그인이 담당하는 압축에는 전체 작업에 하나의 제한 시간이 적용됩니다.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`컨텍스트 주입`},help:{"v1-u18x0-7u":`내장 런타임에서 작업 공간 부트스트랩 파일 주입을 제어합니다. "always"는 일반적인 주입을 사용하고(기본값), "continuation-skip"은 전체 부트스트랩이 기록된 턴 이후 조건에 맞는 후속 턴에서 주입을 건너뛰며, "never"는 주입을 비활성화합니다. CLI 기반 프롬프트 준비에는 영향을 주지 않습니다.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`기본 컨텍스트 한도`},help:{"v1-1coeez8-5d":`선택한 대용량 발췌문과 주입된 프롬프트 블록에 적용되는 에이전트별 컨텍스트 용량의 기본값입니다. 제한 없는 호출 경로를 다시 열지 않고도 읽기 및 주입 크기의 한도를 조정할 수 있습니다.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`기본 memory_get 최대 문자 수`},help:{"v1-1qb40qv-4v":`잘림 메타데이터와 이어보기 안내가 추가되기 전에 memory_get이 반환하는 기본 최대 문자 수입니다. 이전의 더 긴 발췌문과 비슷한 분량을 원하면 이 값을 늘리되, 적절한 상한을 유지하세요.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`압축 후 기본 최대 문자 수`},help:{"v1-64qo8g-5r":`압축 후 컨텍스트 갱신을 위해 내용을 삽입할 때 AGENTS.md에서 유지하는 기본 최대 문자 수입니다. 압축 후 복구 비용을 줄이려면 이 값을 낮추고, 더 긴 시작 지침이 필요한 에이전트에는 이 값을 높이세요.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`작업 디렉터리`},help:{"v1-1y8wlxn-6a":`에이전트 응답 실행을 위한 작업 디렉터리로, 워크스페이스 초기 설정 및 메모리 파일과는 별개입니다. 에이전트별 cwd와 세션 생성 시 지정된 cwd가 우선 적용됩니다. ~ 및 상대 경로를 지원하며, 별도의 cwd를 사용하려면 샌드박스 외부에서 실행해야 합니다.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`의사 결정 모델`},help:{"v1-7nd7ze-64":`타입이 지정된 선택, 점수, 불리언 확률을 위한 선택적 제공업체/모델입니다. 설정하지 않거나 비워 두면 의사 결정 호출이 비활성화됩니다. 지원 플러그인은 범위가 제한된 작업 근거를 이 제공업체에 전송하며, 채팅 및 유틸리티 모델은 변경되지 않습니다.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`내장 OpenClaw`},help:{"v1-1keek32-3k":`OpenClaw 세션에서 워크스페이스 로컬 에이전트 설정을 신뢰하고 적용하는 방식을 제어하는 내장 OpenClaw 실행기 보안 강화 설정입니다.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`사이버 정책 장애 조치`},help:{"v1-xvv6wl-2r":`내장 런타임에서 안전하게 재실행할 수 있는 OpenAI 사이버 정책 거부가 발생하면 Daybreak로 자동 에스컬레이션합니다.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`사이버 정책 장애 조치 대기 시간`},help:{"v1-16smtrl-25":`현재 세션에서 사용할 수 없는 에스컬레이션 대상을 건너뛰는 시간입니다.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`사이버 정책 장애 조치 모드`},help:{"v1-rzsd2b-2h":`자동 에스컬레이션을 활성화하거나("auto", 기본값), 제공자가 거부하면 그대로 종료합니다("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`사이버 정책 장애 조치 모델`},help:{"v1-1aaj8nn-1t":`자동 사이버 정책 에스컬레이션에 사용할 제공자/모델 대상입니다.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`내장 OpenClaw 실행 규약`},help:{"v1-1fch2ig-66":`내장 OpenClaw 실행 규약입니다. "default"는 표준 실행기 동작을 유지하며, "strict-agentic"은 지원되는 OpenAI/OpenAI Codex GPT-5 계열 실행에서 구조화된 계획 추적과 사용자에게 표시되지 않는 턴 복구를 활성화합니다.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`내장 OpenClaw 프로젝트 설정 정책`},help:{"v1-fdyy04-65":'내장 OpenClaw가 워크스페이스 로컬 `.openclaw/settings.json`을 처리하는 방식입니다. "sanitize"(기본값)는 shellPath/shellCommandPrefix를 제거하고, "ignore"는 프로젝트 설정을 완전히 비활성화하며, "trusted"는 프로젝트 설정을 그대로 적용합니다.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`실험적 에이전트 플래그`},help:{"v1-cvv5cl-2w":`실험적인 에이전트 기본 플래그입니다. 미리 보기 기능을 의도적으로 테스트하는 경우가 아니라면 꺼 두세요.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`경량 로컬 모델 모드 활성화(실험적)`},help:{"v1-gj06u6-7b":`browser, automations, message 등의 선택적 도구를 제한하는 고급 문제 해결용 재정의 설정입니다. 기본적으로 꺼져 있으며, 지원되는 로컬 런타임은 이 제한 없이 자동 도구 검색을 사용합니다. 명시적으로 허용된 도구와 필수 전달 도구는 유지됩니다.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`기본 에이전트 고속 모드`},help:{"v1-zv4y98-2z":`에이전트 루프의 기본 고속 모드 정책입니다("auto", true 또는 false). 개별 에이전트 항목의 설정이 우선 적용됩니다.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`하트비트 에이전트`},help:{"v1-1jynxej-3w":`에이전트별 하트비트 구성이 없을 때 백그라운드 하트비트 실행을 담당하는 에이전트입니다. 구성된 기본 라우팅을 유지하려면 설정하지 마세요.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`하트비트 다이렉트 메시지 정책`},help:{"v1-nhyxa9-41":`하트비트를 다이렉트 메시지/DM 채팅으로 전달할 수 있는지 제어합니다. "allow"(기본값)는 DM 전달을 허용하고, "block"은 다이렉트 메시지 대상 전송을 차단합니다.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`하트비트 시간 제한(초)`},help:{"v1-1se21py-5f":`하트비트 에이전트 턴이 중단되기 전까지 허용되는 최대 시간(초)입니다. 설정하지 않으면 agents.defaults.timeoutSeconds가 설정된 경우 해당 값을 사용하고, 그렇지 않으면 하트비트 주기를 사용하되 최대 600초로 제한합니다.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`사람처럼 응답하기 위한 최대 지연(ms)`},help:{"v1-vnmvli-1m":`사용자 지정 humanDelay의 최대 지연 시간(ms)입니다(기본값: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`사람처럼 응답하기 위한 최소 지연(ms)`},help:{"v1-5nrtr5-1l":`사용자 지정 humanDelay의 최소 지연 시간(ms)입니다(기본값: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`사람처럼 응답하기 위한 지연 모드`},help:{"v1-k7hyg3-1n":`블록 단위 응답의 지연 방식입니다("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`이미지 최대 크기(px)`},help:{"v1-vju8x-2u":`대화 기록이나 도구 결과의 이미지 페이로드를 정제할 때 적용되는 이미지 한 변의 최대 길이(픽셀)입니다(기본값: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`이미지 모델 대체 목록`},help:{"v1-1kgx5i9-1b":`우선순위순으로 나열된 대체 이미지 모델입니다(provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`이미지 모델`},help:{"v1-dstqyh-2c":`기본 모델이 이미지 입력을 지원하지 않을 때 사용하는 선택적 이미지 모델입니다(provider/model).`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`이미지 품질`},help:{"v1-1uyxc5s-6u":`이미지 도구의 미디어 압축 설정: "auto"는 제공업체/모델 제한과 이미지 수에 맞춰 조정하고, "efficient"는 토큰과 바이트를 절약하며, "balanced"는 현재의 중간 수준을 유지하고, "high"는 스크린샷과 문서 이미지의 세부 정보를 더 많이 보존합니다.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`이미지 생성 대체 모델`},help:{"v1-oljfk4-1m":`순서대로 사용할 대체 이미지 생성 모델 목록(provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`이미지 생성 모델`},help:{"v1-g4yw0h-2o":`공유 이미지 생성 기능에서 사용하는 선택적 이미지 생성 모델(provider/model)입니다.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`이미지 생성 제한 시간(ms)`},help:{"v1-9yesfj-31":`image_generate 호출에 대한 제공업체 요청의 기본 제한 시간(밀리초)입니다. 호출별 timeoutMs가 이 설정보다 우선합니다.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`음악 생성 대체 모델`},help:{"v1-wyg9xe-1m":`순서대로 사용할 대체 음악 생성 모델 목록(provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`음악 생성 모델`},help:{"v1-xs1e2h-2o":`공유 음악 생성 기능에서 사용하는 선택적 음악 생성 모델(provider/model)입니다.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`동영상 생성 대체 모델`},help:{"v1-wpbf1e-1m":`우선순위 순으로 나열된 대체 동영상 생성 모델(provider/model)입니다.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`동영상 생성 모델`},help:{"v1-hfmlbl-2o":`공유 동영상 생성 기능에서 사용하는 선택적 동영상 생성 모델(provider/model)입니다.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`동영상 생성 제한 시간(ms)`},help:{"v1-1bqj80s-4i":`video_generate 호출에 적용되는 기본 제공업체 요청 제한 시간(밀리초)입니다. 호출별 timeoutMs가 이 값보다 우선하며, 이 값은 제공업체가 지정한 기본값보다 우선합니다.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`대체 모델`},help:{"v1-t4djq2-24":`우선순위 순으로 나열된 대체 모델(provider/model)입니다. 기본 모델이 실패하면 사용됩니다.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`기본 모델`},help:{"v1-1i8a1v4-v":`기본 모델(provider/model)입니다.`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`모델 정책`},help:{"v1-z0txb7-2e":`모델 재정의에 대한 명시적 정책입니다. 모든 모델을 허용하려면 이 항목을 생략하거나 allow를 비워 두세요.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`허용된 모델`},help:{"v1-1fqace-3x":`모델 재정의에 허용되는 참조입니다. 별칭, 전체 "provider/model" 참조, "openai/*"와 같은 제공업체 와일드카드를 사용할 수 있습니다. 비워 두면 모든 모델이 허용됩니다.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`모델`},help:{"v1-13cvq23-4i":`구성된 모델 카탈로그와 모델별 설정입니다. 각 항목은 별칭, 매개변수, 런타임 메타데이터, Code Mode 재정의를 제공하며, 모델 재정의를 제한하지 않습니다.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`기본 에이전트 모델 런타임`},help:{"v1-6km9kx-41":`기본 에이전트의 모델별 런타임 정책(선택 사항)입니다. 에이전트 전체의 런타임을 설정하는 대신 모델별 런타임 예외를 지정할 때 사용하세요.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`기본 에이전트 모델 런타임 ID`},help:{"v1-1co96w7-4a":`기본 에이전트의 모델 런타임 ID입니다. "openclaw", "auto", "codex"와 같은 등록된 플러그인 하네스 ID 또는 "claude-cli"와 같은 지원되는 CLI 백엔드 별칭을 사용하세요.`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`코드 모드`},help:{"v1-rsdl5o-6x":`이 특정 공급자/모델에 대한 OpenClaw 코드 모드입니다. 켜짐은 강제로 활성화하고, 꺼짐은 비활성화하며, 기본값은 tools.codeMode.enabled를 상속합니다. 에이전트별 활성화 설정이 우선 적용됩니다. 선택된 런타임이나 Codex 기본 코드 모드는 변경하지 않습니다.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`모델 선택 범위`},help:{"v1-sj8owq-bl":`범위를 명시하지 않은 채팅 명령 및 Gateway 세션 모델 업데이트에 적용할 범위입니다. "session"(기본값)은 현재 세션만 변경하고, "agent"는 해당 에이전트의 기본 모델도 업데이트하며, "global"은 공유 agents.defaults.model 대체 모델도 업데이트합니다. 명시적인 범위 플래그가 우선 적용되며, 설정된 기본값을 변경하려면 소유자/관리자 권한이 필요합니다. Telegram 콜백 선택기와 내장 로컬 TUI는 계속 세션 범위로만 적용됩니다.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`PDF 최대 크기(MB)`},help:{"v1-1uig1dr-1u":`PDF 도구에서 허용하는 최대 PDF 파일 크기(메가바이트)입니다(기본값: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`PDF 최대 페이지 수`},help:{"v1-11na7hp-1y":`PDF 도구에서 처리할 최대 PDF 페이지 수입니다(기본값: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`PDF 대체 모델`},help:{"v1-89ebd8-19":`우선순위순으로 지정된 PDF 대체 모델입니다(provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF 모델`},help:{"v1-2ktkxt-2y":`PDF 분석 도구에 사용할 선택적 PDF 모델입니다(provider/model). 기본적으로 imageModel을 사용하며, 없으면 세션 모델을 사용합니다.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`저장소 루트`},help:{"v1-j3sh74-2h":`시스템 프롬프트의 런타임 줄에 표시할 선택적 저장소 루트입니다(자동 감지 결과를 재정의합니다).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`샌드박스 브라우저 CDP 소스 포트 범위`},help:{"v1-1jkowdc-2b":`컨테이너 경계의 CDP 인바운드 트래픽에 대한 선택적 CIDR 허용 목록입니다(예: 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`샌드박스 브라우저 네트워크`},help:{"v1-8m74ud-5w":`샌드박스 브라우저 컨테이너용 Docker 네트워크입니다(기본값: openclaw-sandbox-browser). 전용 기본 네트워크 또는 사용자 지정 브리지 네트워크를 사용하세요. 브라우저 제어에는 공개된 CDP 포트가 필요하므로 "none"은 지원되지 않습니다.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`샌드박스 Docker 컨테이너 네임스페이스 참여 허용`},help:{"v1-qm39de-4c":`샌드박스 Docker 네트워크 모드 container:<id>를 허용하는 위험한 비상용 재정의 설정입니다. 다른 컨테이너의 네임스페이스에 참여하므로 샌드박스 격리가 약화됩니다.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`샌드박스 Docker GPU`},help:{"v1-jj0yhw-4k":`--gpus에 전달할 선택적 Docker GPU 패스스루 값입니다. 예: "all" 또는 "device=GPU-uuid". NVIDIA Container Toolkit과 같은 호환 호스트 런타임이 필요합니다.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`레거시 세션 저장소 대상`},help:{"v1-1xkej6i-2g":`폐기된 main-agent 행과 고정 레거시 세션 저장소의 업그레이드 호환성을 위한 소유자입니다.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`레거시 세션 저장소 소유자`},help:{"v1-ommm7e-5w":`기본 마커 폐기 후 고정 레거시 세션 저장소에서 폐기된 main-agent 행 또는 범위가 지정되지 않은 행을 소유하는 에이전트입니다. 이전 소유자가 main도 유일한 에이전트도 아니었던 경우 업그레이드 중 자동으로 기록됩니다.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`agents.entries.*.skills를 생략한 에이전트가 상속하는 선택적 기본 스킬 허용 목록입니다. 스킬을 제한하지 않으려면 생략하고, 상속하는 에이전트에 스킬을 부여하지 않으려면 []로 설정하세요. 명시적으로 지정한 agents.entries.*.skills는 이 기본값과 병합되지 않고 기본값을 대체합니다.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`작업 공간 부트스트랩 생성 건너뛰기`},help:{"v1-kbstgw-5v":`작업 공간 부트스트랩 파일의 자동 생성을 건너뛰며, 기존 파일의 주입은 건너뛰지 않습니다. 내장 런타임에서 주입을 비활성화하려면 agents.defaults.contextInjection을 "never"로 설정하세요. 단, 에이전트별 설정으로 재정의할 수 있습니다.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`생략할 선택적 부트스트랩 파일`},help:{"v1-1j2z4yj-4c":`에이전트 작업 공간에 생성하지 않을 선택적 부트스트랩 파일입니다. 유효한 값: SOUL.md, USER.md, IDENTITY.md(HEARTBEAT.md도 허용되지만 아무 효과가 없습니다).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`시작 컨텍스트`},help:{"v1-1ugsihy-5o":`인수 없이 실행한 "/new" 및 "/reset"의 첫 턴에 런타임이 추가하는 사전 컨텍스트입니다. 모델이 무엇을 읽을지 결정하도록 하는 대신, 최근 일일 메모리 파일을 첫 프롬프트에 미리 로드할지 제어합니다.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`시작 컨텍스트 적용 대상`},help:{"v1-wav4a5-36":`인수 없이 실행하는 초기화 명령 중 시작 컨텍스트를 적용할 명령을 선택합니다. "new", "reset" 또는 둘 다 포함할 수 있습니다(기본값: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`시작 컨텍스트 일일 메모리 일수`},help:{"v1-4i5xcm-3p":`설정된 사용자 시간대의 오늘부터 거슬러 올라가며 로드할 날짜별 메모리 파일 수입니다(기본값: 오늘과 어제를 포함한 2개).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`시작 컨텍스트 활성화`},help:{"v1-1d5vz2u-4i":`인수 없이 세션을 초기화할 때 시작 사전 컨텍스트를 활성화합니다(기본값: true). 비활성화하면 런타임이 일일 메모리를 로드하지 않고 프롬프트만 사용하는 방식으로 돌아갑니다.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`시작 컨텍스트 파일당 최대 바이트 수`},help:{"v1-11cbian-41":`시작 컨텍스트를 구성할 때 일일 메모리 파일당 허용되는 최대 바이트 수입니다(기본값: 16384). 경계 안전성을 보장하는 이 읽기 한도를 초과하는 파일은 건너뜁니다.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`시작 컨텍스트 파일당 최대 문자 수`},help:{"v1-10z53s-2u":`로드된 각 일일 메모리 파일에서 시작 사전 컨텍스트에 유지할 최대 문자 수입니다(기본값: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`시작 컨텍스트 최대 총 문자 수`},help:{"v1-sf676u-54":`시작 프리루드에 로드된 모든 일별 메모리 파일에서 유지할 최대 총 문자 수입니다(기본값: 2800). 이 한도에 도달하면 추가 파일의 내용은 프리루드에서 잘립니다.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`하위 에이전트 위임 모드`},help:{"v1-pqewbk-5o":`프롬프트로만 적용되는 하위 에이전트 위임 강도입니다. 기본값은 각 에이전트의 기본 세션에서는 "prefer", 그 외에는 "suggest"입니다. "prefer"는 단순하지 않은 작업을 sessions_spawn을 통해 위임하도록 에이전트에 강하게 지시합니다.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`시스템 에이전트 대상`},help:{"v1-1wwimo9-34":`백그라운드 OpenClaw 시스템 에이전트 및 Custodian 추론과 범위가 지정되지 않은 일부 운영자 조회에 대한 대상 설정입니다.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`시스템 에이전트 소유자`},help:{"v1-15rvt92-8c":`백그라운드 시스템 에이전트 및 Custodian 질의에 사용할 모델과 자격 증명을 소유한 에이전트입니다. models.list, models.authStatus, skills.status, doctor.memory.status 또는 에이전트 소유 모델이나 인증 상태를 확인하는 infer CLI 명령에서 agentId 또는 --agent를 생략한 경우에도 사용됩니다. 요청에 명시된 agentId가 항상 우선합니다.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`입력 중 표시 간격(초)`},help:{"v1-1y701ox-42":`모든 에이전트의 입력 중 표시 유지 주기를 초 단위로 제어합니다. 값을 늘리면 입력 중 표시를 지원하는 모든 채널에서 업데이트 빈도가 줄어듭니다.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`입력 중 표시 모드`},help:{"v1-m2hvpw-3m":`에이전트의 입력 중 표시를 시작할 시점을 "never", "instant", "thinking", "message" 중에서 지정합니다. 에이전트별 typingMode 설정이 이 기본값보다 우선합니다.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`유틸리티 모델`},help:{"v1-1wg7h1a-7s":`제목 생성 및 진행 상황 안내와 같은 짧은 내부 작업에 사용할 저비용 모델(provider/model 또는 별칭)입니다. 선택 사항이며, 설정하지 않으면 기본 공급자가 지정한 소형 모델을 사용하고, 해당 모델이 없으면 기본 모델을 사용합니다. 유틸리티 라우팅을 비활성화하려면 빈 문자열로 설정하세요.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`대체 음성 모델`},help:{"v1-faazv4-1b":`우선순위순 대체 음성 모델(provider/model) 목록입니다.`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`음성 모델`},help:{"v1-1yeh3h4-2t":`음성 출력, 음성 텍스트 변환, 실시간 음성 기능에 사용할 음성 모델(provider/model)입니다. 선택 사항입니다.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`음성 시간 제한(ms)`},help:{"v1-1sbergs-32":`호출자가 시간 제한을 지원하는 경우 음성 모델 작업에 적용할 공급자 요청의 기본 시간 제한입니다. 단위는 밀리초입니다.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`작업 공간`},help:{"v1-1lssx8l-5w":`초기화 및 메모리 파일을 위한 기본 에이전트 작업 공간입니다. agents.defaults.cwd가 설정되지 않은 경우 작업 디렉터리로도 사용됩니다. 래퍼를 통해 실행할 때는 경로가 일관되게 해석되도록 이 값을 명시적으로 설정하세요.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`에이전트 목록`},help:{"v1-yurood-5l":`ID와 모델, 도구, 정체성, 작업 공간에 대한 선택적 재정의 설정이 포함된, 명시적으로 구성된 에이전트 목록입니다. 바인딩, 승인, 세션 라우팅이 일관되게 유지되도록 ID를 변경하지 마세요.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`레거시 에이전트 런타임`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`레거시 에이전트 런타임 ID`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`에이전트 부트스트랩 최대 문자 수`},help:{"v1-rsf1es-4j":`이 에이전트의 시스템 프롬프트에 삽입되는 각 작업 공간 부트스트랩 파일의 최대 문자 수를 에이전트별로 재정의합니다. 생략하면 agents.defaults.bootstrapMaxChars를 상속합니다.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`에이전트 부트스트랩 최대 총 문자 수`},help:{"v1-1bal68p-4y":`이 에이전트의 시스템 프롬프트에 삽입되는 모든 작업 공간 부트스트랩 파일의 최대 총 문자 수를 에이전트별로 재정의합니다. 생략하면 agents.defaults.bootstrapTotalMaxChars를 상속합니다.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`에이전트 컨텍스트 삽입`},help:{"v1-1j68ys8-50":`임베디드 런타임에서 작업 공간 부트스트랩 파일 주입을 재정의하는 에이전트별 설정입니다. 생략하면 agents.defaults.contextInjection을 상속합니다. CLI 기반 프롬프트 준비에는 영향을 주지 않습니다.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`에이전트 컨텍스트 제한`},help:{"v1-f1qxq8-3c":`주요 컨텍스트 할당량 설정을 에이전트별로 재정의하는 선택적 설정입니다. 생략된 필드는 agents.defaults.contextLimits를 상속합니다.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`에이전트 memory_get 최대 문자 수`},help:{"v1-12hlmsv-1v":`memory_get의 기본 최대 문자 수 할당량을 에이전트별로 재정의합니다.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`에이전트 압축 후 최대 문자 수`},help:{"v1-15s0npd-1w":`압축 후 AGENTS.md 발췌문 분량 제한을 에이전트별로 재정의합니다.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`에이전트 작업 디렉터리`},help:{"v1-mv43ak-6a":`이 에이전트의 응답 실행에 사용할 작업 디렉터리입니다. agents.defaults.cwd보다 우선하지만 세션 생성 시 지정된 cwd보다 우선하지는 않습니다. 부트스트랩 및 메모리 파일은 작업 공간에 유지됩니다. ~ 및 상대 경로를 지원합니다. 별도의 cwd를 사용하려면 샌드박스 없이 실행해야 합니다.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`에이전트 의사 결정 모델`},help:{"v1-1mih8bf-3j":`에이전트별 의사 결정 모델입니다. 설정하지 않으면 agents.defaults.decisionModel을 상속하며, 빈 문자열로 설정하면 이 에이전트의 의사 결정 호출이 비활성화됩니다.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`에이전트 내장 OpenClaw`},help:{"v1-uoomza-4b":`선택적 에이전트별 내장 OpenClaw 재정의 설정입니다. 전역 기본값을 변경하지 않고 특정 에이전트에 더 엄격한 GPT-5 실행 동작을 적용할 때 사용합니다.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`에이전트 내장 OpenClaw 실행 계약`},help:{"v1-1d1jaoi-7k":`선택적 에이전트별 내장 OpenClaw 실행 계약 재정의 설정입니다. 지원되는 OpenAI/OpenAI Codex GPT-5 계열 실행에서 해당 에이전트의 구조화된 계획 추적 및 비표시 턴 복구를 활성화하려면 "strict-agentic"으로 설정하고, 표준 실행기 동작을 상속하려면 "default"로 설정합니다.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`에이전트 실험적 플래그`},help:{"v1-1r06jov-2a":`에이전트별 실험적 플래그입니다. 생략된 필드는 agents.defaults.experimental을 상속합니다.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`에이전트 경량 로컬 모델 모드`},help:{"v1-5o3tgx-58":`경량 로컬 모델 모드를 위한 에이전트별 문제 해결용 재정의 설정입니다. 모든 에이전트의 도구를 줄이지 않고, 선택적 도구를 제한하여 확인된 모델 오류를 해결할 수 있는 경우에만 활성화하세요.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`에이전트 빠른 모드 기본값`},help:{"v1-1ujydjc-3o":`에이전트별 빠른 모드 기본값(선택 사항: "auto", true 또는 false)입니다. 메시지별 또는 세션별 빠른 모드 재정의가 설정되지 않은 경우 적용됩니다.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`하트비트 다이렉트 메시지 정책`},help:{"v1-11gl9l0-41":`하트비트 다이렉트 메시지/DM 전송 정책의 에이전트별 재정의입니다. DM이 아닌 대상으로만 하트비트 알림을 보내야 하는 에이전트에는 "block"을 사용하세요.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`하트비트 제한 시간(초)`},help:{"v1-kdetv4-6s":`하트비트 에이전트 턴이 중단되기 전까지 허용되는 에이전트별 최대 시간(초)입니다. 설정하지 않으면 병합된 하트비트 제한 시간을 상속합니다. 해당 값이 없으면 agents.defaults.timeoutSeconds가 설정된 경우 그 값을 사용하고, 그렇지 않으면 하트비트 주기를 사용하되 최대 600초로 제한합니다.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`아이덴티티 아바타`},help:{"v1-pzp9gr-1t":`에이전트 아바타(작업 공간 기준 상대 경로, http(s) URL 또는 data URI)입니다.`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`에이전트 모델 정책`},help:{"v1-17d5je8-2r":`에이전트별 모델 재정의 정책입니다. 명시적인 허용 목록은 이 에이전트의 기본 정책을 대체합니다.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`허용된 에이전트 모델`},help:{"v1-v1ueke-5b":`이 에이전트에서 재정의에 사용할 수 있는 모델 참조입니다. 별칭, 전체 "provider/model" 참조, "provider/*" 또는 "provider/namespace/*"처럼 끝에 와일드카드가 붙는 접두사를 허용합니다. 비워 두면 모든 모델을 허용합니다.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`에이전트 모델 재정의`},help:{"v1-nld1vq-1v":`전체 provider/model ID를 키로 사용하는 에이전트별 모델 카탈로그 재정의 설정입니다.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`에이전트 모델 런타임`},help:{"v1-7b59y-3s":`이 에이전트의 모델별 런타임 정책으로, 선택 사항입니다. 에이전트 전체의 런타임을 설정하는 대신 에이전트별 모델 예외를 지정할 때 사용하세요.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`에이전트 모델 런타임 ID`},help:{"v1-1ckfc39-46":`에이전트별 모델 런타임 ID: "openclaw", "auto", "codex"와 같은 등록된 플러그인 하네스 ID 또는 "claude-cli"와 같은 지원되는 CLI 백엔드 별칭입니다.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`코드 모드`},help:{"v1-91zu7f-7m":`이 에이전트와 정확히 일치하는 provider/model에 대한 OpenClaw 코드 모드입니다. 켜기는 강제로 활성화하고, 끄기는 비활성화하며, 기본값은 에이전트 활성화 설정, 공유 모델 재정의 설정, tools.codeMode.enabled 순으로 상속합니다. 선택된 런타임이나 Codex 네이티브 코드 모드는 변경하지 않습니다.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`에이전트 추론 기본값`},help:{"v1-13ly0xf-3m":`에이전트별 기본 추론 표시 설정(on|off|stream)으로, 선택 사항입니다. 메시지별 또는 세션별 추론 재정의 설정이 없을 때 적용됩니다.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`에이전트 런타임`},help:{"v1-avjgkf-3l":`이 에이전트의 런타임 설명자로, 선택 사항입니다. 기본 OpenClaw 실행에는 embedded를, 외부 ACP 하네스 기본값에는 acp를 사용하세요.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`에이전트 ACP 런타임`},help:{"v1-91zvdk-3i":`runtime.type=acp일 때 이 에이전트의 ACP 런타임 기본값입니다. 대화별로 바인딩 수준의 ACP 재정의 설정이 여전히 우선 적용됩니다.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`에이전트 ACP 하네스 에이전트`},help:{"v1-1pm98vp-37":`이 OpenClaw 에이전트에 사용할 ACP 하네스 에이전트 ID입니다(선택 사항, 예: codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`에이전트 ACP 백엔드`},help:{"v1-1u3cdsg-2n":`이 에이전트의 ACP 세션에 사용할 ACP 백엔드 재정의 설정입니다(선택 사항, 미설정 시 전역 acp.backend 사용).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`에이전트 ACP 작업 디렉터리`},help:{"v1-d9p9rf-1t":`이 에이전트의 ACP 세션에 사용할 기본 작업 디렉터리입니다(선택 사항).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`에이전트 ACP 모드`},help:{"v1-yatuk4-21":`이 에이전트의 기본 ACP 세션 모드입니다(선택 사항, persistent 또는 oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`에이전트 런타임 유형`},help:{"v1-139fbk6-2r":`이 에이전트의 런타임 유형: "embedded"(기본 OpenClaw 런타임) 또는 "acp"(ACP 하네스 기본값).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`에이전트 샌드박스 브라우저 CDP 소스 범위`},help:{"v1-1q1qyso-1d":`CDP 소스 CIDR 허용 목록의 에이전트별 재정의 설정입니다.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`에이전트 샌드박스 브라우저 네트워크`},help:{"v1-13bdfww-4c":`샌드박스 브라우저 Docker 네트워크의 에이전트별 재정의 설정입니다. 브리지 네트워크를 사용하세요. 브라우저 제어에는 외부에 공개된 CDP 포트가 필요하므로 "none"은 지원되지 않습니다.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`에이전트 샌드박스 Docker 컨테이너 네임스페이스 참여 허용`},help:{"v1-1xtnseb-2i":`샌드박스 Docker 네트워크 모드에서 컨테이너 네임스페이스 참여를 허용하는 위험한 에이전트별 재정의 설정입니다.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`에이전트 샌드박스 Docker GPU`},help:{"v1-1kek1n2-1t":`샌드박스 컨테이너의 Docker GPU 패스스루에 대한 에이전트별 재정의 설정입니다.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`에이전트 스킬 필터`},help:{"v1-igchue-6v":`이 에이전트에서 허용할 스킬 목록으로, 선택 사항입니다. 생략하면 agents.defaults.skills가 설정된 경우 이를 상속하며, 그렇지 않으면 스킬에 제한이 적용되지 않습니다. 스킬을 사용하지 않으려면 []로 설정하세요. 목록을 명시하면 상속된 기본값과 병합하지 않고 완전히 대체합니다.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`에이전트 Skills 제한`},help:{"v1-1sv10v9-4y":`스킬 하위 시스템의 사용 한도에 대한 선택적 에이전트별 재정의 설정입니다. 별도의 범용 컨텍스트 제한 경로를 추가하지 않고 에이전트에 다른 스킬 프롬프트 한도를 적용해야 할 때 사용하세요.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`에이전트 Skills 프롬프트 최대 문자 수`},help:{"v1-dys63y-52":`에이전트별 스킬 프롬프트 문자 수 한도 재정의입니다. 동일한 한도를 contextLimits를 통해 적용하는 대신 기존 skills.limits.maxSkillsPromptChars 경로를 확장합니다.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`하위 에이전트 위임 모드`},help:{"v1-1rkgh6p-4s":`에이전트별 하위 에이전트 위임 강도 재정의입니다. 생략하면 이 에이전트의 기본 세션에서는 "prefer"를, 그 외에는 "suggest"를 사용합니다. 명시적으로 설정한 "prefer" 또는 "suggest"가 항상 우선합니다.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`에이전트 기본 사고 수준`},help:{"v1-173q7vy-43":`에이전트별 기본 사고 수준으로, 선택 사항입니다. 메시지별 또는 세션별 재정의가 설정되지 않은 경우 이 에이전트에 대해 agents.defaults.thinkingDefault를 재정의합니다.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`에이전트 도구 허용 목록 추가 항목`},help:{"v1-1550ui9-46":`전역 및 프로필 정책에 추가로 적용되는 에이전트별 도구 허용 목록입니다. 특수 목적 에이전트의 권한이 의도치 않게 확대되지 않도록 범위를 좁게 유지하세요.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`제공업체별 에이전트 도구 정책`},help:{"v1-mthxv9-4t":`채널 범위의 기능 제어를 위한 에이전트별 제공업체별 도구 정책 재정의입니다. 단일 에이전트가 다른 제공업체보다 특정 제공업체에서 더 엄격한 제한을 필요로 할 때 사용하세요.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`에이전트 코드 모드`},help:{"v1-118t8u5-65":`에이전트별 Code Mode 옵션입니다. enabled를 명시적으로 설정하면 공유 모델 및 전역 활성화 기본값보다 우선하며, 에이전트별 모델의 codeMode 재정의가 최우선으로 적용됩니다. 다른 옵션은 활성화 여부를 변경하지 않고 tools.codeMode 위에 병합됩니다.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`에이전트 실행 제한 시간(초)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`에이전트 GitHub CLI ID 재정의`},help:{"v1-mjwdh4-38":`이 에이전트의 관리형 GitHub CLI ID 및 Git 작성자 정보를 완전히 재정의합니다. 생략하면 시스템 ID를 상속합니다.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`에이전트 Git 작성자 이메일`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`에이전트 Git 작성자 이름`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`에이전트 GitHub 자격 증명 유형`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`에이전트 GitHub 프로필 버전`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`에이전트 메시지 작업 허용 목록`},help:{"v1-1g5gov3-67":`message 도구의 에이전트별 메시지 작업 허용 목록입니다. 공개 샌드박스 에이전트에는 ["send"]와 같은 최소 목록을 설정하여 읽기, 수정, 삭제, 반응 및 기타 제공업체별 메시지 작업이 숨겨지고 차단되도록 하세요.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`에이전트 컨텍스트 간 메시징(제공업체 간)`},help:{"v1-pehesn-49":`서로 다른 제공업체 간 전송에 대한 에이전트별 재정의 설정입니다. 전역 설정을 상속합니다(기본값: true). 이 에이전트의 제공업체 간 메시지 전송을 차단하려면 false로 설정하세요.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`에이전트의 컨텍스트 간 메시지 전송(동일 제공업체)`},help:{"v1-s9u09h-4t":`동일한 제공업체의 다른 대화로 메시지를 전송할 때 적용되는 에이전트별 보호 설정입니다. 공개 에이전트가 현재 대화에서만 메시지를 보내도록 하려면 이 설정과 allowAcrossProviders를 모두 false로 설정하세요.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`에이전트 도구 프로필`},help:{"v1-1du76ix-57":`특정 에이전트에 다른 기본 기능 구성이 필요한 경우 도구 프로필 선택을 재정의하는 에이전트별 설정입니다. 에이전트 간 정책 차이가 의도에 맞고 검토 가능한 상태로 유지되도록 제한적으로 사용하세요.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`에이전트 스웜`},help:{"v1-420ljs-2c":`에이전트별 스웜 재정의 설정입니다. 값은 최상위 tools.swarm 구성에 병합되며 기존 값보다 우선 적용됩니다.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`에이전트 입력 표시 모드`},help:{"v1-oxir52-2e":`다른 에이전트를 변경하지 않고 특정 에이전트의 기본 입력 표시 시작 정책을 재정의합니다.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`에이전트 유틸리티 모델`},help:{"v1-1v9oskz-2z":`짧은 내부 작업에 사용할 에이전트별 유틸리티 모델 재정의 설정입니다(선택 사항). agents.defaults.utilityModel을 재정의합니다.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`에이전트 소유권 세대`},help:{"v1-m2hp61-8g":`다중 에이전트 소유권 세대를 나타내는 영구 마커입니다. "explicit"은 앰비언트 채널, 하트비트, 시스템 에이전트 자문, Talk, cron 및 별도 맥락 없는 CLI 작업에서 해당 접점의 소유자를 확인해야 하며, 확인하지 못하면 작업을 차단해야 함을 의미합니다. OpenClaw는 에이전트 집합을 생성하거나 마이그레이션할 때 이 마커를 자동으로 기록합니다. 에이전트가 하나뿐이면 생략하세요.`}},approvals:{label:{"v1-1m405m7-9":`승인`},help:{"v1-4y3in-5w":`exec 및 플러그인 승인 요청을 원래 세션 외부의 채팅 대상으로 전달하기 위한 승인 라우팅 설정입니다. 운영자가 별도 경로로 승인 요청을 확인해야 하는 경우가 아니면 비활성화 상태로 유지하세요.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`exec 승인 전달`},help:{"v1-1r2mozk-5v":`활성화 여부, 라우팅 모드, 필터, 명시적 대상 등 exec 승인 전달 동작을 설정합니다. 승인 요청을 원래 스레드뿐 아니라 운영 채널에도 보내야 하는 경우 여기에서 구성하세요.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`승인 에이전트 필터`},help:{"v1-xbuhd3-5i":'승인 요청을 전달할 에이전트 ID의 선택적 허용 목록입니다. 예: `["primary", "ops-agent"]`. 전달의 영향 범위를 제한하고 관련 없는 에이전트에 대한 채널 알림을 방지하는 데 사용하세요.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`exec 승인 전달 활성화`},help:{"v1-1t0whe8-5s":`exec 승인 요청을 구성된 전달 대상으로 보내도록 활성화합니다(기본값: false). 위험이 낮은 환경에서는 비활성화 상태로 유지하고, 승인 담당자가 채널에서 요청을 확인해야 하는 경우에만 활성화하세요.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`승인 전달 모드`},help:{"v1-1dedfo4-69":`승인 요청을 보낼 위치를 제어합니다. "session"은 원래 채팅을, "targets"는 구성된 대상을 사용하며, "both"는 두 경로 모두로 전송합니다. 기본적으로 "session"을 사용하고 운영 워크플로에 중복 전달이 필요한 경우에만 확장하세요.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`승인 세션 필터`},help:{"v1-smeg8e-5u":'부분 문자열 또는 정규식 형태의 패턴으로 일치 여부를 확인하는 선택적 세션 키 필터입니다. 예: `["discord:", "^agent:ops:"]`. 의도한 승인 컨텍스트만 공유 대상으로 전달되도록 범위가 좁은 패턴을 사용하세요.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`승인 전달 대상`},help:{"v1-17ah848-5u":`전달 모드에 대상이 포함될 때 사용하는 명시적 전송 대상이며, 각 대상에는 채널 및 목적지 세부 정보가 포함됩니다. 대상 목록은 최소 권한 원칙에 따라 관리하고, 광범위한 전달을 활성화하기 전에 각 목적지를 검증하세요.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`승인 대상 계정 ID`},help:{"v1-16zopng-5e":`여러 계정이 설정된 채널에서 특정 계정 컨텍스트를 통해 승인을 전달해야 할 때 사용하는 선택적 계정 선택자입니다. 대상 채널에 여러 계정 ID가 구성된 경우에만 사용하세요.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`승인 대상 채널`},help:{"v1-ji1igl-59":`승인 전달에 사용하는 채널/제공자 ID입니다. 예: discord, slack 또는 플러그인 채널 ID. 알 수 없는 경로로 인해 승인 전달이 알림 없이 실패하지 않도록 유효한 채널 ID만 사용하세요.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`승인 대상 스레드 ID`},help:{"v1-1axynw7-59":`전달된 승인을 스레드로 수신할 수 있는 채널에서 사용하는 선택적 스레드/주제 대상입니다. 승인 관련 메시지가 기본 채널이 아닌 운영 스레드 내에 머물도록 하려면 이 설정을 사용하세요.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`승인 대상 목적지`},help:{"v1-1ijng7e-5n":`대상 채널 내의 목적지 식별자입니다(제공업체에 따라 채널 ID, 사용자 ID 또는 스레드 루트). 채널 연동마다 목적지 형식이 다르므로 제공업체별로 의미를 확인하세요.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`플러그인 승인 전달`},help:{"v1-1m6pzxv-6b":`활성화 여부, 라우팅 모드, 필터, 명시적 대상을 포함한 플러그인 승인 전달 동작을 설정합니다. exec 승인 전달과는 독립적입니다. 플러그인 승인 요청을 운영 채널로 보내야 할 때 여기에서 구성하세요.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`플러그인 승인 에이전트 필터`},help:{"v1-jb1bra-4b":'플러그인 승인 전달이 허용되는 에이전트 ID의 선택적 허용 목록입니다. 예: `["primary", "ops-agent"]`. 전달의 영향 범위를 제한하려면 이 설정을 사용하세요.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`플러그인 승인 전달`},help:{"v1-1ntctaf-3v":`구성된 전달 목적지로 플러그인 승인 요청을 전달하도록 활성화합니다(기본값: false). approvals.exec.enabled와는 독립적입니다.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`플러그인 승인 전달 모드`},help:{"v1-1h62vy4-3z":`플러그인 승인 요청을 보낼 위치를 제어합니다. "session"은 원래 채팅을, "targets"는 구성된 대상을 사용하며, "both"는 두 경로 모두로 보냅니다.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`플러그인 승인 세션 필터`},help:{"v1-1eppxmt-57":'부분 문자열 또는 정규식 스타일 패턴으로 일치 여부를 확인하는 선택적 세션 키 필터입니다. 예: `["discord:", "^agent:ops:"]`. 의도한 승인 컨텍스트만 전달되도록 범위가 좁은 패턴을 사용하세요.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`플러그인 승인 전달 대상`},help:{"v1-o92qze-3k":`플러그인 승인 전달 모드에 대상이 포함된 경우 사용하는 명시적 전달 대상입니다. 각 대상에는 채널과 목적지 세부 정보가 포함됩니다.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`플러그인 승인 대상 계정 ID`},help:{"v1-1wf3lqn-3j":`다중 계정 채널 설정에서 플러그인 승인을 특정 계정 컨텍스트를 통해 전달해야 할 때 사용하는 선택적 계정 선택자입니다.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`플러그인 승인 대상 채널`},help:{"v1-1mzhzi9-34":`플러그인 승인 전달에 사용하는 채널/제공업체 ID입니다. 예: discord, slack 또는 플러그인 채널 ID.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`플러그인 승인 대상 스레드 ID`},help:{"v1-1scaw9c-2v":`플러그인 승인을 스레드로 전달할 수 있는 채널에서 사용하는 선택적 스레드/주제 대상입니다.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`플러그인 승인 대상 목적지`},help:{"v1-sh5te1-31":`대상 채널 내 목적지 식별자입니다(제공업체에 따라 채널 ID, 사용자 ID 또는 스레드 루트).`}},attachments:{label:{"v1-8925gh-b":`첨부 파일`},help:{"v1-1xvgkss-40":`미디어를 영구 저장하는 제공업체와 도구 전반에 공유되는 최상위 보존 동작입니다. 일반 임시 저장 미디어를 일정 시간 내에 정리해야 하는 경우 ttlHours를 사용하세요.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`첨부 파일 보존 TTL(시간)`},help:{"v1-1g90day-9e":`일반 mtime 정리 작업이 처리하는 저장된 미디어의 선택적 보존 기간(시간)입니다. 설정하지 않으면 해당 정리 작업이 비활성화됩니다. 24(1일) 또는 168(7일) 같은 값을 설정하면 오래된 임시 저장 미디어를 주기적으로 삭제합니다. 관리되는 발신 미디어(채팅에서 생성된 첨부 파일)는 제외되며, SQLite 및 대화 기록을 고려하는 별도의 보존 정책을 따릅니다.`}},audio:{label:{"v1-11wczsp-5":`오디오`}},auth:{label:{"v1-5xz433-4":`인증`},help:{"v1-1eu3aud-5c":`여러 프로필의 제공업체 자격 증명과 재시도 대기 시간 기반 장애 조치 순서에 사용되는 인증 프로필의 루트 설정입니다. 자동 장애 조치 동작을 추적하고 검토할 수 있도록 프로필을 최소한으로 유지하고 명확하게 설정하세요.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`인증 프로필 순서`},help:{"v1-1x6kknp-1w":`제공업체별로 순서가 지정된 인증 프로필 ID입니다(자동 장애 조치에 사용).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`인증 프로필`},help:{"v1-kzoqcn-1j":`이름이 지정된 인증 프로필입니다(제공업체 + 모드 + 선택적 이메일).`}},bindings:{label:{"v1-1hcih9f-8":`바인딩`},help:{"v1-y7hrzb-4i":`라우팅 및 영구 ACP 대화 소유권을 위한 최상위 바인딩 규칙입니다. 일반 라우팅에는 type=route를, 영구 ACP 하네스 바인딩에는 type=acp를 사용하세요.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`ACP 바인딩 재정의`},help:{"v1-1t4lisi-44":`bindings[].type=acp에 대한 선택적 바인딩별 ACP 재정의 설정입니다. 이 계층은 일치하는 대화에 대해 agents.entries.*.runtime.acp 기본값을 재정의합니다.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`ACP 바인딩 백엔드`},help:{"v1-rsrbkp-2x":`이 바인딩의 ACP 백엔드 재정의 설정입니다(설정하지 않으면 에이전트 런타임 ACP 백엔드를 사용하고, 그다음으로 전역 acp.backend를 사용).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`ACP 바인딩 작업 디렉터리`},help:{"v1-ngpkj0-1y":`이 바인딩에서 생성된 ACP 세션에 적용할 작업 디렉터리 재정의 값입니다.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`ACP 바인딩 레이블`},help:{"v1-azce82-23":`이 바인딩된 대화의 ACP 상태 및 진단에 사용할 알아보기 쉬운 레이블입니다.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`ACP 바인딩 모드`},help:{"v1-cgq8xv-1v":`이 바인딩에 적용할 ACP 세션 모드 재정의 값입니다(persistent 또는 oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`바인딩 에이전트 ID`},help:{"v1-17ra0cl-4m":`해당 바인딩의 일치 규칙이 충족되면 트래픽을 수신하는 대상 에이전트 ID입니다. 런타임에 라우팅이 실패하지 않도록 유효하게 구성된 에이전트 ID만 사용하세요.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`바인딩 일치 규칙`},help:{"v1-sc1w2e-51":`바인딩을 적용할 시점을 결정하는 일치 규칙 객체로, 채널과 선택적 계정/피어 제약 조건을 포함합니다. 다른 컨텍스트에서 에이전트가 의도치 않게 제어권을 가져가지 않도록 규칙의 범위를 좁게 유지하세요.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`바인딩 계정 ID`},help:{"v1-1d209g7-56":`여러 계정을 사용하는 채널 구성에서 바인딩이 하나의 계정에만 적용되도록 하는 선택적 계정 선택자입니다. 경로에 계정 범위 지정이 필요한 경우 사용하고, 그렇지 않으면 설정하지 마세요.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`바인딩 채널`},help:{"v1-d22m5-54":"이 바인딩이 적용되는 채널/제공자 식별자입니다. 예를 들어 `telegram`, `discord` 또는 플러그인 채널 ID를 사용할 수 있습니다. 바인딩 평가가 안정적으로 작동하도록 구성된 채널 키를 정확히 사용하세요."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`바인딩 길드 ID`},help:{"v1-jzzfj1-4x":`다중 서버 배포 환경에서 바인딩을 평가할 때 적용하는 선택적 Discord 스타일 길드/서버 ID 제약 조건입니다. 동일한 피어 식별자가 서로 다른 길드에 나타날 수 있는 경우 사용하세요.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`바인딩 피어 매칭`},help:{"v1-gcjxff-4i":`피어 유형과 피어 ID를 포함하여 특정 대화를 매칭하는 선택적 조건입니다. 하나의 개인 대화/그룹/채널 대상만 에이전트에 고정해야 할 때 사용하세요.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`바인딩 피어 ID`},help:{"v1-86fbh7-4b":`피어 매칭에 사용하는 대화 식별자로, 제공업체의 채팅 ID, 채널 ID 또는 그룹 ID 등이 해당합니다. 알림 없이 매칭이 실패하는 것을 방지하려면 정확히 입력하세요.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`바인딩 피어 유형`},help:{"v1-uufscp-4x":`피어 대화 유형: "direct", "group", "channel" 또는 기존 "dm"(direct의 사용 중단 예정 별칭)입니다. 새 설정에는 "direct"를 권장하며, kind가 채널의 의미와 일치하도록 설정하세요.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`바인딩 역할`},help:{"v1-6s891m-4k":`채팅 컨텍스트에 역할을 연결하는 제공업체에서 사용하는 선택적 역할 기반 필터 목록입니다. 권한이 높은 역할이나 운영 역할의 트래픽을 전문 에이전트로 라우팅할 때 사용하세요.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`바인딩 팀 ID`},help:{"v1-hh9ps2-48":`채팅 범위를 팀 단위로 지정하는 제공업체에서 사용하는 선택적 팀/워크스페이스 ID 제약 조건입니다. 바인딩을 하나의 워크스페이스 컨텍스트로 한정해야 할 때 추가하세요.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`바인딩 세션`},help:{"v1-x325l2-4v":`이 바인딩과 일치하는 대화에 적용할 선택적 경로 세션 재정의입니다. 특정 경로에서 동일한 에이전트를 유지하되 세션 연속성을 별도로 분리해야 할 때 사용하세요.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`바인딩 세션 DM 범위`},help:{"v1-10sg3xw-4s":`이 경로 바인딩에 적용할 선택적 DM 세션 범위 재정의입니다. 예를 들어 전역 session.dmScope="main"을 유지하면서 선택한 직접 대화 상대에는 "per-account-channel-peer"를 사용할 수 있습니다.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`바인딩 세션 그룹 범위`},help:{"v1-1ys2u7k-6n":`이 경로 바인딩에 적용할 선택적 그룹/채널 세션 범위 재정의입니다. "per-group"은 일치하는 대화방을 별도로 유지하며, dmScope와 관계없이 에이전트의 메인 세션이 백그라운드에서 이를 관찰하도록 합니다. "main"은 해당 대화방의 컨텍스트를 메인 세션에 병합하므로 관찰이 필요하지 않습니다.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`바인딩 유형`},help:{"v1-172mhtk-3o":`바인딩 종류입니다. 일반 라우팅에는 "route"를 사용하고(기존 경로 항목에서는 생략 가능), 영구 ACP 대화 바인딩에는 "acp"를 사용하세요.`}},broadcast:{label:{"v1-awqjh0-j":`에이전트 그룹 스레드`},help:{"v1-1tz72sr-6b":`에이전트 그룹 스레드를 사용하면 하나의 수신 대화에서 구성된 여러 에이전트를 각각 별도의 세션으로 실행할 수 있습니다. 채널이 명시된 항목은 제한된 횟수의 후속 라운드를 지원하며, 기존 WhatsApp 피어 배열은 단일 패스 동작을 유지합니다.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`에이전트 그룹 참여자 및 옵션`},help:{"v1-1b63zmt-7d":`채널이 명시된 피어 ID(예: "telegram:-100123")를 사용하여 에이전트 ID 배열 또는 agents, mentionGating, maxRounds, maxTurns를 포함하는 엄격한 형식의 객체를 구성하세요. 채널이 명시된 항목은 기존 WhatsApp 피어 키보다 우선하며, 최대 16개의 에이전트를 허용합니다.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`에이전트 그룹 참여자`},help:{"v1-g5o0ky-43":`agents.entries에 정의된 참여 에이전트 ID입니다(최대 16개). 각 참여자는 이 채널, 계정, 대화 및 스레드에 대해 별도의 세션을 사용합니다.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`에이전트 그룹 최대 라운드 수`},help:{"v1-i6v4jc-5a":`첫 라운드를 포함한 수신 메시지당 최대 라운드 수입니다(정수: 1–4, 기본값: 1). 후속 라운드에서는 다른 참여자의 응답을 작성자 정보와 함께 제한된 범위 내에서 공유하며, 모든 참여자가 응답을 건너뛰면 중단됩니다.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`에이전트 그룹 최대 턴 수`},help:{"v1-1kiv8dy-72":`모든 라운드에 걸친 수신 메시지당 최대 참여자 턴 수입니다(정수: 1–32, 기본값: agents.length). 병렬 실행 전에 슬롯을 예약합니다. 이 제한은 에이전트 턴 수에 적용되며, 실제 메시지 청크 수나 도구 전송 횟수에는 적용되지 않습니다. 재시작 후에는 이전 실행의 한도 사용 상태가 이어지지 않습니다.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`에이전트 그룹 멘션 기반 선택`},help:{"v1-uay9zu-5u":`명시적으로 @멘션된 참여자가 있으면 해당 참여자만 선택하고, 없으면 모든 참여자를 실행합니다(기본값: true). 이름만 입력하거나 이모지를 사용하면 참여자가 선택되지 않습니다. 채널 허용 목록과 참여 허용 규칙은 계속 적용됩니다.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`에이전트 그룹 실행 전략`},help:{"v1-p4k9hu-4q":`참여자 실행 순서입니다. "parallel"(기본값)은 에이전트를 동시에 실행하고, "sequential"은 설정된 순서대로 실행합니다. 각 라운드가 완료된 후 다음 라운드가 시작됩니다.`}},browser:{label:{"v1-13dzmen-7":`브라우저`},help:{"v1-5b74wi-5l":`로컬 또는 원격 CDP 연결, 프로필 라우팅, 스크린샷/스냅샷 동작을 위한 브라우저 런타임 설정입니다. 자동화 워크플로에 맞춤형 브라우저 전송 설정이 필요한 경우가 아니면 기본값을 유지하세요.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`시스템 프로필 가져오기 허용`},help:{"v1-1lsvlxw-5w":`macOS 호스트가 로컬 Chrome 계열 시스템 프로필의 쿠키를 관리형 OpenClaw 브라우저 프로필로 가져올 수 있도록 허용합니다. 브라우저 프로필 쿠키 가져오기와 이에 따른 macOS 키체인 동의 메시지 표시를 방지하려면 이 설정을 비활성화하세요.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`브라우저 연결 전용 모드`},help:{"v1-xaw7xm-4s":`로컬 브라우저 프로세스를 시작하지 않고 기존 브라우저에 연결만 하도록 브라우저 모드를 제한합니다. 모든 브라우저 세션이 원격 CDP 제공업체를 통해 외부에서 관리되는 경우 사용하세요.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`브라우저 CDP URL`},help:{"v1-2n72jb-65":`외부에서 관리되는 브라우저 인스턴스에 연결하는 데 사용하는 CDP/DevTools 엔드포인트 URL입니다. 중앙 집중식 브라우저 호스트, 터널 또는 기존 세션 연결에 사용하고, URL 접근은 신뢰할 수 있는 네트워크 경로로 제한하세요.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`브라우저 기본 프로필`},help:{"v1-a6xo96-52":`호출자가 프로필을 명시적으로 선택하지 않을 때 선택되는 기본 브라우저 프로필 이름입니다. 다른 컨텍스트의 상태를 실수로 사용하는 일을 줄이려면 안정적이고 권한이 낮은 프로필을 기본값으로 사용하세요.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`브라우저 활성화`},help:{"v1-19qr4oj-56":`Gateway에서 브라우저 기능 연동을 활성화하여 브라우저 도구와 CDP 기반 워크플로를 실행할 수 있게 합니다. 브라우저 자동화가 필요하지 않으면 비활성화하여 노출 범위와 시작 시 작업량을 줄이세요.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`브라우저 평가 기능 활성화`},help:{"v1-1oa79mq-59":`지원되는 환경에서 런타임 스크립트 평가를 위한 브라우저 측 평가 도우미를 활성화합니다. 워크플로에 스냅샷이나 탐색 이상의 평가 기능이 필요하지 않으면 비활성화 상태로 유지하세요.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`브라우저 실행 파일 경로`},help:{"v1-1plb4ki-6i":`호스트 환경에서 자동 검색만으로 충분하지 않을 때 명시적으로 지정하는 브라우저 실행 파일 경로입니다. 재시작 후에도 일관되게 실행되도록 고정된 절대 경로나 OS 홈 디렉터리를 나타내는 ~로 시작하는 경로를 사용하세요.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`브라우저 확장 프로그램 릴레이`},help:{"v1-6ywlwr-4e":`Chrome 확장 프로그램 릴레이 인증 호환성 설정입니다. 페어링된 이전 버전의 확장 프로그램이나 외부 CDP 클라이언트에 필요한 동안에만 레거시 호환 기간을 유지하세요.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`레거시 브라우저 릴레이 인증 허용`},help:{"v1-pj2e90-63":`레거시 Bearer, Basic 및 토큰 하위 프로토콜 릴레이 인증을 일시적으로 허용합니다. 기본값: 마이그레이션 기간 동안 true. 모든 확장 프로그램과 외부 CDP 클라이언트가 브라우저 릴레이 인증 v2를 사용하게 되면 false로 설정하세요.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`브라우저 헤드리스 모드`},help:{"v1-1rswq8j-5a":`로컬 런처가 브라우저 인스턴스를 시작할 때 헤드리스 모드로 실행하도록 강제합니다. 서버 환경에서는 헤드리스 모드를 활성화 상태로 유지하고, 화면에 표시되는 UI를 디버깅해야 할 때만 비활성화하세요.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`브라우저 샌드박스 비활성화 모드`},help:{"v1-slntux-4w":`런타임에 샌드박스가 작동하지 않는 환경에서 Chromium 샌드박스 격리 플래그를 비활성화합니다. 프로세스 격리 보호가 약화되므로 가능하면 이 옵션을 꺼 두세요.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`브라우저 프로필`},help:{"v1-1x8lf05-51":`CDP 포트 또는 URL로 명시적으로 라우팅하는 데 사용하는 이름별 브라우저 프로필 연결 맵으로, 선택적 메타데이터를 포함할 수 있습니다. 프로필 이름을 일관되게 유지하고 엔드포인트 정의가 중복되지 않도록 하세요.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`브라우저 프로필 연결 전용 모드`},help:{"v1-2b5zs0-5a":`로컬 브라우저 실행을 건너뛰고 기존 CDP 엔드포인트에만 연결하도록 프로필별로 재정의하는 설정입니다. 특정 프로필은 외부에서 관리하고 나머지는 로컬에서 실행할 때 유용합니다.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`브라우저 프로필 CDP 포트`},help:{"v1-gx1yiq-49":`URL 대신 포트로 브라우저 인스턴스에 연결할 때 사용하는 프로필별 로컬 CDP 포트입니다. 연결 충돌을 방지하려면 프로필마다 고유한 포트를 사용하세요.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`브라우저 프로필 CDP URL`},help:{"v1-x491r0-64":`프로필 이름에 따라 브라우저를 명시적으로 라우팅하는 데 사용하는 프로필별 CDP/DevTools 엔드포인트 URL입니다. 원격 CDP 호스트, 터널 또는 실행 중인 Chrome DevTools 엔드포인트를 통해 연결해야 하는 기존 세션 프로필에 사용하세요.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`브라우저 프로필 드라이버`},help:{"v1-17byyx6-5r":`프로필별 브라우저 드라이버 모드입니다. CDP 기반 프로필에는 "openclaw"(또는 기존 "clawd"), Chrome DevTools MCP 연결에는 "existing-session", 인증된 Chrome 확장 프로그램 릴레이에는 "extension"을 사용하세요.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`브라우저 프로필 실행 파일 경로`},help:{"v1-29azyv-4w":`로컬에서 실행되는 관리형 브라우저 프로필의 프로필별 브라우저 실행 파일 경로입니다. browser.executablePath보다 우선 적용되며, OS 홈 디렉터리를 나타내는 ~로 시작하는 경로를 사용할 수 있습니다.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`브라우저 프로필 헤드리스 모드`},help:{"v1-p4jtgv-4u":`로컬에서 실행되는 브라우저 인스턴스의 헤드리스 설정을 프로필별로 재정의합니다. 다른 모든 프로필에 browser.headless를 강제 적용하지 않고 특정 프로필만 헤드리스로 유지하려면 이 설정을 사용하세요.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`브라우저 프로필 Chrome MCP 인수`},help:{"v1-rc45ke-5g":`existing-session 연결을 위한 프로필별 추가 Chrome DevTools MCP 인수입니다. 예: --no-usage-statistics. 여기에 지정된 엔드포인트 인수는 기본 제공 자동 연결 또는 브라우저 URL 선택보다 우선 적용됩니다.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`브라우저 프로필 Chrome MCP 명령`},help:{"v1-1xpty8o-2h":`existing-session 연결을 위한 프로필별 Chrome DevTools MCP 명령입니다. 기본값은 npx입니다.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`브라우저 프로필 사용자 데이터 디렉터리`},help:{"v1-5xvgex-9h":`Chrome DevTools MCP를 통해 기존 세션에 연결할 때 사용하는 프로필별 Chromium 사용자 데이터 디렉터리입니다. 기본 제공 자동 연결 경로가 선택한 호스트 또는 브라우저 노드에서 잘못된 브라우저 데이터 디렉터리를 선택하는 경우 Brave, Edge, Chromium 또는 기본 프로필이 아닌 Chrome 프로필에 이 설정을 사용하세요. ~로 시작하는 경로는 OS 홈 디렉터리로 확장됩니다.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`브라우저 스냅샷 기본 설정`},help:{"v1-v19wdy-4y":`호출자가 스냅샷 옵션을 명시적으로 제공하지 않을 때 사용하는 기본 스냅샷 캡처 설정입니다. 채널과 자동화 경로 전반에서 일관된 캡처 동작을 보장하도록 조정하세요.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`브라우저 스냅샷 모드`},help:{"v1-joeyxp-5c":`에이전트가 사용할 수 있도록 페이지 콘텐츠를 변환하는 방식을 제어하는 기본 스냅샷 추출 모드입니다. 워크플로에 맞춰 가독성, 원본 충실도, 토큰 사용량 간의 균형을 이루는 모드를 선택하세요.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`브라우저 SSRF 정책`},help:{"v1-1qbp9im-5e":`내부 호스트에 접근할 수 있는 브라우저/네트워크 가져오기 경로에 대한 서버 측 요청 위조 방지 설정입니다. 프로덕션 환경에서는 제한적인 기본값을 유지하고 명시적으로 승인된 대상만 허용하세요.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`브라우저 허용 호스트 이름`},help:{"v1-1rng39-2k":`브라우저 SSRF 정책 검사에서 허용하는 정확한 호스트 이름 또는 IP 리터럴입니다. 목록을 최소한으로 유지하세요.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`브라우저 IPv6 고유 로컬 범위 허용`},help:{"v1-1glx5cy-2c":`신뢰할 수 있는 가상 IP 프록시 환경에서 IPv6 고유 로컬 주소(fc00::/7)를 허용합니다.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`브라우저 RFC 2544 벤치마크 범위 허용`},help:{"v1-10ateu3-2i":`신뢰할 수 있는 가상 IP 프록시 환경에서 RFC 2544 벤치마크 범위 IP(198.18.0.0/15)를 허용합니다.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`브라우저 차단 호스트 이름`},help:{"v1-nug0we-6k":`사설 네트워크 접근이 활성화되어 있어도 DNS 및 허용 규칙보다 먼저 차단되는 호스트 이름 패턴입니다. 정확한 호스트 이름과 하위 도메인 전용 패턴인 "*.example.com"을 지원합니다. 최상위 도메인도 차단하려면 "example.com"을 별도로 추가하세요. 비어 있거나 설정되지 않으면 차단 항목이 추가되지 않습니다.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`브라우저 사설 네트워크 허용(위험)`},help:{"v1-17103pi-4m":`브라우저 도구에서 사설 네트워크 주소 범위에 접근하도록 허용합니다. 설정하지 않으면 기본적으로 비활성화됩니다. 명시적으로 신뢰하는 사설 네트워크 대상에만 활성화하세요.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`브라우저 탭 정리`},help:{"v1-1ctwaad-4y":`기본 에이전트 세션에서 연 브라우저 탭을 가능한 한 정리하는 정책입니다. 장시간 실행되는 게이트웨이에 오래된 샌드박스 또는 관리형 브라우저 탭이 쌓이지 않도록 활성화 상태를 유지하세요.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`브라우저 탭 정리 활성화`},help:{"v1-4sv97p-3u":`기본 에이전트 세션에서 추적하는 유휴 브라우저 탭의 정리를 활성화합니다. 외부 도구가 탭의 수명 주기를 전적으로 관리하는 경우에만 비활성화하세요.`}},channels:{label:{"v1-1ju93md-8":`채널`},help:{"v1-12yv6ma-5n":`채널 제공자 설정과 접근 정책, 하트비트 표시 여부, 인터페이스별 동작을 제어하는 공통 기본값입니다. 기본값은 중앙에서 관리하고 필요한 경우에만 제공자별로 재정의하세요.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`채널 기본값`},help:{"v1-uz6veb-4p":`공급자별 설정이 없을 때 모든 공급자에 적용되는 기본 채널 동작입니다. 공급자별로 세부 조정하기 전에 일관된 기본 정책을 적용하는 데 사용하세요.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`기본 봇 루프 방지`},help:{"v1-1lpznyk-4w":`봇 간 루프 방지를 지원하는 채널 공급자의 기본 쌍별 루프 방지 설정입니다. 특정 채널에 다른 한도가 필요한 경우에만 공급자별 재정의를 사용하세요.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`기본 봇 루프 대기 시간(초)`},help:{"v1-1yl5ird-2z":`한 쌍이 루프 한도를 초과한 후 적용되는 대기 시간(초)입니다. 지원되는 채널의 기본값은 60입니다.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`기본 봇 루프 방지 활성화`},help:{"v1-3ruik-4r":`봇이 작성한 메시지가 디스패치 단계에 도달할 수 있을 때, 지원되는 채널에서 쌍별 루프 방지를 기본으로 활성화합니다. 봇이 무시되는 경우 공급자가 이 보호 기능을 비활성화할 수도 있습니다.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`기본 봇 루프 시간 구간당 이벤트 수`},help:{"v1-1u0mdjc-41":`설정된 시간 구간 내에서 발신자/수신자 쌍이 억제가 시작되기 전에 주고받을 수 있는 최대 이벤트 수입니다. 지원되는 채널의 기본값은 20입니다.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`기본 봇 루프 시간 구간(초)`},help:{"v1-12xpmen-2m":`쌍별 루프 한도에 적용되는 슬라이딩 윈도우의 길이(초)입니다. 지원하는 채널의 기본값은 60입니다.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`기본 컨텍스트 표시 범위`},help:{"v1-1hze3g1-5o":`가져온 인용문/스레드/기록 콘텐츠의 기본 보조 컨텍스트 표시 범위입니다. "all"(모든 컨텍스트 유지), "allowlist"(허용 목록에 있는 발신자만), "allowlist_quote"(허용 목록 적용 + 명시적 인용문 유지) 중에서 선택합니다.`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`기본 그룹 정책`},help:{"v1-ntl9m4-4n":`채널 전반에 적용되는 기본 그룹 정책입니다. "open", "disabled", "allowlist" 중에서 선택합니다. 폭넓은 그룹 참여를 의도한 경우가 아니라면 프로덕션 환경의 안전성을 위해 "allowlist"를 유지하세요.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`기본 하트비트 표시 설정`},help:{"v1-49bw75-4v":`제공자/채널에서 전송하는 상태 메시지의 기본 하트비트 표시 설정입니다. 전역 설정을 조정하여 알림은 계속 표시하면서 불필요한 정상 상태 업데이트를 줄일 수 있습니다.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`하트비트 알림 표시`},help:{"v1-8dk8zx-4g":`true이면 성능 저하/오류 하트비트 알림을 표시하여 운영자 채널에서 문제를 신속하게 확인할 수 있습니다. 프로덕션 환경에서는 채널의 비정상 상태를 확인할 수 있도록 활성화 상태를 유지하세요.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`하트비트 정상 상태 표시`},help:{"v1-17tg3mk-4z":`true이면 채널 상태 출력에 정상/OK 하트비트 상태 항목을 표시합니다. 상태 출력이 많은 환경에서는 false로 유지하고, 운영자가 명시적인 정상 확인을 필요로 할 때만 활성화하세요.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`하트비트 표시기 사용`},help:{"v1-1w12cs2-4m":`지원되는 경우 상세한 상태 텍스트 대신 간결한 표시기 형태로 하트비트를 표시합니다. 활성 채널이 많아 정보가 밀집된 대시보드에서는 표시기 모드를 사용하세요.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`기본 암시적 멘션`},help:{"v1-4gtdyv-48":`봇에 대한 답장, 봇 메시지 인용, 봇이 참여한 스레드 등의 맥락을 명시적인 멘션 없이도 지원되는 메시지 채널의 활성화 조건으로 사용할지 결정하는 기본 정책입니다.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`봇 메시지 인용 시 기본 암시적 멘션`},help:{"v1-va1u5v-2v":`기본적으로 봇 메시지 인용을 암시적 멘션으로 처리합니다. 하위 호환성을 위해 기본값은 true입니다.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`봇에 대한 답장 시 기본 암시적 멘션`},help:{"v1-lm44c3-39":`기본적으로 봇 자신의 메시지에 대한 답장을 암시적 멘션으로 처리합니다. 하위 호환성을 위해 기본값은 true입니다.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`스레드 참여 시 기본 암시적 멘션`},help:{"v1-160205h-3o":`기본적으로 봇이 참여한 스레드의 후속 메시지를 암시적 멘션으로 처리합니다. 하위 호환성을 위해 기본값은 true입니다.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`채널별 모델 재정의`},help:{"v1-1b01spx-2p":`제공자 -> 채널 ID / DM 상대 ID -> 모델 재정의 매핑입니다(값은 provider/model 또는 별칭).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`클라우드 워커`},help:{"v1-10carc4-5v":`일회용 원격 환경을 위한 선택적 클라우드 워커 프로필입니다. 이 섹션이 생략되거나 프로필이 없으면 클라우드 워커 생성은 계속 사용할 수 없으며 기존 Gateway/노드 상태 동작은 변경되지 않습니다.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`클라우드 워커 데스크톱(실험실)`},help:{"v1-vllayc-3n":`데스크톱을 지원하는 클라우드 워커 환경에서 실험적 worker.desktop.observe 기능과 Control UI 데스크톱 패널을 활성화합니다.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`클라우드 워커 준비 풀`},help:{"v1-rw51o5-6b":`이후 세션에 사용할 수 있도록 준비 상태로 유지되는 클라우드 워커의 한도입니다. 예약된 워커에는 공급자의 정리 작업이 완료될 때까지 머신 실행 요금이 부과됩니다. 고정 만료 시점은 실제 프로젝트 수요와 공급자의 기존 유휴 정책에 따라 결정됩니다.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`클라우드 워커 준비 예비 풀 상한`},help:{"v1-1mpd1dt-7u":`프로젝트와 프로필 전체에서 아직 할당되지 않은 준비된 클라우드 워커 수에 적용되는 Gateway 전체 상한입니다(기본값: 4). 준비 중인 워커와 정리가 확인되지 않은 예비 워커도 상한 계산에 포함됩니다. 0으로 설정하면 스냅샷 재사용과 활성 세션은 유지하면서 미할당 예비 워커를 모두 제거하고 보충을 비활성화합니다.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`클라우드 워커 프로필`},help:{"v1-eii67l-3j":`이름이 지정된 클라우드 워커 프로필입니다. 각 프로필은 플러그인으로 등록된 워커 제공자를 선택하며 제공자별 설정을 포함합니다.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`클라우드 워커 프로필`},help:{"v1-1v2w7jl-4u":`환경 생성 시 이름으로 선택하는 단일 클라우드 워커 프로필입니다. 이 블록에 비밀 정보를 직접 포함하지 말고 지원되는 참조를 사용하여 제공자 자격 증명을 보관하세요.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`클라우드 워커 설치 방식`},help:{"v1-blrtbf-74":`워커 설치 방식: "bundle"(기본값)은 Gateway에 설치된 콘텐츠 해시 기반 빌드를 전송하며, 출시 버전, 개발 버전, 미출시 버전을 지원합니다. "npm"은 Gateway와 정확히 동일한 버전을 설치하며 해당 버전이 출시된 경우에만 사용할 수 있습니다.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`클라우드 워커 제공자`},help:{"v1-1p4s4c1-44":`플러그인에서 등록한 워커 공급자 ID입니다. Gateway가 프로필을 기반으로 환경을 프로비저닝하려면 구성된 플러그인이 이 ID를 노출해야 합니다.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`클라우드 워커 준비 예비 풀 목표`},help:{"v1-1nwve9s-7w":`이 프로필을 사용하는 적격 프로젝트별 미할당 준비 워커의 목표 수입니다(기본값: 1). Gateway 전체의 준비 풀 상한이 적용됩니다. 0으로 설정하면 스냅샷 재사용은 유지하면서 이 프로필의 예비 풀을 비활성화합니다. 준비 중인 워커와 정리가 확인되지 않은 예비 워커도 목표 수 계산에 포함됩니다.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`클라우드 워커 공급자 설정`},help:{"v1-mq7u32-4j":`선택한 플러그인에서 검증하는 공급자 전용 설정입니다. 비밀 정보가 포함된 값에는 SecretRef 객체를 사용하세요. 내부 구조를 알 수 없는 설정에서는 비밀 정보가 자동으로 해석되지 않습니다.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`클라우드 워커 유휴 상태 중단 대기 시간`},help:{"v1-1keuwgh-4w":`45m 또는 2h 등 지정한 시간 동안 유휴 상태인 클라우드 워커를 자동으로 회수합니다. 다음 메시지가 도착하면 대체 워커를 프로비저닝합니다. 최솟값: 1m. 워커를 계속 실행하려면 설정하지 마세요.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`클라우드 워커 프로젝트 프로필`},help:{"v1-1kkfrif-46":`소문자로 정규화된 저장소 식별자(host/owner/repo)를 키로 사용하는 기본 클라우드 워커 프로필 이름입니다. 명시적으로 지정한 디스패치 프로필 ID가 우선합니다.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`클라우드 워커 프로젝트 프로필`},help:{"v1-1mux5u0-30":`세션 작업 트리의 origin이 이 저장소 식별자와 일치할 때 기본으로 사용하는 클라우드 워커 프로필 이름입니다.`}},commands:{label:{"v1-15x4mpf-8":`명령어`},help:{"v1-1gi0dr2-5a":`공급자 전반에서 채팅 명령 인터페이스, 소유자 기반 접근 제한, 상승된 권한의 명령 접근 동작을 제어합니다. 더 엄격한 운영자 제어나 더 폭넓은 명령 가용성이 필요하지 않다면 기본값을 유지하세요.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`명령의 상승된 권한 접근 규칙`},help:{"v1-7azkw-5g":`소유자 수준의 명령 인터페이스에 대해 채널 및 발신자별로 권한 상승 명령 허용 규칙을 정의합니다. 특권 명령이 광범위한 채팅 참여자에게 노출되지 않도록 제공업체별로 범위가 좁은 식별자를 사용하세요.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Bash 채팅 명령 허용`},help:{"v1-83ah7w-36":"bash 채팅 명령(`!`, 별칭: `/bash`)으로 호스트 셸 명령을 실행하도록 허용합니다(기본값: false, tools.elevated 필요)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Bash 포그라운드 대기 시간(ms)`},help:{"v1-1o0o4dw-2c":`bash가 백그라운드로 전환하기 전까지 대기하는 시간입니다(기본값: 2000, 0이면 즉시 백그라운드로 전환).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`/config 허용`},help:{"v1-151bb7c-21":`/config 채팅 명령으로 디스크의 설정을 읽고 쓰도록 허용합니다(기본값: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`/debug 허용`},help:{"v1-y1lc3j-1y":`/debug 채팅 명령으로 런타임에만 적용되는 설정 재정의를 허용합니다(기본값: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`/mcp 허용`},help:{"v1-1rtwcgd-2o":`/mcp 채팅 명령으로 mcp.servers 아래의 OpenClaw MCP 서버 설정을 관리하도록 허용합니다(기본값: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`네이티브 명령`},help:{"v1-dighr2-5n":`명령 등록을 지원하는 채널(Discord, Slack, Telegram)에 네이티브 슬래시/메뉴 명령을 등록합니다. 의도적으로 텍스트 전용 명령 워크플로를 사용하는 경우가 아니라면 사용자가 명령을 쉽게 찾을 수 있도록 활성화 상태를 유지하세요.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`네이티브 스킬 명령`},help:{"v1-19gtqci-5h":`지원되는 제공업체의 명령 메뉴에서 사용자가 스킬을 직접 호출할 수 있도록 네이티브 스킬 명령을 등록합니다. 노출되는 명령이 운영자의 기대에 부합하도록 스킬 정책과 일치하게 유지하세요.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`명령어 소유자`},help:{"v1-1di38gv-3y":`소유자 전용 명령어에 대한 명시적 소유자 허용 목록입니다. 채널 고유 ID를 사용하세요(선택적으로 "whatsapp:+15551234567"처럼 접두사를 붙일 수 있습니다). '*'는 무시됩니다.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`/plugins 허용`},help:{"v1-akwy9y-33":`발견된 플러그인을 나열하고 설정에서 플러그인 활성화 여부를 전환하는 /plugins 채팅 명령어를 허용합니다(기본값: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`재시작 허용`},help:{"v1-m32fv2-27":`/restart, /update 및 외부 SIGUSR2 재시작 요청을 허용합니다(기본값: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`텍스트 명령어`},help:{"v1-1utu76s-5j":`사용 가능한 기본 명령어 인터페이스 외에도 채팅 입력에서 텍스트 명령어를 파싱할 수 있도록 합니다. 기본 명령어 등록을 지원하지 않는 채널과의 호환성을 위해 이 설정을 활성화된 상태로 유지하세요.`}},cron:{label:{"v1-1qlte4b-b":`자동화`},help:{"v1-4md8ic-5u":`저장된 자동화, 동시 실행, 전송 실패 시 대체 처리 및 실행 세션 보존에 대한 전역 스케줄러 설정입니다. 자동화 규모를 확장하거나 외부 웹훅 수신기를 통합하는 경우가 아니라면 기본값을 유지하세요.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`자동화 활성화`},help:{"v1-y8otx6-5i":`Gateway에서 관리하는 저장된 일정의 자동화 실행을 활성화합니다. 일반적인 알림 및 자동화 흐름을 위해 활성화된 상태로 유지하고, 작업을 삭제하지 않고 모든 자동화 실행을 일시 중지하려는 경우에만 비활성화하세요.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`자동화 세션 보존`},help:{"v1-4wagu6-7e":"완료된 자동화 실행 세션을 정리하기 전까지 보관하는 기간을 설정합니다(`24h`, `7d`, `1h30m`, 또는 정리를 비활성화하는 `false`; `0h`처럼 기간이 0인 경우에도 비활성화됨; 기본값: `24h`). 실행 빈도가 높은 일정에서는 보관 기간을 줄여 저장 공간 증가를 억제하세요."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`놓친 반복 자동화 건너뛰기`},help:{"v1-w9wfmo-66":`Gateway 시작 시 놓친 반복 cron/every 실행을 건너뛰고, 이를 뒤늦게 실행하는 대신 다음 예정 시각에 실행하도록 예약합니다. 기본값: false. 중단 이후 오래된 알림이 전송되지 않도록 하려면 활성화하세요. 일회성 at 작업은 여전히 뒤늦게 실행됩니다.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`자동화 웹훅 SSRF 정책`},help:{"v1-1xlfqnu-5h":`모든 아웃바운드 자동화 웹훅에 적용되는 SSRF 정책입니다. 이 정책에서 명시적으로 허용하지 않는 한 사설, 루프백, 링크 로컬 및 내부 대상은 계속 차단됩니다. 엄격한 전송 제한을 유지하려면 설정하지 마세요.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`자동화 웹훅 허용 호스트 이름`},help:{"v1-1i94hyz-3n":`자동화 웹훅 전송을 허용할 정확한 호스트 이름 또는 IP 리터럴입니다. 기본적으로 차단되는 대상도 포함할 수 있습니다. 목록은 최소한으로 유지하세요.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`자동화 웹훅 IPv6 고유 로컬 범위 허용`},help:{"v1-rke0oj-3b":`IPv6 고유 로컬 주소(fc00::/7)로 자동화 웹훅을 전송할 수 있도록 허용합니다. 신뢰할 수 있는 fake-IP 프록시 환경에서만 사용하세요.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`자동화 웹훅 RFC 2544 벤치마크 범위 허용`},help:{"v1-x1usg4-3h":`RFC 2544 벤치마크 범위 IP(198.18.0.0/15)로 자동화 웹훅을 전송하도록 허용합니다. 신뢰할 수 있는 가상 IP 프록시 환경에서만 사용하세요.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`자동화 웹훅 차단 호스트 이름`},help:{"v1-16cv1ic-6a":`자동화 웹훅 전송 시 DNS 조회 및 허용 규칙 적용 전에 차단할 호스트 이름 패턴입니다. 정확한 호스트 이름과 하위 도메인 전용 패턴인 "*.example.com"을 지원합니다. 최상위 도메인도 차단하려면 "example.com"을 별도로 추가하세요. 비어 있거나 설정하지 않으면 차단 규칙이 추가되지 않습니다.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`자동화 웹훅 사설 네트워크 허용(위험)`},help:{"v1-1n9710c-3t":`사설 및 내부 네트워크 대상으로 자동화 웹훅을 전송하도록 허용합니다. 설정된 모든 웹훅 대상을 신뢰할 수 있는 경우가 아니면 비활성화 상태로 유지하세요.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`자동화 웹훅 베어러 토큰`},help:{"v1-1l90hxg-5l":`웹훅 모드 사용 시 자동화 웹훅 POST 전송에 첨부되는 베어러 토큰입니다. 비밀 값 또는 환경 변수 치환을 사용하는 것이 좋으며, 공유 웹훅 엔드포인트에 인터넷에서 접근할 수 있다면 이 토큰을 정기적으로 교체하세요.`}},desktop:{label:{"v1-rs698z-7":`데스크톱`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`로컬 데스크톱`},help:{"v1-99weio-30":`로컬 VNC 서버를 기반으로 페어링된 노드 또는 실험용 Gateway 호스트 소스의 데스크톱을 모니터링합니다.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`데스크톱 공유`},help:{"v1-m9lbcj-83":`이 기기의 데스크톱 소스를 활성화합니다. 페어링된 macOS, Windows, Linux 노드에서는 기본적으로 활성화되며, 데스크톱 앱의 공유 설정이 명시되어 있으면 해당 설정이 우선합니다. Gateway 호스트의 Labs 소스는 기본적으로 비활성화되며 변경 사항은 실시간으로 적용됩니다. 페어링된 노드의 데스크톱 구성을 변경한 후에는 해당 노드를 다시 시작하세요.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`관리형 Linux 호스트 데스크톱`},help:{"v1-1r7n22m-49":`Linux에서 루프백 전용 헤드리스 TigerVNC/XFCE 데스크톱을 실행하고 관리합니다. 명시적으로 지정한 포트나 기본 포트에서 실행 중인 기존 VNC 서버가 여전히 우선합니다.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`로컬 VNC 비밀번호 파일`},help:{"v1-1m5lsox-37":`VNC 비밀번호 파일의 절대 경로입니다. macOS에서 이 값을 생략하면 데스크톱 뷰어를 열 때 계정 자격 증명을 입력할 수 있습니다.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`로컬 VNC 포트`},help:{"v1-1ku4w9b-2b":`이 컴퓨터에서 이미 실행 중인 VNC 서버의 루프백 RFB 포트입니다(기본값: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`진단`},help:{"v1-1d5rnym-5p":`디버깅 중 특정 대상 추적, 텔레메트리 내보내기, 캐시 검사를 위한 진단 설정입니다. 프로덕션 환경에서는 기본 진단을 최소한으로 유지하고, 문제를 조사할 때만 상세 진단 신호를 활성화하세요.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`캐시 추적`},help:{"v1-10523zm-5b":`임베디드 실행에서 캐시 결정과 페이로드 컨텍스트를 관찰하기 위한 캐시 추적 로깅 설정입니다. 디버깅할 때 일시적으로 활성화하고, 이후에는 비활성화하여 로그에 남는 민감한 정보를 줄이세요.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`캐시 추적 활성화`},help:{"v1-2c1umi-1v":`임베디드 에이전트 실행의 캐시 추적 스냅샷을 로그에 기록합니다(기본값: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`진단 활성화`},help:{"v1-a46pxt-4h":`로그와 텔레메트리 연결 경로의 진단 계측 출력을 제어하는 전체 토글입니다. 기본적으로 활성화되어 있으며, 제약이 매우 엄격한 환경에서만 false로 설정하세요.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`진단 플래그`},help:{"v1-x4w5ok-33":`플래그별로 특정 진단 로그를 활성화합니다(예: ["telegram.http"]). "telegram.*" 또는 "*" 같은 와일드카드를 지원합니다.`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Gateway 구성 요소에서 생성하는 추적, 메트릭 및 로그의 OpenTelemetry 내보내기 설정입니다. 중앙 집중식 관측 백엔드 및 분산 추적 파이프라인과 통합할 때 사용하세요.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`OpenTelemetry 콘텐츠 캡처`},help:{"v1-19tid4t-2t":`선택적으로 활성화하는 OTEL 스팬 콘텐츠 캡처입니다. 기본적으로 꺼져 있으며, true로 설정하면 시스템 메시지를 제외한 메시지 및 도구 콘텐츠를 캡처합니다.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry 활성화`},help:{"v1-193bm0-5b":`구성된 엔드포인트 및 프로토콜 설정에 따라 추적, 메트릭 및 로그의 OpenTelemetry 내보내기 파이프라인을 활성화합니다. 수집기 엔드포인트와 인증 구성이 완료될 때까지 비활성화 상태로 유지하세요.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`OpenTelemetry 엔드포인트`},help:{"v1-4rrd1x-4y":`OpenTelemetry 내보내기 전송에 사용하는 수집기 엔드포인트 URL로, 스킴과 포트를 포함합니다. 접근 가능하고 신뢰할 수 있는 수집기 엔드포인트를 사용하고, 배포 후 수집 오류를 모니터링하세요.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`OpenTelemetry 플러시 간격(ms)`},help:{"v1-1moqogc-53":`버퍼의 텔레메트리 데이터를 수집기로 주기적으로 전송하는 간격(밀리초)입니다. 내보내기 빈도를 줄이려면 값을 높이고, 장애 대응 중 데이터를 더 빠르게 확인하려면 값을 낮추세요.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`OpenTelemetry 헤더`},help:{"v1-s26t2a-52":`OpenTelemetry 내보내기 요청과 함께 전송되는 추가 HTTP 요청 헤더로, 주로 테넌트 인증이나 라우팅에 사용됩니다. 비밀 정보는 환경 변수 기반 값으로 관리하고 불필요하게 헤더를 늘리지 마세요.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry 로그 활성화`},help:{"v1-12wo6rv-4k":`로컬 로깅 대상 외에 OpenTelemetry를 통한 로그 신호 내보내기를 활성화합니다. 서비스와 에이전트 전반에서 중앙 집중식 로그 상관관계 분석이 필요할 때 사용하세요.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`OpenTelemetry 로그 엔드포인트`},help:{"v1-1vgzldu-40":`로그 신호 전용 OTLP/HTTP 엔드포인트입니다. 설정하면 로그 내보내기에 한해 diagnostics.otel.endpoint 및 OTEL_EXPORTER_OTLP_ENDPOINT보다 우선 적용됩니다.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`OpenTelemetry 로그 내보내기 도구`},help:{"v1-9bzywd-5q":`diagnostics.otel.logs의 로그 내보내기 대상입니다. 설정된 OTLP 로그 엔드포인트를 사용하려면 "otlp"를, 컨테이너 로그 파이프라인에서 stdout의 각 줄에 JSON 레코드 하나를 출력하려면 "stdout"을, 두 대상이 모두 필요하면 "both"를 사용하세요.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`OpenTelemetry 메트릭 이름 접두사`},help:{"v1-1epdpi9-b2":`OpenClaw 자체 메트릭 이름의 기본 접두사 "openclaw."를 대체합니다. 접두사를 제거하려면 빈 문자열을 사용하세요. 또는 영문자로 시작하고 ASCII 영문자, 숫자, 밑줄, 마침표, 하이픈, 슬래시로 구성된 최대 128자의 문자열을 사용하세요. "acme."처럼 필요한 구분자를 포함하세요. 표준 gen_ai.* 메트릭 이름은 변경되지 않습니다. 이 값을 변경하면 기존 이름을 쿼리하는 대시보드와 알림도 업데이트해야 합니다.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`OpenTelemetry 메트릭 활성화`},help:{"v1-13r4cf4-4x":`설정된 OpenTelemetry 수집기 엔드포인트로 메트릭 신호 내보내기를 활성화합니다. 런타임 상태 대시보드를 사용하려면 활성화 상태를 유지하고, 메트릭 양을 최소화해야 하는 경우에만 비활성화하세요.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`OpenTelemetry 메트릭 엔드포인트`},help:{"v1-qlfh7x-47":`메트릭 신호 전용 OTLP/HTTP 엔드포인트입니다. 설정하면 메트릭 내보내기에 한해 diagnostics.otel.endpoint 및 OTEL_EXPORTER_OTLP_ENDPOINT보다 우선 적용됩니다.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetry 프로토콜`},help:{"v1-17ine8s-5e":`텔레메트리 내보내기에 사용할 OTel 전송 프로토콜입니다. "http/protobuf"만 허용됩니다. "openclaw doctor --fix"를 실행하여 저장된 레거시 "grpc" 값을 수정하거나 설정 출처별 수동 편집 안내를 확인하세요.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`OpenTelemetry 트레이스 샘플링 비율`},help:{"v1-brcwep-50":`관측성 백엔드로 내보낼 트레이스 트래픽의 양을 제어하는 트레이스 샘플링 비율(0-1)입니다. 비율을 낮추면 오버헤드와 비용이 줄어들고, 높이면 디버깅 정밀도가 향상됩니다.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetry 서비스 이름`},help:{"v1-1hpiqon-5d":`관측성 백엔드에서 이 Gateway 인스턴스를 식별하기 위해 텔레메트리 리소스 속성에 보고되는 서비스 이름입니다. 배포 시에도 대시보드와 알림의 일관성이 유지되도록 고정된 이름을 사용하세요.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetry 트레이스 활성화`},help:{"v1-j7zrrp-4s":`설정된 OpenTelemetry 수집기 엔드포인트로 트레이스 신호 내보내기를 활성화합니다. 지연 시간 분석이나 디버깅을 위한 추적이 필요하면 활성화 상태를 유지하고, 메트릭과 로그만 필요하면 비활성화하세요.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`OpenTelemetry 트레이스 엔드포인트`},help:{"v1-8yw5p1-43":`신호별 OTLP/HTTP 트레이스 엔드포인트입니다. 설정하면 트레이스 내보내기에 한해 diagnostics.otel.endpoint 및 OTEL_EXPORTER_OTLP_ENDPOINT보다 우선 적용됩니다.`}},discovery:{label:{"v1-l2sr05-9":`검색`},help:{"v1-1sqleij-4w":`로컬 mDNS 알림 및 선택적 광역 존재 알림을 위한 서비스 검색 설정입니다. 서비스 메타데이터가 유출되지 않도록 검색 범위를 의도한 네트워크로 제한하세요.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS 검색`},help:{"v1-vtbyyq-4w":`로컬 네트워크 알림 및 검색 동작을 조정하는 mDNS 검색 설정 그룹입니다. 추가 메타데이터가 필요하지 않다면 일반적인 LAN 검색에는 최소 모드를 유지하세요.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`mDNS 검색 모드`},help:{"v1-1p28pd5-2m":`mDNS 브로드캐스트 모드입니다("minimal"이 기본값이며, "full"은 cliPath/sshPort를 포함하고, "off"는 mDNS를 비활성화합니다).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`광역 검색`},help:{"v1-1akkqjm-53":`로컬 링크 범위를 넘어 검색 신호를 노출하는 광역 검색 설정 그룹입니다. 여러 사이트의 Gateway 존재 정보를 의도적으로 집계하는 배포 환경에서만 활성화하세요.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`광역 검색 도메인`},help:{"v1-rxrygo-4m":`openclaw.internal과 같은 광역 검색용 선택적 유니캐스트 DNS-SD 도메인입니다. 로컬 mDNS 범위를 넘어 Gateway 검색 정보를 의도적으로 게시할 때 사용하세요.`}},env:{label:{"v1-1zc80q-b":`환경`},help:{"v1-1ao5po6-55":`Gateway 프로세스에 런타임 변수를 제공하는 환경 가져오기 및 재정의 설정입니다. 이 섹션에서 셸 환경 로딩과 명시적 변수 주입 동작을 제어하세요.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`셸 환경 가져오기`},help:{"v1-1gw487t-4y":`시작 시 로그인 셸에서 변수를 불러오는 셸 환경 가져오기 설정입니다. 프로필에 정의된 비밀 정보나 PATH 사용자 지정 설정을 사용하는 경우 활성화 상태로 유지하세요.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`셸 환경 가져오기 활성화`},help:{"v1-5tiuup-5u":`시작 초기화 중에 사용자 셸 프로필에서 환경 변수를 불러옵니다. 개발자 컴퓨터에서는 활성화 상태로 유지하고, 환경 변수를 명시적으로 관리하는 접근 제한 서비스 환경에서는 비활성화하세요.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`셸 환경 가져오기 제한 시간(ms)`},help:{"v1-nsk2yf-5c":`대체 동작이 적용되기 전까지 셸 환경을 확인하는 데 허용되는 최대 시간(밀리초)입니다. 더 빠르게 시작하려면 제한 시간을 줄이고, 셸 초기화에 시간이 많이 걸리면 늘리세요.`}},"env%2Evars":{label:{"v1-grhbhj-u":`환경 변수 재정의`},help:{"v1-yxc3z7-5n":`OpenClaw의 런타임 프로세스 환경에 병합되는 명시적인 키/값 환경 변수 재정의입니다. 셸 프로필의 부수 효과에만 의존하지 않고 일관된 환경 구성을 적용하려면 이 설정을 사용하세요.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`바인딩 모드, 인증, Control UI, 원격 전송 및 운영 안전 제어를 위한 Gateway 런타임 설정입니다. 신뢰할 수 있는 로컬 인터페이스 외부로 Gateway를 의도적으로 노출하는 경우가 아니라면 보수적인 기본값을 유지하세요.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Gateway x-real-ip 대체 사용 허용`},help:{"v1-1wr3qmw-4c":`프록시 환경에서 x-forwarded-for가 없을 때 x-real-ip를 대신 사용할 수 있도록 합니다. 인그레스 스택에 이 호환 동작이 필요한 경우가 아니라면 비활성화 상태로 유지하세요.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway 인증`},help:{"v1-70b6ni-50":`모드, 자격 증명, 신뢰할 수 있는 프록시의 동작, 요청 속도 제한을 포함한 Gateway HTTP/WebSocket 접근 인증 정책입니다. 루프백이 아닌 모든 배포 환경에서는 인증을 활성화 상태로 유지하세요.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Gateway 인증에 Tailscale ID 허용`},help:{"v1-vqtmgw-53":`설정된 경우 신뢰할 수 있는 Tailscale ID 경로를 통해 Gateway 인증 검사를 통과할 수 있도록 허용합니다. tailnet의 ID 보안이 강력하고 운영자 워크플로에 이 기능이 필요한 경우에만 사용하세요.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Gateway ID 범위 권한 부여`},help:{"v1-1h0zxy7-5n":`검증된 trusted-proxy 또는 Tailscale ID를 해당 연결에만 유효한 운영자 범위 권한에 매핑합니다. 이메일 키는 대소문자를 구분하지 않고 일치 여부를 확인합니다. 부여된 권한은 연결 범위 상한이 적용되기 전에 기기 범위에 추가됩니다.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Gateway 인증 모드`},help:{"v1-j8rodq-9t":`Gateway 인증 모드: 에지 아키텍처에 따라 "none", "token", "password" 또는 "trusted-proxy"를 사용합니다. token/password 모드는 설정된 비밀 값(gateway.auth.token 또는 gateway.auth.password)을 선택합니다. 클라이언트는 연결 인증 필드 중 어느 쪽으로든 이 값을 전송할 수 있습니다. 직접 노출하는 경우에는 token/password를 사용하고, trusted-proxy는 보안이 강화된 ID 인식 프록시 뒤에서만 사용하세요.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Gateway 비밀번호`},help:{"v1-1ndt0u2-4g":`gateway.auth.mode=password로 선택되는 공유 비밀 값입니다. 클라이언트는 auth.token 또는 auth.password 중 어느 쪽으로든 이 값을 전송할 수 있습니다. Tailscale Funnel에는 비밀번호 모드가 필요합니다.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Gateway 인증 요청 속도 제한`},help:{"v1-1kstr42-54":`Gateway 경계에서 자격 증명 무차별 대입 공격의 위험을 줄이기 위한 로그인/인증 시도 제한 설정입니다. 외부에 노출된 환경에서는 활성화 상태를 유지하고 평소 트래픽 수준에 맞게 임계값을 조정하세요.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Gateway 토큰`},help:{"v1-16i7cxs-5q":`gateway.auth.mode=token으로 선택되는 공유 비밀 값으로, 새 로컬 초기 설정의 기본값입니다. 클라이언트는 auth.token 또는 auth.password로 이 값을 전송할 수 있습니다. 루프백이 아닌 주소에 바인딩하려면 인증 모드를 활성화해야 합니다.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gateway 신뢰할 수 있는 프록시 인증`},help:{"v1-12fsi5d-58":`사용자 클레임을 삽입하는 업스트림 ID 공급자를 위한 신뢰할 수 있는 프록시 인증 헤더 매핑입니다. 위조된 ID 헤더를 방지하려면 알려진 프록시 CIDR 및 엄격한 헤더 허용 목록과 함께 사용하세요.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Cloudflare Access OIDC GitHub 신원`},help:{"v1-1puth4k-6t":`선택한 Cloudflare Access OIDC 제공자의 검증된 GitHub 신원 정보로, 선택 사항입니다. 표준 Access 이메일 및 어설션 헤더가 필요합니다. 클레임이 없으면 이메일 전용 프로필이 유지되며, 기존 프로필 역할과 공동 작성자 환경설정은 보존됩니다.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`GitHub 계정 ID 클레임`},help:{"v1-pcaaw7-57":`전달된 OIDC 클레임의 정확한 이름입니다. 해당 값은 검증된 양의 십진수 문자열 형식의 GitHub 계정 ID여야 합니다. Access가 oidc_fields에 이 클레임을 포함하여 전달하도록 구성하세요. 검증되지 않은 사용자 편집 가능 클레임은 절대 사용하지 마세요.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access 발급자`},help:{"v1-gykv03-56":`신뢰할 수 있는 Cloudflare Access 팀의 정확한 HTTPS 오리진입니다. 예: https://example.cloudflareaccess.com. 끝에 슬래시를 붙이지 마세요. 다른 발급자의 클레임은 GitHub 신원 정보로 사용되지 않습니다.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Cloudflare Access OIDC 공급자 ID`},help:{"v1-kbyo5w-44":`신뢰할 수 있는 OIDC 통합에 대한 정확한 Access ID 공급자 ID입니다. 공급자의 표시 이름이나 일치하는 클레임 이름만으로는 신뢰가 성립하지 않습니다.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`신뢰할 수 있는 프록시 기기 자동 승인`},help:{"v1-uh32ha-6z":`신뢰할 수 있는 프록시 인증 후 새 브라우저 및 네이티브 UI 운영자 기기와 동일 키의 권한 범위 확장을 자동으로 승인하는 선택적 정책입니다. 부여되는 권한은 deviceAutoApprove.scopes로 제한되며, 프록시의 x-openclaw-scopes 헤더가 있으면 해당 헤더로도 제한됩니다.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`신뢰할 수 있는 프록시 기기 자동 승인 활성화`},help:{"v1-1nntwls-78":`리버스 프록시가 허용된 사용자를 인증하면 새 브라우저 및 네이티브 UI 운영자 기기와 동일 키의 권한 범위 확장을 자동으로 승인합니다. 기본값: false. 프록시의 ID 인증 경계가 수동 기기 페어링을 대체할 만큼 강력한 경우에만 활성화하세요.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`신뢰할 수 있는 프록시의 기기 자동 승인 권한 범위`},help:{"v1-raeila-g3":`자동 승인된 운영자 기기에 부여되는 최대 권한 범위입니다. 기본값은 operator.read, operator.write, operator.approvals, operator.questions입니다. 요청된 권한 범위는 이 목록으로 제한되며, 권한 범위가 없는 요청에는 이 목록이 부여됩니다. 설정하지 않으면 이전 UI 클라이언트를 위해 자동 승인 시 operator.questions도 추가됩니다. 명시적으로 지정한 목록은 확장되지 않습니다. operator.admin을 명시적으로 포함하면 프록시로 인증된 모든 사용자가 전체 관리자 권한을 자동 승인받을 수 있으며, 권한 범위가 없는 요청에도 전체 관리자 권한이 자동으로 부여됩니다. 또한 보안 감사에서 심각한 문제로 보고되고 Gateway 시작 시 경고가 표시됩니다.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Gateway 바인딩 모드`},help:{"v1-1unqude-4y":`인터페이스 노출을 제어하는 네트워크 바인딩 프로필입니다. "auto", "lan", "loopback", "custom", "tailnet" 중에서 선택합니다. 로컬에서만 사용하려면 "loopback"을 유지하세요. "auto"는 모든 인터페이스를 노출할 수 있습니다.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI 에이전트`},help:{"v1-1qqo8m2-5a":`Gateway 세션 카탈로그에 노출된 외부 CLI 세션 엔진을 Control UI에서 검색할 수 있도록 합니다. 기본적으로 활성화되어 있으며, 비활성화하면 새 세션의 모델 선택기에서 해당 엔진을 시작할 수 없습니다.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI 에이전트 활성화`},help:{"v1-ufu7fx-8p":`true이면 카탈로그 기반 CLI 에이전트를 Control UI의 새 세션 모델 선택기에 표시합니다(기본값: true). CLI 에이전트와 네이티브 CLI 세션 생성을 비활성화하려면 false로 설정하세요. 세션 생성 기능이 있다고 명시한 카탈로그만 표시되며, Gateway가 세션 카탈로그 지원을 알리지 않으면 선택기는 숨겨진 상태로 유지됩니다.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`활성화 여부, 경로 지정, 브라우저 출처 및 인증 보안 강화 동작을 포함한 Control UI 호스팅 설정입니다. 인터넷에 공개하는 배포 전에는 UI 노출을 최소화하고 강력한 인증 제어를 함께 적용하세요.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Control UI 허용 출처`},help:{"v1-1stgitk-9i":`Control UI/WebChat WebSocket 연결에 허용되는 브라우저 출처입니다(전체 출처만 허용, 예: https://control.example.com). 위험한 Host 헤더 대체 동작을 명시적으로 활성화하지 않는 한, 루프백이 아닌 주소에 Control UI를 배포할 때 필수입니다. ["*"]로 설정하면 모든 브라우저 출처를 허용하므로 엄격히 통제된 로컬 테스트 외에는 사용하지 마세요.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Control UI 임베드의 외부 URL 허용`},help:{"v1-obwpfg-6s":`호스팅된 임베드에서 외부 http(s) 절대 URL을 로드하도록 허용하는 위험한 설정입니다. Control UI에서 신뢰할 수 있는 타사 페이지를 의도적으로 임베드하는 경우가 아니라면 꺼 두세요. 호스팅된 /__openclaw__/canvas 및 /__openclaw__/a2ui 문서에는 이 설정이 필요하지 않습니다.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`링크 파비콘 자동 가져오기`},help:{"v1-bn9u34-ag":`Gateway를 통해 링크 파비콘과 브라우저 탭의 소셜 미리보기를 가져옵니다(기본적으로 켜짐). 브라우저 탭 카드는 브라우저 쿠키나 사이트 인증 정보 없이 공개 페이지 메타데이터와 페이지에 명시된 이미지를 불러옵니다. 모든 요청에는 엄격한 SSRF 검사와 처리 범위가 제한된 HTML/이미지 처리가 적용됩니다. false로 설정하면 파비콘과 페이지 미리보기를 자동으로 가져오는 기능이 모두 비활성화됩니다. 실시간 브라우저 스크린샷에는 영향을 주지 않습니다.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Control UI 기본 경로`},help:{"v1-1dx68ar-1w":`Control UI가 제공되는 URL의 선택적 접두사입니다(예: /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Control UI 커뮤니티 초대`},help:{"v1-1rz3zsx-73":`이 Gateway에서 제공하는 Control UI에 Discord 커뮤니티 초대를 표시합니다(기본적으로 켜짐). 이 UI 배포를 사용하는 모든 브라우저에서 숨기려면 false로 설정하세요. 변경 사항은 브라우저를 새로고침하거나 다시 연결한 후 적용됩니다. 다시 활성화해도 브라우저별로 저장된 초대 닫기 상태는 유지됩니다.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Host 헤더 기반 출처 폴백 허용(위험)`},help:{"v1-1t1qi4c-7v":`Control UI/WebChat의 WebSocket 검사에서 Host 헤더 기반 출처 폴백을 활성화하는 위험한 설정입니다. 이 모드는 배포 환경에서 의도적으로 Host 헤더 기반 출처 정책을 사용하는 경우 지원됩니다. 보안을 강화하기 위한 권장 기본 방식은 여전히 gateway.controlUi.allowedOrigins를 명시적으로 설정하는 것입니다.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Control UI 임베드 샌드박스 모드`},help:{"v1-d54l3a-7c":'호스팅된 Control UI 임베드의 iframe 샌드박스 정책입니다. "strict"는 스크립트를 비활성화하고, "scripts"는 출처 격리를 유지하면서 대화형 임베드를 허용하며(기본값), "trusted"는 의도적으로 더 높은 권한이 필요한 동일 사이트 문서에 `allow-same-origin`을 추가합니다.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI 활성화`},help:{"v1-1hhyymc-4w":`true이면 Gateway HTTP 프로세스에서 Gateway Control UI를 제공합니다. 로컬 관리에 사용하려면 활성화 상태를 유지하고, 외부 제어 인터페이스로 대체하는 경우 비활성화하세요.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Control UI 환경`},help:{"v1-paarso-4n":`Control UI 띠, 에이전트 아바타, 알약 모양 라벨, 브라우저 제목 및 파비콘에 표시되는 선택적 공개 환경 식별 정보입니다. 기본 모양을 유지하려면 생략하세요.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Control UI 환경 색상`},help:{"v1-mp6cta-2i":`이름으로 지정하는 환경 색상 팔레트: teal, amber, purple, coral, pink, blue, green, red 또는 gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Control UI 환경 라벨`},help:{"v1-1njve3z-3z":`Control UI 및 브라우저 탭에 표시되는 환경 라벨입니다. 앞뒤 공백은 제거되며, 라벨은 1~24자여야 합니다.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`실험적 Control UI 기능`},help:{"v1-1qobi2m-3g":`선택적으로 활성화할 수 있는 Control UI 실험 기능입니다. 이러한 기능은 릴리스마다 변경될 수 있으며, 명시적으로 활성화하지 않으면 비활성화 상태로 유지됩니다.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`사용자 지정 플러그인 UI`},help:{"v1-108u6ts-9e":`사용자가 설치한 플러그인이 Control UI에서 네이티브 JavaScript를 실행할 수 있도록 허용합니다(기본값: false). 기본 제공 플러그인 보기는 계속 사용할 수 있습니다. 사용자 지정 UI는 로그인한 운영자의 Gateway 권한을 공유하므로 신뢰하는 플러그인에 대해서만 활성화하세요. 변경 사항은 Gateway를 다시 시작하지 않고 적용됩니다. 이전에 로드된 플러그인 코드를 지우려면 열려 있는 Control UI 페이지를 새로고침하세요.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Control UI GitHub 서비스 인증 정보`},help:{"v1-1p31phh-d6":`관리형 ID 없이 Control UI 프로젝트 검색과 GitHub 호버 미리보기를 사용하기 위한 SecretRef 기반 서비스 자격 증명입니다. 호버 미리보기는 선택한 에이전트에 구성된 GitHub ID를 우선 사용하며, 재정의가 없으면 시스템 ID를 상속합니다. 서비스 소유권을 명확히 하려면 명시적으로 구성하는 것이 좋습니다. 이 설정을 생략하면 공유 Gateway 프로세스 환경의 GH_TOKEN/GITHUB_TOKEN 폴백이 유지됩니다. 명시적으로 구성한 자격 증명을 사용할 수 없으면 접근이 차단됩니다.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Control UI 리소스 루트`},help:{"v1-elck04-25":`Control UI 리소스의 파일 시스템 루트입니다(선택 사항, 기본값: dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Control UI 세션 관찰자`},help:{"v1-1ahs80-8a":`각 에이전트의 유틸리티 모델을 사용해 구독 중인 Control UI 클라이언트에 실시간 세션 상태 요약을 제공합니다(기본적으로 켜짐). false로 설정하면 Gateway 전체에서 관찰자 모델 호출이 비활성화됩니다. agents.defaults.utilityModel을 빈 문자열로 설정하면 이 설정을 재정의하지 않은 에이전트의 유틸리티 모델 기반 관찰이 비활성화됩니다.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Gateway 사용자 지정 바인딩 호스트`},help:{"v1-lwjcyo-4d":`사용자 지정 바인딩에 사용할 IPv4 주소입니다. 특정 IPv4 주소를 사용하는 경우 127.0.0.1에도 동일한 Gateway 포트가 필요합니다. 모든 인터페이스에 노출해야 하는 경우가 아니라면 0.0.0.0은 사용하지 마세요.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`Gateway HTTP API`},help:{"v1-ebtex7-4j":`엔드포인트 활성화 설정과 전송 계층의 API 노출 제어를 모아 놓은 Gateway HTTP API 구성입니다. 공격 표면을 줄이려면 필요한 엔드포인트만 활성화하세요.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Gateway HTTP 엔드포인트`},help:{"v1-1a0r104-55":`호환성 경로와 선택적 통합을 위한 Gateway API의 HTTP 엔드포인트 기능 설정입니다. 엔드포인트를 신중하게 활성화하고 배포 후 액세스 패턴을 모니터링하세요.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`OpenAI Chat Completions 엔드포인트`},help:{"v1-1271mpb-2b":"OpenAI 호환 `POST /v1/chat/completions` 엔드포인트를 활성화합니다(기본값: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`OpenAI Chat Completions 이미지 제한`},help:{"v1-xgscw1-20":"OpenAI 호환 `image_url` 부분의 이미지 가져오기 및 검증 설정입니다."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`OpenAI Chat Completions 이미지 MIME 허용 목록`},help:{"v1-1guijf3-1t":"`image_url` 부분에 허용되는 MIME 유형입니다(대소문자를 구분하지 않는 목록)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`OpenAI Chat Completions 이미지 URL 허용`},help:{"v1-55cb3n-47":"`image_url` 부분에 대해 서버 측 URL 가져오기를 허용합니다(기본값: false, 데이터 URI는 계속 지원됨). URL 가져오기를 완전히 비활성화하려면 이 값을 `false`로 설정하세요."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`OpenAI Chat Completions 이미지 최대 바이트 수`},help:{"v1-d920yx-1s":"가져오거나 디코딩한 `image_url` 이미지당 최대 바이트 수입니다(기본값: 10MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`OpenAI Chat Completions 이미지 최대 리디렉션 횟수`},help:{"v1-1enujsk-1z":"`image_url` URL에서 이미지를 가져올 때 허용되는 최대 HTTP 리디렉션 횟수입니다(기본값: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`OpenAI Chat Completions 이미지 제한 시간(ms)`},help:{"v1-89w2b9-1x":"`image_url` URL에서 이미지를 가져올 때의 제한 시간(밀리초)입니다(기본값: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`OpenAI Chat Completions 이미지 URL 허용 목록`},help:{"v1-n4hlt1-4r":"`image_url` URL에서 이미지를 가져올 때 사용할 선택적 호스트 이름 허용 목록입니다. 정확한 호스트 이름과 `*.example.com` 와일드카드를 지원합니다. 목록이 비어 있거나 생략되면 호스트 이름 허용 목록 제한이 적용되지 않습니다."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Gateway HTTP 보안 헤더`},help:{"v1-n8z1hb-44":`Gateway 프로세스 자체에서 적용하는 선택적 HTTP 응답 보안 헤더입니다. TLS가 리버스 프록시에서 종료되는 경우 해당 프록시에서 설정하는 것이 좋습니다.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`엄격한 전송 보안 헤더`},help:{"v1-1buwhc3-3v":`Strict-Transport-Security 응답 헤더의 값입니다. 완전히 제어할 수 있는 HTTPS 출처에만 설정하세요. 명시적으로 비활성화하려면 false를 사용하세요.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway 모드`},help:{"v1-nfjirv-5m":`Gateway 작동 모드: "local"은 이 호스트에서 채널과 에이전트 런타임을 실행하고, "remote"는 원격 전송을 통해 연결합니다. 의도적으로 분리된 원격 Gateway 구성을 운영하는 경우가 아니라면 "local"을 유지하세요.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Gateway 노드 Skills 활성화`},help:{"v1-1xwu6at-3g":`페어링된 노드가 연결되어 있는 동안 해당 노드에서 게시한 Skills를 허용합니다(기본값: true). 노드에서 게시한 Skills를 무시하려면 false로 설정하세요.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Gateway 노드 브라우저 모드`},help:{"v1-oeu1nc-69":`노드 브라우저 라우팅("auto" = 호스트 브라우저를 우선 사용하고, 로컬 기능을 사용할 수 없으면 연결된 단일 브라우저 노드를 사용; "manual" = 명시적인 노드 선택 또는 고정 설정 필요; "off" = 노드 라우팅 비활성화).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Gateway 노드 브라우저 고정`},help:{"v1-1cykty2-1p":`브라우저 라우팅을 특정 노드 ID 또는 이름으로 고정합니다(선택 사항).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Gateway 노드 허용 목록(추가 명령)`},help:{"v1-6l4otb-5m":"Gateway 기본값 외에 추가로 허용할 node.invoke 명령입니다(명령 문자열 배열). 여기서 위험한 명령을 활성화하면 보안에 민감한 재정의로 간주되어 `openclaw security audit`에서 경고가 표시됩니다."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Gateway 노드 차단 목록`},help:{"v1-u7c8wx-53":"노드가 선언한 명령이나 기본 허용 목록에 포함되어 있어도 차단할 노드 명령 이름입니다(명령 이름이 정확히 일치하는 경우에만 적용, 예: `system.run`; 해당 명령 내부의 셸 텍스트는 검사하지 않음)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Gateway 노드 페어링`},help:{"v1-gldsi2-4s":`노드 페어링 정책 설정입니다. SSH 검증을 통한 자동 승인은 기본적으로 활성화됩니다. CIDR 자동 승인은 신뢰할 수 있는 CIDR/IP 허용 목록을 명시적으로 구성하지 않으면 비활성화된 상태로 유지됩니다.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`Gateway 노드 페어링 자동 승인 CIDR`},help:{"v1-1m6jsxj-6x":`요청된 권한 범위가 없는 노드 역할 기기의 최초 페어링을 자동 승인하기 위한 선택적 CIDR/IP 허용 목록입니다. 설정하지 않으면 비활성화됩니다. 운영자, 브라우저, Control UI의 페어링과 역할, 권한 범위, 메타데이터 또는 공개 키를 업그레이드하는 모든 페어링에는 여전히 수동 승인이 필요합니다.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Gateway 노드 페어링 로컬 자동 승인`},help:{"v1-glzm36-41":`신뢰할 수 있는 로컬 페어링과 접근 권한 업그레이드를 별도 알림 없이 승인합니다(기본값: true). 편의성 대신 모든 기기에 대한 명시적 승인을 요구하려면 false로 설정하세요.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Gateway 노드 페어링 SSH 검증`},help:{"v1-1e4da92-ct":"노드 역할 기기의 최초 페어링에 대한 SSH 검증 기반 자동 승인입니다(기본값: 활성화). Gateway는 페어링 호스트에 SSH로 역접속하고(BatchMode, 엄격한 호스트 키 검사), 원격 `openclaw node identity` 출력이 승인 대기 중인 기기 키와 일치하는 경우에만 승인합니다. SSH 검증을 비활성화하려면 false로 설정하세요(계속 활성 상태로 유지되는 autoApproveCidrs와는 별개). 수동 페어링만 허용하려면 autoApproveCidrs 설정도 해제하세요. user/identity/timeoutMs/cidrs를 재정의하려면 객체를 전달하세요."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Gateway 노드 플러그인 도구`},help:{"v1-1c24iq3-28":`페어링된 노드가 에이전트에 표시되는 플러그인 도구 설명자를 게시할 수 있는지 제어합니다.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Gateway 노드 플러그인 도구 활성화`},help:{"v1-14lgfu6-47":`페어링된 노드가 게시하는 에이전트에 표시되는 플러그인 도구 설명자를 수락합니다(기본값: true). 노드가 게시한 모든 플러그인 도구를 무시하고 제거하려면 false로 설정하세요.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway 포트`},help:{"v1-for8t5-54":`Gateway 리스너가 API, Control UI 및 채널용 인그레스 경로에 사용하는 TCP 포트입니다. 전용 포트를 사용하고 리버스 프록시나 로컬 개발 서비스와의 충돌을 피하세요.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway 포털`},help:{"v1-1v2lkw9-1c":`포털 게시 및 비공개 인그레스 설정입니다.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`비공개 포털 인그레스`},help:{"v1-20w4gq-69":`운영자가 관리하는 선택적 비공개 HTTPS 와일드카드 리버스 프록시입니다. 원본 Host, 경로 및 WebSocket 업그레이드를 전용 루프백 리스너로 전달하세요. 포털 Bearer 인증은 여전히 필요합니다. Gateway를 다시 시작해야 합니다.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`포털 와일드카드 도메인`},help:{"v1-1ipbfad-53":`임의의 포털 하위 도메인을 위한 DNS 도메인 이름입니다(예: previews.example.net). 와일드카드 DNS와 HTTPS를 비공개로 구성하세요. Gateway 또는 Control UI의 호스트 이름 네임스페이스를 공유하지 마세요.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`포털 인그레스 루프백 포트`},help:{"v1-1mb98cv-4g":`비공개 와일드카드 HTTPS 프록시의 요청을 수신하는 전용 루프백 HTTP 포트입니다. Gateway 포트와 달라야 합니다. 공개 HTTPS 포트가 아닌 백엔드 포트입니다.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Gateway 공개 오리진`},help:{"v1-17vekvx-87":`외부에서 접근할 수 있는 Gateway의 HTTPS 오리진입니다. HTTP는 localhost, 127.0.0.1 또는 [::1]에서만 허용됩니다. 요청자별 MCP OAuth는 이를 사용하여 /oauth/mcp/callback 경로의 콜백 URL을 구성합니다. 채널 세션 링크와 플러그인이 생성한 뷰어 링크는 이를 사용하여 Control UI 및 Gateway 경로에 접근합니다.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gateway 푸시 전송`},help:{"v1-h23oz7-5s":`Gateway가 페어링된 기기를 깨우거나 알림을 보내야 할 때 사용하는 푸시 전송 설정입니다. 공식 iOS 빌드용 릴레이 기반 APNs를 여기에서 구성하세요. 로컬/수동 빌드의 직접 APNs 인증은 계속 환경 변수를 기반으로 합니다.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gateway APNs 전송`},help:{"v1-4bbafr-4e":`이 Gateway에 페어링된 iOS 기기의 APNs 전송 설정입니다. 외부 푸시 릴레이를 통해 등록하는 공식 App Store 빌드에는 릴레이 설정을 사용하세요.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Gateway APNs 릴레이`},help:{"v1-7glbel-6x":`릴레이 기반 APNs 전송을 위한 외부 릴레이 설정입니다. 페어링된 공식 iOS 빌드가 릴레이 기반 등록 정보를 게시하면, 게이트웨이는 push.test, 깨우기 신호, 재연결 시 깨우기에 기본적으로 호스팅된 OpenClaw 릴레이를 사용하거나 이 사용자 지정 릴레이를 사용합니다.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Gateway APNs 릴레이 기본 URL`},help:{"v1-1o8mgnq-69":`공식 App Store iOS 빌드에서 사용하는 외부 APNs 릴레이 서비스의 선택적 사용자 지정 기본 HTTPS URL입니다. 등록 및 전송 트래픽이 동일한 배포 환경에 도달하도록 iOS 빌드에 내장된 릴레이 URL과 일치시켜 주세요.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Gateway APNs 릴레이 시간 제한(ms)`},help:{"v1-a0jkb1-4z":`게이트웨이에서 APNs 릴레이로 보내는 릴레이 전송 요청의 시간 제한(밀리초)입니다(기본값: 10000). 릴레이나 네트워크가 느리면 값을 늘리고, 깨우기 시도를 더 빨리 실패 처리하려면 값을 줄이세요.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`설정 다시 로드`},help:{"v1-d02mvq-4w":`편집 내용을 적용하는 방식과 전체 재시작 시점을 결정하는 실시간 설정 다시 로드 정책입니다. 다시 로드 내부 동작을 디버깅하는 경우가 아니라면, 운영 중 업데이트를 가장 안전하게 적용할 수 있도록 하이브리드 동작을 유지하세요.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`설정 다시 로드 모드`},help:{"v1-1q1etcf-3m":`설정 편집 내용을 적용하는 방식을 제어합니다. "off"는 실시간 편집을 무시하며, "hybrid"는 재시작 없이 안전하게 적용할 수 있는 변경 사항을 먼저 적용한 후 필요한 경우 재시작합니다.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`원격 Gateway`},help:{"v1-6xv7gd-5a":`이 인스턴스가 다른 런타임 호스트에 대한 프록시로 작동할 때 직접 연결 또는 SSH 전송에 사용하는 원격 게이트웨이 연결 설정입니다. 호스트를 분리하여 운영하도록 의도적으로 구성한 경우에만 원격 모드를 사용하세요.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`원격 Gateway 에지 인증 헤더`},help:{"v1-jg9p7d-5o":`설정된 원격 Gateway 앞에 있는 ID 인식 프록시에 제공되는 시크릿 기반 HTTP 헤더입니다. 헤더는 WSS를 통해 gateway.remote.url의 정확한 오리진으로만 전송되며 리디렉션을 따르지 않습니다.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`원격 Gateway 비밀번호`},help:{"v1-16jc0yx-7y":`이 클라이언트를 원격 Gateway에 인증하기 위해 password 필드로 전송되는 공유 시크릿입니다. 서버의 gateway.auth.mode에 따라 설정된 시크릿이 선택되며, 클라이언트의 token 또는 password 필드 중 어느 쪽으로 전달해도 허용됩니다. 이 시크릿은 외부에서 관리하고 커밋되는 설정에 일반 텍스트 값을 넣지 마세요.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`원격 Gateway SSH 호스트 키 정책`},help:{"v1-7qoxtb-49":`macOS SSH 호스트 키 검증 정책입니다. "strict"는 이미 신뢰된 호스트 키를 요구하며, "openssh"는 적용 중인 OpenSSH 설정에 명시적으로 위임합니다.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`원격 Gateway SSH 인증 키`},help:{"v1-hz2hsm-1f":`선택 사항인 SSH 인증 키 파일 경로입니다(ssh -i에 전달됨).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`원격 Gateway SSH 대상`},help:{"v1-85w39w-2t":`SSH를 통한 원격 Gateway 연결입니다(Gateway 포트를 localhost로 터널링). 형식: user@host 또는 user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`원격 Gateway TLS 지문`},help:{"v1-1ri16lk-23":`원격 Gateway의 예상 sha256 TLS 지문입니다(중간자 공격을 방지하기 위해 고정).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`원격 Gateway 토큰`},help:{"v1-1pb9q8w-7v":`이 클라이언트를 원격 Gateway에 인증하기 위해 token 필드로 전송되는 공유 비밀 값입니다. 서버의 gateway.auth.mode에 따라 설정된 비밀 값이 선택되며, 클라이언트의 token 필드와 password 필드 중 어느 쪽이든 허용됩니다. 비밀 값/환경 변수 치환을 통해 저장하고 원격 Gateway 인증 변경 시 함께 교체하세요.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`원격 Gateway 전송 방식`},help:{"v1-1acfs7m-54":`원격 연결 전송 방식입니다. "direct"는 설정된 URL로 연결하고, "ssh"는 SSH 터널을 통해 연결합니다. 원격 포트를 노출하지 않고 암호화된 터널 연결이 필요한 경우 SSH를 사용하세요.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`원격 Gateway URL`},help:{"v1-va7exe-1b":`원격 Gateway WebSocket URL(ws:// 또는 wss://)입니다.`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Gateway 운영자 역할`},help:{"v1-b59sc5-6w":`팀 Gateway를 위한 선택적 프로필 연결 운영자 역할입니다. 이름이 지정된 각 역할은 다른 사용자의 세션에 대한 접근, 샌드박스 격리, 세션 및 실행 에이전트, 부여된 운영자 권한 범위를 제어합니다. 이 섹션을 생략하면 기존 운영자 동작이 유지됩니다.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`기본 운영자 역할`},help:{"v1-1v8add8-4u":`운영자 역할이 설정된 경우, 유효한 명시적 역할 할당이 없는 인증된 프로필에 할당되는 필수 역할입니다. 이름은 설정된 역할 정의의 이름과 일치해야 합니다.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`운영자 역할 정의`},help:{"v1-uv91an-53":`관리자가 이름을 지정한 비어 있지 않은 역할 정의입니다. 인증된 사용자 프로필에 적용되는 사전 정의된 세션 공유, 샌드박스 격리, 에이전트 접근 및 운영자 권한 범위 정책을 묶어서 정의합니다.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`운영자 역할 정의`},help:{"v1-p8tfws-6q":`이름이 지정된 운영자 역할 하나입니다. 각 정의에는 세션 공유 정책, 허용되는 세션 및 실행 에이전트, 운영자 권한 범위의 상한을 명시해야 합니다. 또한 새로 생성되는 세션에 샌드박스 격리를 요구하고 플러그인 접근 정책을 지정할 수 있습니다.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`운영자 역할 접근 정책 플러그인`},help:{"v1-1gq4q08-9n":`이 역할을 승인해야 하는 Gateway 접근 정책을 제공하는 플러그인의 정확한 ID로, 선택 사항입니다. 플러그인이 없거나 비활성화되어 있거나 로드에 실패하거나 현재 유효한 권한을 제공하지 않으면 접근이 거부됩니다. 사용할 수 없는 플러그인 ID도 유효한 구성으로 유지되므로, 독립적인 직원 역할과 Gateway 소유자가 접근을 복구할 수 있습니다. 이 필드를 생략하면 플러그인 의존성이 추가되지 않습니다.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`운영자 역할에 허용된 에이전트`},help:{"v1-fvun18-4v":`이 역할이 세션을 생성하거나 실행을 시작할 때 사용할 수 있는 에이전트입니다. 모든 에이전트를 허용하려면 "*"를 설정하고, 특정 에이전트만 허용하려면 해당 에이전트 ID를 나열하세요. 세션 생성과 실행 시작을 모두 비활성화하려면 빈 목록을 사용하세요.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`운영자 역할의 샌드박스 격리`},help:{"v1-sknx21-66":`새로 생성되는 세션의 실행 격리 방식입니다. "inherit"(기본값)는 에이전트 정책을 사용합니다. "required"는 에이전트의 샌드박스 모드가 꺼져 있어도 샌드박스를 영구적으로 요구하며, 백엔드를 사용할 수 없으면 실행을 차단합니다.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`운영자 역할의 권한 범위 상한`},help:{"v1-1selr2i-4s":`이 역할의 최대 연결 권한으로 부여되는 운영자 권한 범위의 한정된 목록입니다. 요청된 권한 범위, 페어링된 권한 범위, 신원에 따라 부여된 권한 범위, 상향된 권한 범위에는 이 목록과의 교집합만 적용됩니다.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`운영자 역할의 세션 접근`},help:{"v1-hsoiop-45":`인증된 다른 사용자가 생성한 세션에 대해 이 역할에 부여되는 세션 공유 권한입니다. 사용자는 자신의 세션에 계속 소유자로서 접근할 수 있습니다.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`운영자 역할의 다른 세션 접근`},help:{"v1-vf8umx-5r":`다른 사용자의 세션에 대한 접근 권한입니다. "none"은 세션을 숨기고, "view"는 읽기를 허용하며, "suggest"는 제안 흐름을 허용하고, "write"는 참여를 허용합니다. 명시적인 세션 멤버 자격으로 추가 접근 권한을 얻을 수 있습니다.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Gateway Tailscale`},help:{"v1-6ar9o-4x":`Serve/Funnel을 통한 외부 노출과 Gateway 시작/종료 시 수명 주기 처리를 위한 Tailscale 통합 설정입니다. 배포 환경에서 의도적으로 Tailscale 인그레스를 사용하는 경우가 아니라면 꺼 두세요.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Gateway Tailscale 모드`},help:{"v1-6l2099-5a":`비공개 또는 공개 노출 경로를 위한 Tailscale 게시 모드로, "off", "serve", "funnel" 중 하나를 사용합니다. tailnet 전용 접근에는 "serve"를 사용하고, 공용 인터넷에서 접근할 수 있어야 하는 경우에만 "funnel"을 사용하세요.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Gateway Tailscale 외부 Funnel 마이그레이션 보호 장치`},help:{"v1-1mntkor-7q":`mode='serve'를 위한 더 이상 사용되지 않는 마이그레이션 보호 장치입니다. 외부 Funnel이 여전히 일반 Gateway 리스너를 대상으로 하는 경우, OpenClaw는 노출 설정을 변경하지 않고 비밀번호 인증을 구성하고 모드를 'funnel'로 마이그레이션할 때까지 플러그인 인증을 거친 웹훅만 사용할 수 있다는 경고를 표시합니다.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`운영자 터미널`},help:{"v1-18f5rgm-8b":`Control UI와 모바일 클라이언트에 제공되는 운영자 터미널입니다. Gateway 호스트에서 실행되는 PTY 기반 셸로, 관리자 범위의 운영자 세션으로 사용이 제한됩니다. 대상 에이전트의 작업 공간에서 시작되며, 완전히 샌드박스 처리된 에이전트(sandbox.mode 'all')에는 제한 없는 호스트 셸을 제공하는 대신 실행을 거부합니다.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`운영자 터미널의 분리된 세션 시간 제한`},help:{"v1-k6qbgr-9e":`연결이 끊긴 후(노트북 절전, 페이지 새로고침 등) 터미널 세션이 유지되는 시간(초)입니다. 이 시간 동안 terminal.attach로 다시 연결하면 최근 출력이 재생됩니다. 연결이 끊기는 즉시 세션을 종료하려면 0으로 설정하세요. 기본값: 300(5분). 연결이 끊긴 세션에서도 명령은 계속 실행되므로 공유 호스트나 외부에 노출된 호스트에서는 이 시간을 줄이세요.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`운영자 터미널 활성화`},help:{"v1-1nez06v-7p":`관리자 권한 범위의 클라이언트에 운영자 터미널을 활성화합니다(기본값: true). Gateway 프로세스 환경을 사용하는 브라우저/모바일 셸이 노출됩니다. 관리자 운영자에게 호스트 셸을 제공하면 안 되는 배포 환경에서는 false로 설정하여 비활성화하세요. 변경 사항은 Gateway를 다시 시작하지 않아도 적용됩니다.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`운영자 터미널 셸`},help:{"v1-19mfe6t-5i":`운영자 터미널에서 실행할 셸 실행 파일입니다. 설정하지 않으면 호스트 로그인 셸(Unix의 $SHELL, Windows의 %ComSpec%)을 사용합니다. 일관된 운영자 환경을 유지하려면 특정 인터프리터를 명시적으로 지정하세요.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`Gateway TLS`},help:{"v1-1dx77dq-4z":`Gateway 프로세스에서 직접 HTTPS 연결을 종단 처리하기 위한 TLS 인증서 및 키 설정입니다. 프로덕션 환경에서는 인증서를 명시적으로 지정하고, 신뢰할 수 없는 네트워크에서 평문 통신이 노출되지 않도록 하세요.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Gateway TLS 인증서 자동 생성`},help:{"v1-1ld6uiu-4w":`파일을 명시적으로 설정하지 않은 경우 로컬 TLS 인증서/키 쌍을 자동으로 생성합니다. 로컬/개발 환경에서만 사용하고, 프로덕션 트래픽에는 정식 인증서로 교체하세요.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Gateway TLS CA 경로`},help:{"v1-andqlu-52":`Gateway 경계에서 클라이언트 검증이나 사용자 지정 신뢰 체인 요구 사항에 사용하는 선택적 CA 번들 경로입니다. 배포 환경에 사설 PKI나 사용자 지정 인증서 체인이 포함된 경우 사용하세요.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Gateway TLS 인증서 경로`},help:{"v1-1wznaof-4q":`TLS가 활성화된 경우 Gateway에서 사용하는 TLS 인증서 파일의 파일 시스템 경로입니다. 관리되는 인증서 경로를 사용하고 자동 갱신이 이 위치와 일치하도록 유지하세요.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`Gateway TLS 활성화`},help:{"v1-ykhwp0-4o":`Gateway 리스너에서 TLS 종료를 활성화하여 클라이언트가 HTTPS/WSS로 직접 연결할 수 있도록 합니다. 인터넷에 직접 노출되거나 신뢰할 수 없는 네트워크 경계에 있는 경우 활성화 상태를 유지하세요.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Gateway TLS 키 경로`},help:{"v1-15knri0-4i":`TLS가 활성화된 경우 Gateway에서 사용하는 TLS 개인 키 파일의 파일 시스템 경로입니다. 이 키 파일의 접근 권한을 제한하고 보안 정책에 따라 키를 교체하세요.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Gateway 도구 노출 정책`},help:{"v1-1ffol26-5a":`에이전트/도구 프로필과 별개로 런타임에 사용 가능한 도구를 제한할 수 있는 Gateway 수준의 도구 노출 허용/거부 정책입니다. 포괄적인 긴급 제어와 프로덕션 환경의 보안 강화에 사용하세요.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Gateway 도구 허용 목록`},help:{"v1-163khb1-4y":`런타임에 제한된 도구만 사용할 수 있도록 명시적으로 지정하는 Gateway 수준의 도구 허용 목록입니다. 도구 범위를 엄격하게 제어해야 하는 제한된 환경에서 사용하세요.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Gateway 도구 거부 목록`},help:{"v1-1lhssnf-4o":`하위 수준 정책에서 허용하더라도 위험한 도구를 차단하는 명시적인 Gateway 수준 도구 차단 목록입니다. 긴급 대응과 심층 방어 강화를 위해 차단 규칙을 사용하세요.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`Gateway 신뢰할 수 있는 프록시 CIDR`},help:{"v1-n5zcvf-4f":`전달된 클라이언트 신원 헤더를 제공할 수 있는 상위 프록시의 CIDR/IP 허용 목록입니다. 신뢰할 수 없는 중간 경유지가 사용자를 사칭하지 못하도록 이 목록의 범위를 좁게 유지하세요.`}},hooks:{label:{"v1-j9ywl7-5":`훅`},help:{"v1-1mzh0ry-5v":`외부 이벤트를 OpenClaw의 깨우기 또는 에이전트 작업에 매핑하는 수신 웹훅 자동화 인터페이스입니다. 신뢰할 수 있는 네트워크 외부에 노출하기 전에 명시적인 토큰/세션/에이전트 제어로 접근을 엄격하게 제한하세요.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`훅에서 허용되는 에이전트 ID`},help:{"v1-hree88-7c":`훅 요청과 매핑이 대상으로 지정할 수 있는 실제 적용 에이전트 ID의 허용 목록입니다. agentId가 생략된 경우의 기본 에이전트 라우팅도 포함됩니다. 이를 사용해 자동화 이벤트를 전용 서비스 에이전트로 제한하고, 훅 토큰이 노출될 경우 피해 범위를 줄이세요.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`훅에서 허용되는 세션 키 접두사`},help:{"v1-b346oh-4r":`호출자가 제공하는 키가 활성화된 경우 수신 훅 요청에서 허용되는 세션 키 접두사의 허용 목록입니다. 임의의 세션 키 주입을 방지하려면 접두사 범위를 좁게 설정하세요.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`훅 요청의 세션 키 허용`},help:{"v1-11n9ps-52":`true이면 호출자가 훅 요청에 세션 키를 제공하여 라우팅을 제어할 수 있습니다. 신뢰할 수 있는 연동 주체에게 사용자 지정 세션 스레딩이 명시적으로 필요한 경우가 아니라면 false로 유지하세요.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`훅 기본 세션 키`},help:{"v1-bzdgkn-57":`요청이 허용된 채널을 통해 세션 키를 제공하지 않을 때 훅 전달에 사용하는 대체 세션 키입니다. 서로 관련 없는 자동화 대화가 섞이지 않도록 일정하게 유지되면서도 범위가 제한된 키를 사용하세요.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`훅 활성화`},help:{"v1-1mixmjf-4n":`수신 웹훅 요청을 위한 훅 엔드포인트와 매핑 실행 파이프라인을 활성화합니다. 외부 이벤트를 Gateway로 라우팅하고 있는 경우가 아니라면 비활성화 상태로 유지하세요.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail 훅`},help:{"v1-4cibmt-4r":`Pub/Sub 알림과 선택적 로컬 콜백 제공에 사용하는 Gmail 푸시 통합 설정입니다. 가능하면 전용 Gmail 자동화 계정으로 범위를 제한하세요.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Gmail 훅 계정`},help:{"v1-12l1h96-4v":`이 훅 통합에서 Gmail 감시 및 구독 작업에 사용하는 Google 계정 식별자입니다. 작업 권한을 분리하려면 자동화 전용 메일 계정을 사용하세요.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Gmail 훅의 안전하지 않은 외부 콘텐츠 허용`},help:{"v1-1w3gdvs-55":`활성화하면 정제 수준이 낮은 외부 Gmail 콘텐츠도 처리 과정에 전달할 수 있습니다. 더 안전한 기본 설정을 위해 비활성화 상태로 유지하고, 변환 과정을 통제할 수 있는 신뢰할 만한 메일 스트림에만 활성화하세요.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Gmail 훅 콜백 URL`},help:{"v1-19fhn6q-4z":`Gmail 또는 중개 서비스가 이 훅 파이프라인으로 알림을 전달하기 위해 호출하는 공개 콜백 URL입니다. 토큰 검증과 네트워크 노출 제한을 통해 이 URL을 보호하세요.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Gmail 훅 본문 포함`},help:{"v1-14cf1c3-52":`true이면 후속 매핑/에이전트 처리를 위해 이메일 본문을 가져와 포함합니다. 페이로드 크기와 데이터 민감도가 증가하므로 본문 텍스트가 필요한 경우가 아니면 false로 유지하세요.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Gmail 훅 라벨`},help:{"v1-9zpdg8-4g":`특정 라벨이 지정된 메시지만 훅 이벤트를 트리거하도록 제한하는 선택적 Gmail 라벨 필터입니다. 관련 없는 받은편지함 메시지가 자동화에 과도하게 유입되지 않도록 필터 범위를 좁게 유지하세요.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Gmail 훅 최대 본문 바이트 수`},help:{"v1-2aaxx1-4b":`includeBody가 활성화된 경우 이벤트당 처리할 Gmail 페이로드의 최대 바이트 수입니다. 대용량 메시지 처리 비용과 위험을 줄이려면 제한값을 보수적으로 설정하세요.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Gmail 훅 모델 재정의`},help:{"v1-1var65t-59":`메일함 자동화에 전용 모델 동작이 필요한 경우 Gmail로 트리거된 실행에 적용할 선택적 모델 재정의입니다. 메일함 작업에 특화된 처리가 필요하지 않으면 에이전트 기본값을 상속하도록 설정하지 않은 상태로 두세요.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Gmail 훅 푸시 토큰`},help:{"v1-h1vx01-4o":`알림을 처리하기 전에 Gmail 푸시 훅 콜백에 필요한 공유 비밀 토큰입니다. 환경 변수 치환을 사용하고, 콜백 엔드포인트가 외부에 노출된 경우 토큰을 교체하세요.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Gmail 훅 갱신 간격(분)`},help:{"v1-pr1z9-49":`Gmail 감시 구독의 만료를 방지하기 위한 갱신 주기(분)입니다. 제공업체의 만료 기간보다 짧게 설정하고 로그에서 갱신 실패를 모니터링하세요.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Gmail 훅 로컬 서버`},help:{"v1-hom4wq-54":`별도의 인그레스 계층 없이 Gmail 알림을 직접 수신하기 위한 로컬 콜백 서버 설정 블록입니다. 이 프로세스가 웹훅 트래픽을 직접 처리해야 하는 경우에만 활성화하세요.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Gmail 훅 서버 바인딩 주소`},help:{"v1-55bieu-4d":`훅을 직접 제공할 때 사용하는 로컬 Gmail 콜백 HTTP 서버의 바인딩 주소입니다. 외부 인그레스가 명시적으로 필요한 경우가 아니라면 루프백 전용으로 유지하세요.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Gmail 훅 서버 경로`},help:{"v1-1jqhcw4-4h":`로컬 Gmail 콜백 서버에서 푸시 알림을 수신하는 HTTP 경로입니다. 이벤트가 누락되지 않도록 구독 설정과 일치하게 유지하세요.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Gmail 훅 서버 포트`},help:{"v1-1yku7dz-43":`serve 모드가 활성화된 경우 로컬 Gmail 콜백 HTTP 서버에서 사용하는 포트입니다. Gateway/제어 인터페이스와의 충돌을 방지하려면 전용 포트를 사용하세요.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail 훅 구독`},help:{"v1-127h8vg-5b":`설정된 주제에서 Gmail 변경 알림을 수신하기 위해 Gateway가 사용하는 Pub/Sub 구독입니다. 여러 소비자 간에 예기치 않은 경합이 발생하지 않도록 구독 소유권을 명확하게 유지하세요.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Gmail 훅 Tailscale`},help:{"v1-7jzidp-4l":`Serve/Funnel 경로를 통해 Gmail 콜백을 노출하기 위한 Tailscale 노출 설정 블록입니다. 공개 인그레스 경로를 활성화하기 전에 비공개 tailnet 모드를 사용하세요.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Gmail 훅 Tailscale 모드`},help:{"v1-vhm395-4u":`Gmail 콜백을 위한 Tailscale 노출 모드: "off", "serve" 또는 "funnel". 비공개 tailnet 전송에는 "serve"를 사용하고, 공용 인터넷에서의 수신이 필요한 경우에만 "funnel"을 사용하세요.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Gmail 훅 Tailscale 경로`},help:{"v1-fr8qi-4m":`활성화 시 Gmail 콜백 전달을 위해 Tailscale Serve/Funnel이 공개하는 경로입니다. 요청이 의도한 핸들러에 도달하도록 Gmail 웹훅 설정과 일치시키세요.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Gmail 훅 Tailscale 대상`},help:{"v1-1twwxge-47":`Tailscale Serve/Funnel이 요청을 전달하는 로컬 서비스 대상입니다(예: http://127.0.0.1:8787). 라우팅의 모호성을 피하려면 루프백 대상을 명시적으로 지정하세요.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Gmail 훅 사고 수준 재정의`},help:{"v1-17owk9q-4z":`Gmail로 트리거되는 에이전트 실행의 사고 수준을 재정의합니다: "off", "minimal", "low", "medium" 또는 "high". 일상적인 받은편지함 자동화에서는 비용과 지연 시간을 관리할 수 있도록 기본값을 낮게 유지하세요.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Gmail 훅 Pub/Sub 주제`},help:{"v1-iled0e-4p":`Gmail 감시 기능이 이 계정의 변경 알림을 게시하는 데 사용하는 Google Pub/Sub 주제 이름입니다. 감시를 활성화하기 전에 주제의 IAM에서 Gmail에 게시 권한을 부여했는지 확인하세요.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`내부 훅`},help:{"v1-piq9k-4v":`모듈 경로에서 로드되는 기본 제공/사용자 지정 이벤트 핸들러의 내부 훅 런타임 설정입니다. 신뢰할 수 있는 프로세스 내부 자동화에 사용하고 핸들러 로드 범위를 엄격하게 제한하세요.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`내부 훅 활성화`},help:{"v1-1wv0289-4c":`내부 훅 런타임에서 내부 훅과 구성된 항목의 처리를 활성화합니다. 내부 훅을 의도적으로 구성한 경우가 아니라면 비활성화 상태로 유지하세요.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`내부 훅 항목`},help:{"v1-1ovi38l-4o":`구체적인 런타임 핸들러와 메타데이터를 등록하는 데 사용되는 내부 훅 항목 레코드입니다. 운영 환경의 동작을 감사할 수 있도록 항목을 명시적으로 정의하고 버전을 관리하세요.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`내부 훅 로더`},help:{"v1-11re5ph-4p":`시작 시 핸들러 모듈을 검색할 위치를 제어하는 내부 훅 로더 설정입니다. 의도치 않은 모듈 충돌이나 가려짐을 줄이려면 로드 루트 경로를 제한하세요.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`내부 훅 추가 디렉터리`},help:{"v1-1xfdqxg-4c":`기본 로드 경로 외에 내부 훅 모듈을 검색할 추가 디렉터리입니다. 의도치 않은 모듈 가려짐을 줄이려면 디렉터리를 최소한으로 유지하고 관리하세요.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`훅 매핑`},help:{"v1-frhp3v-5i":`수신 훅 요청을 일치시키고 깨우기 또는 에이전트 작업을 선택하는 순서가 지정된 매핑 규칙입니다. 필요에 따라 전달 라우팅을 지정할 수 있습니다. 광범위한 패턴 규칙이 모든 요청과 일치하지 않도록 구체적인 매핑을 먼저 배치하세요.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`훅 매핑 작업`},help:{"v1-1r5zt5f-5f":`매핑 작업 유형입니다. "wake"는 에이전트 깨우기 흐름을 트리거하고, "agent"는 에이전트 처리로 직접 전달합니다. 즉시 실행하려면 "agent"를, 하트비트 기반 처리를 선호하면 "wake"를 사용하세요.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`훅 매핑 에이전트 ID`},help:{"v1-l0uioz-4y":`작업 라우팅에 기본값을 사용하지 않을 때 매핑을 실행할 대상 에이전트 ID입니다. 전용 자동화 에이전트를 사용하면 웹훅 동작을 운영자의 대화형 세션과 분리할 수 있습니다.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`훅 매핑의 안전하지 않은 외부 콘텐츠 허용`},help:{"v1-1np9426-57":`true이면 매핑 콘텐츠가 생성된 메시지에 정제가 덜 된 외부 페이로드 데이터를 포함할 수 있습니다. 기본값은 false로 유지하고, 변환 로직을 검토한 신뢰할 수 있는 소스에 대해서만 활성화하세요.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`훅 매핑 전달 채널`},help:{"v1-oz7pu5-5s":`매핑 출력의 전달 채널을 재정의합니다(예: "last", "telegram", "discord", "slack", "signal", "imessage", "msteams"). 다른 채널로 실수로 전송하지 않도록 채널 재정의 값을 명시적으로 지정하세요.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`훅 매핑 응답 전달`},help:{"v1-12tbbam-5o":`매핑 실행 결과를 채널 대상에 전달할지, 전달 없이 처리할지 제어합니다. 사용자에게 표시되는 출력을 게시하지 않아야 하는 백그라운드 자동화에서는 전달을 비활성화하세요.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`훅 매핑 팬아웃 키`},help:{"v1-1d593op-7e":`매핑이 각 요소별로 작업을 분배할 최상위 페이로드 배열 키입니다. 각 요소는 자체 작업을 실행하며, 템플릿이나 변환에는 배열에 현재 요소만 포함된 페이로드가 전달됩니다. Gmail 사전 설정은 forEach: messages를 사용하므로 일괄 푸시 시 이메일마다 한 번씩 실행됩니다.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`훅 매핑 ID`},help:{"v1-q1t4zw-57":`감사, 문제 해결, 특정 항목 업데이트에 사용되는 훅 매핑 항목의 선택적 고정 식별자입니다. 로그와 설정 변경 내역에서 매핑을 명확하게 참조할 수 있도록 고유한 ID를 사용하세요.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`훅 매핑 일치 조건`},help:{"v1-6u73k2-5a":`작업 라우팅이 적용되기 전에 경로 및 소스 등의 매핑 일치 조건을 묶는 객체입니다. 관련 없는 웹훅 트래픽이 자동화를 실행하지 않도록 일치 조건을 구체적으로 설정하세요.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`훅 매핑 일치 경로`},help:{"v1-1d7dc5j-4k":`훅 매핑의 경로 일치 조건으로, 일반적으로 수신 요청 경로와 비교됩니다. 웹훅 엔드포인트 경로 그룹별로 자동화 동작을 나누려면 이 조건을 사용하세요.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`훅 매핑 일치 소스`},help:{"v1-177zgy7-52":`훅 매핑의 소스 일치 조건으로, 일반적으로 신뢰할 수 있는 업스트림 메타데이터나 어댑터 로직에서 설정됩니다. 재시도 시에도 라우팅 결과가 일관되도록 고정된 소스 식별자를 사용하세요.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`훅 매핑 메시지 템플릿`},help:{"v1-ggqszl-5c":`구조화된 매핑 입력을 대상 작업 경로로 전송할 최종 메시지 내용으로 구성하는 템플릿입니다. 후속 파싱과 동작이 안정적으로 유지되도록 템플릿이 일관된 결과를 생성하게 하세요.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`훅 매핑 모델 재정의`},help:{"v1-10qyo4j-5e":`자동화에 에이전트 기본 모델과 다른 모델을 사용해야 할 때 매핑으로 트리거되는 실행에 적용할 선택적 모델 재정의입니다. 매핑 실행 간 동작을 예측할 수 있도록 필요한 경우에만 사용하세요.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`훅 매핑 이름`},help:{"v1-zrd9tn-4v":`진단 및 운영자용 설정 UI에 사용되는, 사람이 읽기 쉬운 매핑 표시 이름입니다. 장애 검토 시 라우팅 의도를 명확히 파악할 수 있도록 간결하고 설명적인 이름을 사용하세요.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`훅 매핑 세션 키`},help:{"v1-lfnt1n-58":`스레드 연속성을 제어하기 위해 매핑으로 전달되는 메시지에 명시적으로 적용할 세션 키 재정의입니다. 반복되는 이벤트가 관련 없는 대화에 섞이지 않고 서로 연결되도록 범위가 지정된 안정적인 키를 사용하세요.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`훅 매핑 세션 모드`},help:{"v1-1ggtdze-5k":`매핑 세션의 연속성을 제어합니다. "isolated"는 새 실행 세션을 시작하고, "persistent"는 결정된 sessionKey를 재사용합니다. 연동에 지속적인 컨텍스트가 명시적으로 필요한 경우가 아니라면 isolated를 유지하세요.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`훅 매핑 텍스트 템플릿`},help:{"v1-1rg732b-4y":`리치 페이로드 렌더링을 원하지 않거나 지원하지 않을 때 사용하는 텍스트 전용 대체 템플릿입니다. 채팅 전달 화면에 간결하고 일관된 요약 문자열을 제공하려면 이 템플릿을 사용하세요.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`훅 매핑 사고 설정 재정의`},help:{"v1-17hq8me-57":`매핑으로 트리거된 실행에서 지연 시간과 추론 깊이의 균형을 조정하는 선택적 사고 수준 재정의 설정입니다. 더 깊은 추론이 명확히 필요한 경우가 아니라면 대량의 훅을 처리할 때는 low 또는 minimal로 유지하세요.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`훅 매핑 시간 제한(초)`},help:{"v1-1r44ox2-4i":`시간 초과 처리가 적용되기 전까지 매핑 작업 실행에 허용되는 최대 시간입니다. 대량의 웹훅을 보내는 소스에는 더 짧은 제한 시간을 적용하여 대기열에 작업이 쌓이지 않도록 하세요.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`훅 매핑 전달 대상`},help:{"v1-1p7928e-55":`매핑 응답을 고정된 대상으로 라우팅할 때 사용하는, 선택한 채널 내의 대상 식별자입니다. 프로덕션 매핑을 활성화하기 전에 제공업체별 대상 형식을 확인하세요.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`훅 매핑 변환`},help:{"v1-14igxpm-5m":`매핑 작업 처리 전에 수행할 모듈/내보내기 전처리를 정의하는 변환 구성 블록입니다. 검토된 코드 경로의 변환만 사용하고, 자동화 결과를 재현할 수 있도록 동작의 결정성을 유지하세요.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`훅 변환 내보내기`},help:{"v1-atn8v-4b":`변환 모듈에서 호출할 이름 있는 내보내기입니다. 생략하면 모듈의 기본 내보내기를 사용합니다. 한 파일에 여러 변환 핸들러가 있는 경우 이 값을 설정하세요.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`훅 변환 모듈`},help:{"v1-56futq-4v":`전달 전에 수신 페이로드를 다시 작성하기 위해 hooks.transformsDir에서 로드하는 변환 모듈의 상대 경로입니다. 모듈은 로컬에 보관하고 검토를 거쳐야 하며, 경로 탐색 패턴이 포함되지 않도록 하세요.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`훅 매핑 깨우기 모드`},help:{"v1-1dzqfnw-59":`깨우기 예약 모드입니다. "now"는 즉시 깨우고, "next-heartbeat"는 다음 하트비트 주기까지 연기합니다. 약간의 지연을 허용할 수 있는 낮은 우선순위의 자동화에는 지연 모드를 사용하세요.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`훅 엔드포인트 경로`},help:{"v1-1l9ijzv-4u":"Gateway 제어 서버의 훅 엔드포인트에서 사용하는 HTTP 경로입니다(예: `/hooks`). 추측하기 어려운 경로를 사용하고 토큰 검증을 함께 적용하여 다층 방어를 구현하세요."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`훅 프리셋`},help:{"v1-dp8m0l-4v":`표준 매핑과 기본 동작을 초기 설정하기 위해 로드 시 적용하는 이름이 지정된 훅 프리셋 묶음입니다. 운영자가 활성화된 자동화를 감사할 수 있도록 프리셋 사용을 명시하세요.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`훅 인증 토큰`},help:{"v1-1ihf6mv-82":`매핑 실행 전에 요청을 인증하기 위해 훅 수신 지점에서 확인하는 공유 베어러 토큰입니다. 이 토큰의 보유자는 별도의 비소유자 역할이 아니라 훅 수신 인터페이스에 대해 완전히 신뢰할 수 있는 호출자로 취급하세요. 웹훅 엔드포인트에 인터넷으로 접근할 수 있다면 환경 변수 치환을 사용하고 토큰을 정기적으로 교체하세요.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`훅 변환 디렉터리`},help:{"v1-1ayj9p0-4t":`매핑의 transform.module 경로가 참조하는 훅 변환 모듈의 기본 디렉터리입니다. 동적 가져오기를 검토할 수 있고 그 동작을 예측할 수 있도록 통제된 저장소 디렉터리를 사용하세요.`}},logging:{label:{"v1-rq08xq-7":`로깅`},help:{"v1-11an9pb-5e":`심각도, 출력 대상, 형식, 민감한 데이터 마스킹에 대한 로깅 동작을 제어합니다. 유용한 진단 정보를 유지하면서 프로덕션 환경에 적합하도록 로그 수준과 마스킹을 엄격하게 설정하세요.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`감사 원장`},help:{"v1-1lauvy2-6w":`운영자 검토를 위해 메타데이터만 제한적으로 보관하는 감사 기록입니다. 실행 및 도구 기록은 기본적으로 활성화됩니다. 메시지 수명 주기 메타데이터는 개인정보 보호에 민감하므로 별도로 동의하여 활성화해야 합니다. 백그라운드 기록기는 최선형 방식으로 작동하며, 무손실 규정 준수 아카이브가 아닙니다.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`감사 원장 활성화`},help:{"v1-snknxb-4v":`새 실행, 도구 및 활성화된 메시지 감사 이벤트를 기록합니다. 기본값: true. 변경 사항은 즉시 적용됩니다. 수락된 쓰기 작업은 완료되며, 보존된 행은 만료될 때까지 조회할 수 있습니다.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`실행 ID 감사`},help:{"v1-1ucirwv-5b":`특정 실행을 정밀하게 검사할 수 있도록 제한된 범위의 실행 ID 귀속 정보를 보존합니다. 기본값: false. logging.audit.enabled가 필요하며 새로 수락된 실행에 적용됩니다. 기존 컨텍스트는 변경되지 않습니다.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`메시지 감사 범위`},help:{"v1-1yg4lc3-76":`내용을 포함하지 않는 메시지 수명 주기 기록을 제어합니다. "off"(기본값), 확인된 직접 대화만 기록하는 "direct", 직접 대화, 그룹, 채널 및 알 수 없는 대화 유형을 모두 기록하는 "all" 중에서 선택합니다. logging.audit.enabled가 필요합니다. 변경 사항은 이후의 수명 주기 이벤트에 적용됩니다.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`콘솔 로그 수준`},help:{"v1-16badbd-5u":`터미널 출력을 제어하는 콘솔 전용 로그 임계값입니다: "silent", "fatal", "error", "warn", "info", "debug", "trace". 필요한 경우 파일에는 상세한 로그를 유지하면서 로컬 콘솔 출력은 줄이는 데 사용하세요.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`콘솔 로그 스타일`},help:{"v1-d7u0iq-3q":`콘솔 출력 형식입니다: "pretty" 또는 "json". 기계 파싱 파이프라인에는 json을, 사람이 읽기 편한 터미널 워크플로에는 pretty를 사용하세요.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`로그 파일 경로`},help:{"v1-16gaitv-4w":`콘솔 로깅과 함께 또는 콘솔 로깅 대신 로그 출력을 영구 저장할 선택적 파일 경로입니다. 관리되는 쓰기 가능한 경로를 사용하고, 보존 및 순환 설정을 운영 정책에 맞추세요.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`로그 수준`},help:{"v1-1r5yku0-5o":`런타임 로거 출력의 기본 로그 수준 임계값입니다: "silent", "fatal", "error", "warn", "info", "debug", "trace". 운영 환경에서는 "info" 또는 "warn"을 유지하고, 문제 조사 중에만 debug/trace를 사용하세요.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`사용자 지정 마스킹 패턴`},help:{"v1-1esa6eg-7k":`사용자 지정 정규식 문자열은 로그/대화 기록 출력의 기본 문자열 목록을 대체하고, 안전 경계의 UI/도구/진단 규칙에 추가됩니다. 기본 제공되는 폼 본문, 구조화된 인증 정보, AWS 단독 키 보호 기능은 항상 적용됩니다. 배포 환경별 토큰과 식별자를 마스킹하려면 이 설정을 사용하세요.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`OpenClaw에서 관리하는 전역 MCP 서버 정의입니다. 내장 OpenClaw 및 기타 런타임 어댑터는 이러한 서버를 런타임 소유의 프로젝트 설정에 저장하지 않고도 사용할 수 있습니다.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP 앱`},help:{"v1-amyd91-38":`MCP Apps UI 지원. 활성화하면 구성된 MCP 서버가 도구 결과에 대한 대화형 HTML 보기를 제공할 수 있습니다.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps 활성화`},help:{"v1-ghqy98-3w":`MCP Apps 렌더링과 앱-서버 간 브리지를 명시적으로 활성화합니다. 앱 UI 리소스를 제공하도록 구성된 MCP 서버를 신뢰할 수 있는 경우에만 활성화하세요.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`MCP Apps 샌드박스 오리진`},help:{"v1-1sxv3mf-6v":`MCP Apps용 전용 공개 HTTP(S) 오리진(선택 사항)입니다. 리버스 프록시 또는 TLS 종료 지점 뒤에서 사용하고, 구성된 MCP Apps 샌드박스 포트로만 프록시하도록 설정하세요. Control UI 오리진과 달라야 하며, 인증이 필요한 콘텐츠를 제공해서는 안 됩니다.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`MCP Apps 샌드박스 포트`},help:{"v1-1b8n71l-4p":`MCP Apps 샌드박스 전용 수신 포트입니다. 기본값은 Gateway 포트 번호에 1을 더한 값입니다. 다른 로컬 서비스나 Gateway 프로필이 해당 포트를 이미 사용 중이면 사용하지 않는 포트를 설정하세요.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP 서버`},help:{"v1-157ozoz-42":`이름이 지정된 MCP 서버 정의입니다. OpenClaw는 이를 자체 구성에 저장하며, 런타임 어댑터가 실행 시 지원되는 전송 방식을 결정합니다.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`MCP 서버 인증`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP 클라이언트 인증서`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP 클라이언트 키`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP 클라이언트 인증서`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP 클라이언트 키`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP 투영`},help:{"v1-slcmq1-6x":`Codex app-server 스레드에만 적용되는 OpenClaw 투영 메타데이터입니다. ACP 세션이나 일반 Codex 하네스 설정에는 영향을 주지 않습니다. 모든 Codex app-server 에이전트가 Codex의 기본 MCP 승인 동작으로 이 서버를 사용할 수 있도록 하려면 이 블록을 생략하세요.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCP 에이전트`},help:{"v1-8q98n8-67":`Codex app-server 스레드 설정에 이 MCP 서버를 포함할 OpenClaw 에이전트 ID 목록입니다. 선택 사항이며 비어 있지 않아야 합니다. 목록이 비어 있거나 공백만 포함하거나 유효하지 않으면 안전을 위해 적용이 차단됩니다. 생략하면 모든 Codex app-server 에이전트에 서버가 투영됩니다.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Codex MCP 도구 승인`},help:{"v1-1xql0qr-3d":`동일한 서버별 MCP 도구 승인 모드에 대한 Codex 고유 표기입니다. OpenClaw 설정에서는 defaultToolsApprovalMode를 우선 사용하세요.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Codex MCP 도구 승인`},help:{"v1-y5vsqq-3s":`이 서버의 Codex MCP 도구 승인 모드로, 선택 사항입니다. "auto", "prompt" 또는 "approve"를 사용할 수 있습니다. 명시적으로 신뢰하는 MCP 서버에만 사용하세요.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`MCP 연결 제한 시간(ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP 서버 활성화`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`MCP OAuth 인증 프로필`},help:{"v1-fcrb4u-5z":`이 원격 MCP 서버에 현재 Bearer 토큰을 주입하는 데 사용되는 갱신 가능한 인증 프로필 ID입니다. 설정하면 OpenClaw가 런타임에 프로필을 확인하고 갱신하며, 갱신에 필요한 정보는 하위 시스템으로 전달하지 않습니다.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`MCP OAuth 클라이언트 메타데이터 URL`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth ID`},help:{"v1-1ie6ys7-59":`이 서버의 OAuth 자격 증명 소유 방식입니다. 운영자가 관리하는 자격 증명을 사용하려면 이 필드를 생략하거나 "shared"를 사용하세요. 인증된 각 발신자가 자신의 계정을 연결하도록 하려면 "per-requester"를 사용하세요.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`MCP OAuth 리디렉션 URL`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`MCP OAuth 범위`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`MCP 요청 제한 시간(ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`MCP TLS 검증`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`MCP TLS 검증`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`MCP 병렬 도구 호출`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`MCP 병렬 도구 호출`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`MCP 도구 선택`},help:{"v1-10poyzb-4v":`서버별 MCP 도구 선택 설정입니다. 선택한 이름의 MCP 도구만 노출하려면 include를, 숨기려면 exclude를 사용하세요. 항목에는 정확한 이름과 간단한 '*' 글로브 패턴을 사용할 수 있습니다.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`제외된 MCP 도구`},help:{"v1-ijrc5y-1u":`이 서버에서 숨길 MCP 도구의 정확한 이름 또는 간단한 '*' 글로브 패턴입니다.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`포함할 MCP 도구`},help:{"v1-89fdfq-3o":`이 서버에서 노출할 MCP 도구의 정확한 이름 또는 간단한 '*' 글로브 패턴입니다. 생략하면 제외된 도구를 뺀 모든 서버 도구가 노출 대상이 됩니다.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`MCP 세션 유휴 TTL(ms)`},help:{"v1-j9si74-87":`OpenClaw 세션 MCP 런타임의 유휴 상태 해제 시간을 밀리초 단위로 지정하는 선택적 설정입니다. 설정하지 않거나 0으로 설정하면 세션 정리 또는 Gateway 종료 시까지 런타임이 유지됩니다. 양수 값은 내림 처리됩니다. 활성 임대나 대기 중인 획득 요청이 있으면 런타임이 해제되지 않습니다. 실행에 속한 런타임은 해당 일회성 실행이 끝나면 종료됩니다.`}},memory:{label:{"v1-oopaku-6":`메모리`},help:{"v1-1wlx40m-13":`내장 메모리 구성(전역)입니다.`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`메모리 출처 표시 모드`},help:{"v1-1q6dxr5-4u":`응답의 출처 표시 여부를 제어합니다. "auto"는 유용할 때 출처를 표시하고, "on"은 항상 표시하며, "off"는 숨깁니다. 유용한 정보와 불필요한 정보 사이의 균형을 유지하려면 기본값인 "auto"를 사용하세요.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`메모리 검색`},help:{"v1-1ukbud1-25":`MEMORY.md 및 memory/*.md에 대한 벡터 검색입니다(에이전트별 재정의 지원).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`메모리 검색 임베딩 캐시`},help:{"v1-d8h2e4-5b":`계산된 청크 임베딩을 SQLite에 캐시하여 재색인과 증분 업데이트 속도를 높입니다(기본값: true). 캐시의 정확성을 조사하거나 디스크 사용량을 최소화하려는 경우가 아니라면 활성 상태로 유지하세요.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`메모리 검색 문서 입력 유형`},help:{"v1-1ui33sv-5f":"문서 및 인덱싱용 메모리 임베딩에 사용할 선택적 공급자별 `input_type` 값입니다. 구절 또는 문서 레이블이 필요한 OpenAI 호환 비대칭 임베딩 엔드포인트에 사용하세요."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`메모리 검색 활성화`},help:{"v1-14f11b9-4t":`이 에이전트 프로필의 메모리 검색 인덱싱 및 검색 동작을 제어하는 기본 토글입니다. 의미 기반 회상을 사용하려면 활성화하고, 상태를 전혀 유지하지 않는 응답을 원하면 비활성화하세요.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`메모리 검색 세션 인덱스(실험적)`},help:{"v1-qvhv8z-3i":`세션 대화 기록을 메모리 검색에 인덱싱합니다. 루트와 에이전트별 회상 설정의 상속 방식이 다를 때는 이 고급 재정의 설정을 유지하세요.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`추가 메모리 경로`},help:{"v1-ojqokq-7i":`기본 메모리 파일 외에 추가 디렉터리나 .md 파일을 메모리 인덱스에 추가합니다. 항목은 경로 문자열 또는 루트 기준 상대 glob 패턴을 포함하는 객체일 수 있습니다. 멀티모달 메모리가 활성화된 경우 이 경로 아래에서 일치하는 이미지/오디오 파일도 인덱싱 대상이 됩니다.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`추가 메모리 경로`},help:{"v1-b9mbq8-3m":`추가 메모리 디렉터리 또는 파일을 설정합니다. 상대 경로는 에이전트 작업 공간을 기준으로 해석되며, 파일을 직접 지정한 항목은 해당 파일만 인덱싱됩니다.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`추가 메모리 경로 패턴`},help:{"v1-j8br1v-4e":`디렉터리 항목의 대상을 이 루트 기준 상대 glob과 일치하는 지원 파일로 제한합니다. 예: "runbooks/**/*.md". 생략하면 지원되는 모든 파일을 재귀적으로 검색합니다.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`메모리 검색 대체 제공업체`},help:{"v1-1r6368w-6p":`기본 임베딩이 실패할 때 사용할 예비 제공업체입니다. "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" 또는 "none" 중에서 선택합니다. 프로덕션 환경의 안정성을 위해 실제 대체 제공업체를 설정하세요. 실패를 명시적으로 처리하려는 경우에만 "none"을 사용하세요.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`메모리 검색 입력 유형`},help:{"v1-26vbwe-5u":"쿼리와 문서 임베딩 요청 모두에 동일한 레이블을 적용해야 하는 경우에만 이 선택적 제공업체별 `input_type` 값을 사용하세요. 비대칭 제공업체의 경우 queryInputType과 documentInputType을 사용하는 것이 좋습니다."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`로컬 임베딩 모델 경로`},help:{"v1-13ymbnt-5q":"로컬 메모리 검색에 사용할 로컬 임베딩 모델의 소스를 지정합니다. GGUF 파일 경로나 `hf:` URI 등을 사용할 수 있습니다. provider가 `local`인 경우에만 사용하고, 대규모 인덱스를 다시 빌드하기 전에 모델 호환성을 확인하세요."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`메모리 검색 모델`},help:{"v1-11pohrl-59":`기본 모델이 아닌 모델이 필요할 때 선택한 메모리 제공업체에서 사용할 임베딩 모델 재정의 설정입니다. 제공업체 기본값을 넘어 검색 재현율이나 비용을 명시적으로 조정해야 하는 경우에만 설정하세요.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`메모리 검색 멀티모달`},help:{"v1-1jn02s-9e":'설정된 추가 경로의 이미지 및 오디오 파일을 인덱싱하기 위한 선택적 멀티모달 메모리 설정입니다. 임베딩 모델이 교차 모달 임베딩을 명시적으로 지원하지 않는 한 비활성화 상태로 유지하세요. 활성화한 동안에는 `memory.search.fallback`을 "none"으로 설정하세요. 조건에 맞는 파일은 인덱싱 중에 설정된 원격 임베딩 제공업체로 업로드됩니다.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`멀티모달 메모리 검색 활성화`},help:{"v1-1dk5d7o-7e":`extraPaths에서 이미지/오디오 메모리 인덱싱을 활성화합니다. 현재 이 기능에는 Gemini embedding-2가 필요하며, 기본 메모리 루트는 Markdown 전용으로 유지됩니다. 또한 메모리 검색의 대체 제공자를 비활성화하고, 일치하는 바이너리 콘텐츠를 설정된 원격 임베딩 제공자에 업로드합니다.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`멀티모달 메모리 검색 최대 파일 크기(바이트)`},help:{"v1-1mmdrvk-5d":`멀티모달 파일당 허용되는 최대 바이트 수를 설정합니다. 이 크기를 초과하는 파일은 메모리 인덱싱 중 건너뜁니다. 업로드 비용과 인덱싱 지연 시간을 제한하는 데 사용하거나, 짧은 고품질 오디오 클립을 처리하려면 값을 높이세요.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`멀티모달 메모리 검색 모달리티`},help:{"v1-alp4vh-4l":`extraPaths에서 인덱싱할 멀티모달 파일 유형을 "image", "audio", "all" 중에서 선택합니다. 대규모 바이너리 데이터 모음이 의도치 않게 인덱싱되지 않도록 선택 범위를 좁게 유지하세요.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`메모리 검색 출력 차원 수`},help:{"v1-1f7zu53-93":`메모리 임베딩의 제공자별 출력 벡터 크기를 재정의합니다. Gemini 모델은 128~3072차원을 지원하며 768, 1536 또는 3072를 권장합니다. Titan V2, Cohere V4, Nova 등의 Bedrock 모델군은 각각 허용되는 크기가 다릅니다. 저장된 벡터의 차원 수는 일관되게 유지되어야 하므로 이 값을 변경하면 전체 재인덱싱이 필요합니다.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`메모리 검색 제공자`},help:{"v1-5evseb-71":`메모리 벡터를 생성하고 쿼리하는 데 사용할 임베딩 백엔드를 선택합니다. 기본값은 "openai"입니다. 다른 백엔드를 사용하려면 "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" 또는 "local"로 설정하세요.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`메모리 검색 최대 결과 수`},help:{"v1-13ekath-4x":`후속 재순위 지정 및 프롬프트 삽입 전에 검색에서 반환할 메모리 결과의 최대 개수입니다. 더 폭넓게 정보를 검색하려면 값을 높이고, 프롬프트를 간결하게 유지하고 응답 속도를 높이려면 값을 낮추세요.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`메모리 검색 최소 점수`},help:{"v1-1ww231l-4v":`최종 검색 출력에 메모리 결과를 포함하기 위한 최소 관련성 점수 기준입니다. 관련성이 낮거나 불필요한 결과를 줄이려면 값을 높이고, 검색 조건을 완화하려면 값을 낮추세요.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`메모리 검색 쿼리 입력 유형`},help:{"v1-831yrv-4q":"쿼리 시 메모리 임베딩에 사용할 선택적 공급자별 `input_type` 값입니다. 쿼리 레이블이 필요한 OpenAI 호환 비대칭 임베딩 엔드포인트에 사용하세요."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`대화 간 기억 유지`},help:{"v1-k1itm8-7y":`보호된 대화 기록 검색을 통해 이 에이전트의 다른 비공개 대화에서 관련 맥락을 활용합니다. 전역 session.dmScope가 설정되지 않았거나 "main"이고 DM 범위를 재정의하는 바인딩이 없을 때만 기본적으로 켜집니다. DM 격리가 설정되어 있으면 기본적으로 꺼집니다. 명시적으로 지정한 true 또는 false 값이 항상 우선합니다.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`원격 임베딩 API 키`},help:{"v1-nfuuu-62":`메모리 인덱싱과 쿼리 시점의 임베딩에 사용되는 원격 임베딩 호출에 전용 API 키를 제공합니다. 메모리 임베딩에 전역 기본값이나 환경 변수와 다른 인증 정보를 사용해야 할 때 설정하세요.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`원격 임베딩 기본 URL`},help:{"v1-1ugvqgt-5p":`임베딩 API 엔드포인트를 OpenAI 호환 프록시나 사용자 지정 Gemini 기본 URL 등으로 재정의합니다. 자체 게이트웨이나 공급업체 엔드포인트를 통해 라우팅할 때만 사용하고, 그 외에는 제공업체 기본값을 유지하세요.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`원격 배치 임베딩 활성화`},help:{"v1-1fehqi-5x":`지원되는 경우(OpenAI/Gemini) 임베딩 작업에 제공업체의 배치 API를 활성화하여 대규모 인덱싱 실행 시 처리량을 높입니다. 제공업체의 배치 실패를 디버깅하거나 매우 작은 워크로드를 실행하는 경우가 아니라면 활성화된 상태로 유지하세요.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`원격 임베딩 헤더`},help:{"v1-1uic0kd-5i":`원격 임베딩 요청에 사용자 지정 HTTP 헤더를 추가하고 제공업체 기본값과 병합합니다. 프록시 인증 및 테넌트 라우팅 헤더에 사용하고, 민감한 메타데이터가 유출되지 않도록 값은 최소한으로 유지하세요.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`메모리 검색 소스`},help:{"v1-btxtzg-57":`인덱싱할 소스를 선택합니다. "memory"는 MEMORY.md와 메모리 파일을 읽고, "sessions"는 대화 기록을 포함합니다. 이전 대화 기록에서 정보를 검색해야 하는 경우가 아니라면 ["memory"]를 유지하세요.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`메모리 검색 벡터 인덱스`},help:{"v1-fbybkj-37":`sqlite-vec 시맨틱 인덱스를 제어합니다. 루트와 에이전트별 벡터 정책이 다른 경우 이 고급 재정의 설정을 유지하세요.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`메모리 검색 벡터 확장 경로`},help:{"v1-1hysv5q-58":"자동으로 검색된 sqlite-vec 확장 라이브러리 경로(`.dylib`, `.so`, `.dll`)를 재정의합니다. 런타임에서 sqlite-vec를 자동으로 찾지 못하거나 정상 작동이 확인된 빌드를 고정하려는 경우 사용하세요."}},messages:{label:{"v1-1wwzqad-8":`메시지`},help:{"v1-i5k0iw-5k":`메시지 인프라 및 에이전트 간 공통 기본값입니다. 루트의 동위 설정 항목은 인프라와 에이전트 간 공통 기본값을, agents.defaults는 에이전트 루프 동작을 관리합니다. 에이전트 항목은 지원되는 경우 둘 중 어느 쪽이든 재정의할 수 있습니다.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`수신 확인 반응 이모지`},help:{"v1-1iip0zs-1x":`수신 메시지 확인에 사용하는 이모지 반응입니다(비워 두면 비활성화).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`수신 확인 반응 범위`},help:{"v1-1jvdg5n-7s":`수신 확인 반응을 보낼 조건입니다("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions"는 그룹의 멘션 필수 여부와 관계없이 에이전트를 멘션한 그룹 메시지에 수신 확인 반응을 보냅니다. "group-all"은 모든 그룹 메시지에 수신 확인 반응을 보냅니다. "off"/"none"은 수신 확인 반응을 완전히 비활성화합니다.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`그룹 채팅 규칙`},help:{"v1-chqsvh-4l":`멘션 트리거와 기록 범위 크기 조정을 포함한 그룹 메시지 처리 설정입니다. 그룹 채널에서 모든 메시지가 트리거되지 않도록 멘션 패턴을 제한적으로 설정하세요.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`그룹 기록 한도`},help:{"v1-1mkbpw-9k":`그룹 세션에서 매 턴마다 컨텍스트로 불러올 이전 그룹 메시지의 최대 개수입니다. 대화의 연속성을 높이려면 값을 높이고, 응답 속도를 높이고 비용을 줄이려면 값을 낮추세요. 자동 프롬프트 기록은 최대 200개 메시지로 제한됩니다. JSON 정수의 최댓값을 지정하면 무제한 범위가 아닌 채널 기본 범위(공유 그룹 기록의 경우 50개)가 적용됩니다.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`그룹 멘션 패턴`},help:{"v1-i7h7qc-6f":`그룹 채팅에서 명시적 멘션이나 트리거 문구를 감지하는 데 사용하는 안전한 대소문자 구분 없는 정규식 패턴입니다. 메시지가 많은 채널에서 오탐을 줄이려면 정밀한 패턴을 사용하세요. 유효하지 않거나 안전하지 않은 중첩 반복 패턴은 무시됩니다.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`멘션 없는 그룹 수신 메시지`},help:{"v1-17wef8h-5f":`상시 활성화된 그룹에서 멘션 없는 대화를 전달하는 방식을 제어합니다. "user_request"는 이를 사용자 요청으로 처리하고, "room_event"는 조용한 컨텍스트로 전달하며 표시되는 출력을 보내려면 메시지 도구가 필요합니다.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`그룹에 표시되는 답변`},help:{"v1-qa4z1s-aa":`그룹/채널 대화에서 모델이 작성한 원본 답변의 처리 방식을 재정의합니다. 표시되는 답변에 대한 전역 정책이 설정되지 않은 경우 기본값은 "automatic"입니다. "message_tool"에서는 일반 어시스턴트 출력과 일반 도구 미디어를 보내려면 message(action=send)가 필요합니다. 명시적으로 호스트가 소유한 런타임 출력은 백그라운드 대화방 이벤트를 제외하고 계속 전달할 수 있습니다. "automatic"은 이전과 같이 일반 답변을 게시합니다.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`수신 디바운스`},help:{"v1-ebyu5x-4a":`대기열/턴 처리가 시작되기 전에 적용되는 직접 수신 디바운스 설정입니다. 동일한 발신자가 짧은 시간에 연속으로 보내는 메시지를 처리하도록 제공업체별로 구성하세요.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`채널별 수신 디바운스(ms)`},help:{"v1-wbz54j-4g":`제공자 ID를 키로 하는 채널별 수신 디바운스 재정의 값(밀리초)입니다. 일부 제공자가 다른 제공자보다 메시지 조각을 더 빈번하게 전송하는 경우 사용하세요.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`수신 메시지 디바운스(ms)`},help:{"v1-1616yo2-7w":`동일한 발신자가 빠르게 연속으로 보낸 수신 메시지를 일괄 처리하기 위해 추가 메시지를 기다리는 시간(ms)입니다. 전역 또는 채널별 재정의가 설정되지 않은 경우 Telegram의 기본값은 300ms이며, 다른 채널의 기본값은 0입니다. 0으로 설정하면 일반적인 연속 메시지 일괄 처리는 비활성화되지만, Telegram은 여전히 길이 제한에 근접한 긴 메시지 조각을 다시 합칩니다.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`수신 대기열`},help:{"v1-hm2o31-48":`세션 실행 중 도착하는 수신 메시지의 대기열 처리 전략입니다. 실행 방향 조정, 지연된 후속 처리, 일괄 처리 또는 중단 동작을 조정할 때 사용하세요.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`채널별 대기열 모드`},help:{"v1-4rf8z8-54":`제공자 ID(예: telegram, discord, slack)를 키로 하는 채널별 대기열 모드 재정의 값입니다. 특정 채널의 트래픽 패턴에 전역 기본값과 다른 동작이 필요한 경우 사용하세요.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`대기열 용량`},help:{"v1-16ql8c7-4j":`삭제 정책이 적용되기 전에 대기열에 보관할 수 있는 수신 항목의 최대 개수입니다. 기본값은 20입니다. 메시지가 많은 채널에서는 메모리 사용량을 예측할 수 있도록 용량을 적절히 제한하세요.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`채널별 대기열 폴백 디바운스(ms)`},help:{"v1-4tpyt7-4e":`제공자 ID를 키로 하는 대기열 동작의 채널별 디바운스 재정의 값입니다. 메시지 유입 속도가 서로 다른 채팅 환경에서 메시지 급증 처리를 개별적으로 조정할 때 사용하세요.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`대기열 삭제 전략`},help:{"v1-ydb2rw-6m":`대기열 한도를 초과했을 때의 삭제 전략입니다. "summarize"는 가장 오래된 항목을 삭제하되 간략한 요약을 보존하고, "old"는 요약 없이 가장 오래된 항목을 삭제하며, "new"는 가장 최근 항목을 거부합니다. 맥락이 중요한 장기 대화에는 "summarize"를 사용하세요.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`대기열 모드`},help:{"v1-19k7gy1-67":`진행 중인 실행에 적용할 대기열 모드입니다. "steer"는 진행 중인 실행에 프롬프트를 삽입하고, "followup"은 나중에 실행하며, "collect"는 호환되는 메시지를 나중에 일괄 처리하고, "interrupt"는 진행 중인 실행을 중단한 후 가장 최근 프롬프트를 시작합니다.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`발신 응답 접두사`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`기본 사용량 바닥글 모드`},help:{"v1-l3shsx-dv":`/usage로 모드를 선택하지 않은 세션에 초기 적용되는 답변별 기본 사용량 바닥글 모드("off"|"tokens"|"full")입니다. "tokens"의 기존 별칭인 "on"도 허용됩니다. 모드 값만 지정하거나 "default"를 대체 값으로 사용하는 채널별 맵을 지정할 수 있습니다. 우선순위: 세션 값 -> 채널 항목 -> default -> off. /usage로 명시적으로 선택한 값(off 포함)은 저장되며 기본값보다 우선합니다. /usage reset(별칭: inherit, clear, default)을 사용하면 세션의 재정의 값을 지우고 이 설정의 기본값을 다시 상속할 수 있습니다.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`상태 반응`},help:{"v1-193764l-3s":`에이전트의 진행 상황(대기 중 → 생각 중 → 도구 → 완료/오류)에 따라 트리거 메시지의 이모지를 업데이트하는 수명 주기 상태 반응입니다.`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`상태 반응 활성화`},help:{"v1-1qnmmnc-7x":`지원되는 채널에서 수명 주기 상태 반응을 활성화합니다. Discord는 확인 반응이 활성화되어 있으면 이 값이 설정되지 않아도 활성화된 것으로 처리합니다. Slack, Signal, Telegram, WhatsApp에서는 수명 주기 반응을 사용하려면 이 값이 true여야 합니다. Slack은 기본적으로 진행 상황에 네이티브 어시스턴트 스레드 상태를 사용합니다.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`사용량 푸터 템플릿`},help:{"v1-1xibc23-47":`인라인 객체 또는 JSON 파일 경로로 지정하는 사용자 지정 /usage full 푸터 템플릿입니다. 템플릿이 유효하지 않거나 사용할 수 없으면 기본 제공 사용량 줄로 대체됩니다.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`표시되는 답변`},help:{"v1-7yfwc2-8t":`개인, 그룹, 채널 대화에서 모델이 작성한 원본 답변을 제어합니다. "message_tool"은 일반 어시스턴트 출력 및 일반 도구 미디어에 message(action=send)를 요구합니다. 명시적으로 호스트가 소유한 런타임 출력은 대화방의 백그라운드 이벤트를 제외하고 계속 전달할 수 있습니다. "automatic"은 이전과 같이 일반 답변을 게시합니다.`}},meta:{label:{"v1-1xpfxac-m":`호환성 메타데이터`},help:{"v1-1owqhgn-2w":`이전 버전 바이너리가 안전하지 않은 설정 다운그레이드를 거부할 수 있도록 유지되는, 이전 버전에서도 읽을 수 있는 호환성 메타데이터입니다.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`설정을 마지막으로 수정한 버전`},help:{"v1-qykpv1-1i":`이 설정을 가장 최근에 기록한 OpenClaw 버전입니다.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`설정 마이그레이션 마커`},help:{"v1-burt8q-1q":`완료된 설정 마이그레이션에 대한 제한된 범위의 호환성 마커입니다.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`모델 정책 허용 목록 마이그레이션`},help:{"v1-5psop1-1z":`기존 모델 맵 제한 사항이 유지되거나 평가되었음을 기록합니다.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`유틸리티 모델 분리 마이그레이션`},help:{"v1-vzdfqx-2t":`유틸리티 모델 선택을 분리하기 전에 기존의 암묵적 기본 모델이 보존되었음을 기록합니다.`}},models:{label:{"v1-hzmwb-6":`모델`},help:{"v1-1h1niol-5q":`공급자 정의, 병합/교체 동작, 선택적 Bedrock 검색 통합을 위한 모델 카탈로그 루트입니다. 프로덕션 장애 조치 경로에 의존하기 전에 공급자 정의를 명시적으로 지정하고 검증하세요.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`모델 카탈로그 새로 고침`},help:{"v1-1hess4t-40":`기본 제공 모델 카탈로그의 백그라운드 업데이트를 제어합니다. 원격 항목은 모델 메타데이터를 업데이트할 수 있지만 공급자 엔드포인트나 헤더는 변경할 수 없습니다.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`모델 카탈로그 새로 고침 활성화`},help:{"v1-1fogpjj-3j":`호스팅된 모델 카탈로그 업데이트를 백그라운드에서 가져옵니다(기본값: true). 모든 원격 모델 카탈로그 트래픽을 비활성화하려면 false로 설정하세요.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`모델 카탈로그 새로 고침 URL`},help:{"v1-e02ai2-44":`호스팅된 모델 카탈로그 URL을 자체 호스팅 HTTPS 미러 URL로 재정의합니다(테스트용으로 localhost HTTP도 허용됩니다). 변경 사항은 Gateway를 다시 시작한 후 적용됩니다.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`모델 카탈로그 모드`},help:{"v1-1ofrnsp-es":`공급자 카탈로그의 동작을 제어합니다. "merge"는 기본 제공 공급자를 유지하면서 사용자 지정 공급자를 덧씌우고, "replace"는 설정한 공급자만 사용합니다. "merge"에서 공급자 ID가 일치하면 에이전트의 models.json에 있는 비어 있지 않은 baseUrl 값을 유지합니다. 반면 apiKey 값은 현재 구성/인증 프로필 컨텍스트에서 해당 공급자가 SecretRef로 관리되지 않는 경우에만 유지됩니다. SecretRef로 관리되는 공급자는 현재 소스 마커에서 apiKey를 갱신하며, 일치하는 모델의 contextWindow/maxTokens에는 명시적 항목과 암시적 항목 중 더 큰 값을 사용합니다.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`모델 공급자`},help:{"v1-1y5jg0v-8p":`연결 및 인증 설정과 구체적인 모델 정의를 포함하며, 제공자 ID를 키로 사용하는 제공자 맵입니다. 기본 제공 제공자는 제공자 수준의 오버레이로 조정할 수 있으며, 사용자 지정 제공자는 baseUrl과 models를 포함해야 합니다. 에이전트와 도구의 참조를 여러 환경에서 그대로 사용할 수 있도록 일관된 제공자 키를 사용하세요.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`모델 제공자 런타임`},help:{"v1-1luy4fb-5o":`이 제공자에 대한 선택적 저수준 에이전트 런타임 정책입니다. 에이전트 전체에 런타임을 고정하는 대신 제공자/모델 런타임 정책을 사용하세요. 생략하거나 기본값을 사용하면 OpenClaw가 선택된 제공자에 맞는 런타임을 선택합니다.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`모델 제공자 런타임 ID`},help:{"v1-1gusd9s-69":`제공자 에이전트 런타임 ID: "openclaw", "auto", "codex"와 같은 등록된 플러그인 하네스 ID 또는 "claude-cli"와 같은 지원되는 CLI 백엔드 별칭입니다. 생략하면 공식 엔드포인트를 사용하는 OpenAI는 기본적으로 Codex 하네스를 사용합니다.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`모델 제공자 API 어댑터`},help:{"v1-16c28rb-57":`모델 호출의 요청/응답 호환성 처리를 제어하는 제공자 API 어댑터 선택 항목입니다. 기능 불일치를 방지하려면 업스트림 제공자의 프로토콜에 맞는 어댑터를 사용하세요.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`모델 제공자 API 키`},help:{"v1-1p84k96-54":`제공자가 직접 키 인증을 요구할 때 API 키 기반 인증에 사용하는 제공자 자격 증명입니다. 비밀 값/환경 변수 치환을 사용하고 커밋되는 설정 파일에 실제 키를 저장하지 마세요.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`모델 제공자 인증 모드`},help:{"v1-1l1lwxr-5p":`공급자의 인증 방식을 선택합니다. API 키 인증에는 "api-key", Bearer 토큰 인증에는 "token", OAuth 자격 증명에는 "oauth", AWS 자격 증명 확인에는 "aws-sdk"를 사용합니다. 공급자의 요구 사항에 맞게 설정하세요.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`모델 공급자 Authorization 헤더`},help:{"v1-1gn3lt3-59":`true이면 다른 인증 방식을 사용할 수 있어도 HTTP Authorization 헤더를 통해 자격 증명을 전송합니다. 공급자나 프록시가 Authorization 전달을 명시적으로 요구하는 경우에만 사용하세요.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`모델 공급자 기본 URL`},help:{"v1-1ku88v8-53":`해당 공급자 항목의 모델 요청을 처리하는 공급자 엔드포인트의 기본 URL입니다. HTTPS 엔드포인트를 사용하고, 필요한 경우 구성 템플릿을 통해 환경별 URL을 관리하세요.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`모델 공급자 헤더`},help:{"v1-chg59u-4x":`테넌트 라우팅, 프록시 인증 또는 사용자 지정 게이트웨이 요구 사항을 위해 공급자 요청에 병합되는 정적 HTTP 헤더입니다. 꼭 필요한 경우에만 사용하고 민감한 헤더 값은 시크릿에 보관하세요.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`모델 공급자 num_ctx 주입(OpenAI 호환)`},help:{"v1-53rmcr-6n":"OpenAI 호환 어댑터(`openai-completions`)로 구성된 Ollama 공급자에 OpenClaw가 `options.num_ctx`를 주입할지 제어합니다. 기본값은 true입니다. 프록시나 업스트림이 알 수 없는 `options` 페이로드 필드를 거부하는 경우에만 false로 설정하세요."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`모델 공급자 로컬 서비스`},help:{"v1-19zkcow-4y":`이 제공자에서 필요할 때 실행하는 선택적 로컬 모델 서버 프로세스입니다. OpenClaw는 healthUrl을 확인하고, 필요하면 명령을 실행한 뒤, 준비가 완료될 때까지 기다렸다가 모델 요청을 보냅니다.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`모델 제공자 로컬 서비스 인수`},help:{"v1-t12wib-27":`셸 확장 없이 로컬 모델 서버 명령에 전달되는 인수 목록입니다.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`모델 제공자 로컬 서비스 명령`},help:{"v1-1x6hz64-4j":`로컬 모델 서버 프로세스의 실행 파일 절대 경로입니다. 제공자가 항상 일관되게 시작되고 셸의 PATH 검색에 의존하지 않도록 이 경로를 명시적으로 지정하세요.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`모델 제공자 로컬 서비스 작업 디렉터리`},help:{"v1-fi3xlx-1h":`로컬 모델 서버 프로세스의 작업 디렉터리입니다.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`모델 제공자 로컬 서비스 환경`},help:{"v1-1lwb9k1-3k":`로컬 모델 서버 프로세스에 사용할 추가 환경 변수입니다. 비밀 정보로 보이는 값은 구성 스냅샷에서 가려집니다.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`모델 제공자 로컬 서비스 상태 확인 URL`},help:{"v1-jv7aw-35":`모델 요청 전에 준비 상태를 확인하는 URL입니다. 생략하면 OpenClaw는 제공자의 baseUrl에 /models를 추가하여 사용합니다.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`모델 제공자 로컬 서비스 유휴 시 중지`},help:{"v1-1efg054-3z":`마지막 요청이 완료된 후 OpenClaw가 시작한 로컬 모델 서버를 계속 실행할 시간(밀리초)입니다. OpenClaw가 종료될 때까지 계속 실행하려면 0으로 설정하세요.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`모델 제공자 로컬 서비스 준비 대기 시간 제한`},help:{"v1-4gp0f0-2r":`프로세스를 시작한 후 로컬 모델 서버의 준비 상태 확인을 기다리는 최대 시간(밀리초)입니다.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`모델 제공자 최대 토큰 수`},help:{"v1-fnj50y-38":`모델 항목에 maxTokens가 설정되지 않은 경우 이 제공자의 모델에 적용되는 기본 최대 출력 토큰 한도입니다.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`모델 제공자의 모델 목록`},help:{"v1-1vbm0gt-63":`식별자, 메타데이터, 제공자별 매개변수, 선택적 호환성 및 비용 힌트를 포함하는 제공자의 선언된 모델 목록입니다. 선택 및 대체 모델 확인이 올바르게 이루어지도록 ID를 제공자 카탈로그의 값과 정확히 일치시키세요.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`모델 런타임`},help:{"v1-1k70g2n-3g":`이 특정 모델에 대한 선택적 저수준 에이전트 런타임 정책입니다. 모델 런타임 정책은 제공자 런타임 정책보다 우선합니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`모델 런타임 ID`},help:{"v1-1llzv33-42":`모델 에이전트 런타임 ID: "openclaw", "auto", "codex"와 같은 등록된 플러그인 하네스 ID 또는 "claude-cli"와 같은 지원되는 CLI 백엔드 별칭입니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`모델 미디어 입력`},help:{"v1-wxtj8e-2x":`도구가 보수적인 이미지 압축 기본값을 선택하는 데 사용하는 선택적 모델 미디어 기능 메타데이터입니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`모델 이미지 입력`},help:{"v1-1nviirq-3c":`최대 변 길이, 최대 픽셀 수, 권장 압축 변 길이 등 이 모델의 선택적 이미지 입력 제한입니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`모델 이미지 최대 바이트 수`},help:{"v1-c2469j-23":`제공업체가 이 모델에 대해 허용하는 인코딩된 이미지 페이로드의 최대 크기입니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`모델 이미지 최대 픽셀 수`},help:{"v1-9d6yqp-1u":`제공업체가 이 모델에 대해 허용하는 최대 이미지 픽셀 수입니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`모델 이미지 최대 변 길이`},help:{"v1-1gbci08-1y":`제공업체가 이 모델에 대해 허용하는 최대 이미지 너비 또는 높이입니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`모델 이미지 권장 변 길이`},help:{"v1-1u1mpcg-2x":`균형 잡힌 압축을 위해 이미지 크기 조정 시 권장되는 변 길이입니다. 설정하지 않으면 OpenClaw의 보수적인 기본값을 사용합니다.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`모델 이미지 토큰 모드`},help:{"v1-1oy6z7v-1z":`제공업체의 이미지 토큰 계산 방식: "tile", "detail" 또는 "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`모델 제공업체 런타임 매개변수`},help:{"v1-464sgu-4t":`제공업체 플러그인이 해석하는 제공업체별 런타임 매개변수입니다. 제공업체 문서에 명시된 키를 사용하고, 임의로 가정한 공통 규칙보다 제공업체 문서의 명시적인 내용을 우선하세요.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`모델 제공업체 리전`},help:{"v1-yq7rxk-5h":`리전별 엔드포인트를 제공하는 제공업체가 해석하는 선택적 배포/API 리전입니다. 지원되는 값은 제공업체 문서를 참조하세요. baseUrl 재정의도 함께 설정하면 일반적으로 baseUrl이 우선 적용됩니다.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`모델 제공업체 요청 재정의`},help:{"v1-1lkxryk-87":`모델 제공업체 요청에 적용할 선택적 재정의 설정입니다. 추가 헤더, 인증 재정의, 프록시 라우팅, TLS 클라이언트 설정, 신뢰할 수 있는 자체 호스팅 엔드포인트용 선택적 allowPrivateNetwork를 포함합니다. 업스트림 또는 기업 네트워크 경로에서 전송 설정을 사용자 지정해야 하는 경우에만 사용하세요.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`모델 제공업체 요청의 사설 네트워크 허용`},help:{"v1-1nbtcjk-fo":`true이면 공급자 HTTP 가져오기 보호 기능(fetchWithSsrFGuard)을 통해 사설, CGNAT 또는 유사한 대역으로 모델 공급자 HTTP 요청을 보내는 것을 허용합니다. 사용자 지정/로컬 공급자의 기본 URL은 이미 정확히 구성된 오리진을 신뢰하지만, 메타데이터, 링크 로컬 및 로컬용 NAT64(64:ff9b:1::/48) 오리진은 제외됩니다. 이 신뢰를 해제하려면 false로 설정하세요. OpenAI Responses WebSocket은 헤더/TLS에 request를 재사용하지만 해당 가져오기 SSRF 경로는 사용하지 않습니다. 구성된 baseUrl 오리진 외부의 사설 오리진에 연결해야 하는, 운영자가 제어하는 자체 호스팅 엔드포인트에만 true를 사용하세요.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`모델 공급자 요청 인증 재정의`},help:{"v1-ucdgnf-1w":`이 공급자의 요청 인증 동작을 재정의합니다.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`모델 공급자 요청 인증 헤더 이름`},help:{"v1-1881nqr-1i":`인증 모드가 header일 때 사용하는 사용자 지정 인증 헤더 이름입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`모델 공급자 요청 인증 모드`},help:{"v1-1lhv8hs-24":`인증 재정의 모드: "provider-default", "authorization-bearer" 또는 "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`모델 공급자 요청 인증 헤더 접두사`},help:{"v1-1rbm9lz-21":`인증 모드가 header일 때 request.auth.value 앞에 추가하는 선택적 접두사입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`모델 공급자 요청 Bearer 토큰`},help:{"v1-6rcasw-1l":`인증 모드가 authorization-bearer일 때 사용하는 Bearer 토큰입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`모델 제공업체 요청 인증 헤더 값`},help:{"v1-1v69ej-1j":`인증 모드가 header일 때 사용하는 사용자 지정 인증 헤더 값입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`모델 제공업체 요청 헤더`},help:{"v1-zj3orj-2i":`기본 출처 표시 및 인증 처리가 완료된 후 제공업체 요청에 병합되는 추가 헤더입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`모델 제공업체 요청 프록시`},help:{"v1-md5uj8-4j":`모델 제공업체 요청에 적용할 선택적 프록시 재정의 설정입니다. 환경 프록시 설정을 따르려면 "env-proxy"를, 특정 프록시 URL을 통해 라우팅하려면 "explicit-proxy"를 사용하세요.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`모델 제공업체 요청 프록시 모드`},help:{"v1-1dx0ozg-29":`모델 제공업체 요청의 프록시 재정의 모드: "env-proxy" 또는 "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`모델 제공업체 요청 프록시 TLS`},help:{"v1-rdx62w-1v":`설정된 프록시에 연결할 때 사용하는 선택적 TLS 설정입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`모델 제공업체 요청 프록시 TLS CA`},help:{"v1-11pg2fd-1s":`프록시 TLS 인증서 체인을 검증하는 데 사용하는 사용자 지정 CA 번들입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`모델 제공업체 요청 프록시 TLS 인증서`},help:{"v1-x8nk2q-22":`상호 TLS가 필요할 때 프록시에 제시하는 클라이언트 TLS 인증서입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`모델 제공업체 요청 프록시 TLS 검증 건너뛰기`},help:{"v1-12vjdm9-2j":`프록시 TLS 인증서 검증을 건너뜁니다. 통제된 개발 환경에서만 사용하세요.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`모델 제공업체 요청 프록시 TLS 키`},help:{"v1-1skyr56-1w":`프록시 상호 TLS를 위해 request.proxy.tls.cert와 쌍을 이루는 개인 키입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`모델 제공업체 요청 프록시 TLS 암호문`},help:{"v1-wjvoxd-1m":`request.proxy.tls.key를 복호화하는 데 사용하는 선택적 암호문입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`모델 제공업체 요청 프록시 TLS 서버 이름`},help:{"v1-b4oabu-22":`프록시에 TLS 연결을 설정할 때 사용하는 선택적 SNI/서버 이름 재정의 값입니다.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`모델 제공업체 요청 프록시 URL`},help:{"v1-kvbgou-48":`request.proxy.mode가 explicit-proxy일 때 사용하는 명시적 프록시 URL입니다. URL에 포함된 자격 증명은 민감한 정보로 취급되어 스냅샷에서 가려집니다.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`모델 제공업체 요청 TLS`},help:{"v1-16u7v7h-2b":`업스트림 모델 엔드포인트에 직접 연결할 때 사용하는 선택적 TLS 설정입니다.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`모델 제공자 요청 TLS CA`},help:{"v1-ny8y3e-1v":`업스트림 TLS 인증서 체인을 검증하는 데 사용하는 사용자 지정 CA 번들입니다.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`모델 제공자 요청 TLS 인증서`},help:{"v1-1lltmhw-2e":`상호 TLS가 필요할 때 업스트림 엔드포인트에 제시하는 클라이언트 TLS 인증서입니다.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`모델 제공자 요청 TLS 검증 건너뛰기`},help:{"v1-1006cuy-2m":`업스트림 TLS 인증서 검증을 건너뜁니다. 통제된 개발 환경에서만 사용하세요.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`모델 제공자 요청 TLS 키`},help:{"v1-w2agir-1t":`업스트림 상호 TLS를 위해 request.tls.cert와 쌍을 이루는 개인 키입니다.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`모델 제공자 요청 TLS 암호문구`},help:{"v1-10ds42f-1g":`request.tls.key를 복호화하는 데 사용하는 선택적 암호문구입니다.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`모델 제공자 요청 TLS 서버 이름`},help:{"v1-18yt7x9-1y":`업스트림 TLS 연결을 설정할 때 사용하는 선택적 SNI/서버 이름 재정의 값입니다.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`모델 제공자 요청 시간 제한`},help:{"v1-t3yn8l-ih":`공급자별 모델 요청 제한 시간(초)을 지정하는 선택적 설정입니다. 공급자 수준의 요청 설정은 명시적으로 정의된 해당 공급자의 모델 항목에 적용되며, 암시적 모델을 생성하지 않습니다. 사용자 지정 공급자의 경우 공급자의 baseUrl 및 models와 함께 설정하세요. 연결, 헤더, 본문, 전체 요청 중단 처리를 포함한 공급자 HTTP 요청에 적용되며, 이 공급자의 LLM 유휴/스트림 감시 제한 시간도 암시적 기본값인 약 120초보다 높여 줍니다. 느린 로컬 또는 자체 호스팅 모델 서버나 추론 토큰을 전송하지 않고 내부적으로 버퍼링하는 클라우드 공급자(Gemini preview, 도구 페이로드가 큰 Claude/Opus)를 사용할 때는 전역 에이전트 제한 시간을 변경하는 대신 이 설정을 사용하세요.`}},nodeHost:{label:{"v1-nb8lk1-9":`노드 호스트`},help:{"v1-8recuz-4z":`이 Gateway 노드에서 다른 노드나 클라이언트에 노출하는 기능을 관리하는 노드 호스트 설정입니다. 노드 네트워크를 통해 로컬 기능을 의도적으로 프록시하려는 경우가 아니라면 기본값을 유지하세요.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`노드 에이전트 실행`},help:{"v1-4uz5ur-2k":`이 헤드리스 노드 호스트에서 승인이 필요한 네이티브 에이전트 턴을 사용하도록 설정합니다. 기본적으로 비활성화되어 있습니다.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`노드 Claude 에이전트 실행`},help:{"v1-g8az5y-2l":`이 헤드리스 노드 호스트가 Claude CLI 에이전트 턴의 사용 가능 여부를 Gateway에 알릴 수 있는지 제어합니다.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`노드 Claude 에이전트 실행 활성화`},help:{"v1-1ke804l-44":`로컬 claude 바이너리를 사용할 수 있을 때 페어링된 노드에서 Claude 세션을 이어갈 수 있음을 알립니다(기본값: false). 실행하려면 여전히 노드 exec 승인이 필요합니다.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`노드 자동 업데이트`},help:{"v1-16xjk4e-5n":`패키지로 배포된 헤드리스 노드 호스트의 별도 런타임에 대한 자동 업데이트를 제어합니다. 매시간 확인하고 모든 노드 작업이 완료될 때까지 기다린 후 다시 시작합니다. 자동 재시작 간격은 최소 12시간입니다.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`노드 자동 업데이트 활성화`},help:{"v1-1sa0yeg-7w":`장시간 실행되는 패키지형 헤드리스 노드의 stable 또는 beta 자동 업데이트를 활성화합니다(기본값: true). 사용하지 않으려면 false로 설정하세요. update.checkOnStart=false 또는 OPENCLAW_NO_AUTO_UPDATE=1로도 비활성화됩니다. 소스 체크아웃, 네이티브 앱, 비공개 워커, dev 및 extended-stable에는 업데이트가 자동 적용되지 않습니다.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`노드 브라우저 프록시`},help:{"v1-2xrew7-4f":`노드 라우팅을 통해 로컬 브라우저 제어를 제공하는 브라우저 프록시 설정을 모아 둡니다. 원격 노드 워크플로에 로컬 브라우저 프로필이 필요한 경우에만 활성화하세요.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`노드 브라우저 프록시 허용 프로필`},help:{"v1-1ew5dkm-8b":`노드 프록시 라우팅을 통해 제공할 브라우저 프로필 이름의 선택적 허용 목록입니다. 프로필 생성/삭제 경로를 포함한 모든 프로필 기능을 기본값대로 제공하려면 비워 두세요. 이 값을 설정하면 OpenClaw는 최소 권한 원칙에 따라 프로필 접근을 제한하고 프록시를 통한 영구 프로필 생성/삭제를 차단합니다.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`노드 브라우저 프록시 활성화`},help:{"v1-pa04pd-5b":`노드 프록시 라우팅을 통해 로컬 브라우저 제어 서버를 제공하여 원격 클라이언트가 이 호스트의 브라우저 기능을 사용할 수 있게 합니다. 원격 자동화에 명시적으로 필요한 경우가 아니라면 비활성화 상태로 유지하세요.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`노드 호스트 MCP`},help:{"v1-1mdhrwl-48":`헤드리스 노드 호스트가 시작하고 페어링된 Gateway에 게시한 MCP 서버를 에이전트 도구로 사용합니다. 이 섹션을 변경한 후에는 노드 호스트를 다시 시작하세요.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`노드 호스트 MCP 서버`},help:{"v1-19m002f-3x":`이 노드에 로컬로 정의된 이름이 있는 MCP 서버 목록입니다. mcp.servers와 동일한 서버 구조를 사용하며, 노드 호스트는 OAuth 서버를 지원하지 않습니다.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`노드 호스트 Skills`},help:{"v1-v8txza-41":`이 섹션을 사용하여 헤드리스 노드 호스트에서 ~/.openclaw/skills에 설치된 스킬을 게시합니다. 스킬 파일을 변경한 후에는 노드 호스트를 다시 시작하세요.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`노드 호스트 Skills 활성화`},help:{"v1-1ggpkqb-36":`연결 후 노드에서 호스팅하는 스킬을 검색하고 게시합니다(기본값: true). 노드 스킬 게시를 비활성화하려면 false로 설정하세요.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`노드 워커 실행`},help:{"v1-1w83rox-2p":`Gateway에서 관리하는 번들을 통해 전체 OpenClaw 워커 세션 호스팅을 사용하도록 설정합니다. 기본적으로 비활성화되어 있습니다.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`노드 워커 동시 실행 한도`},help:{"v1-10nvk8f-3w":`이 노드에서 동시에 호스팅할 수 있는 최대 워커 세션 수입니다(기본값: 사용 가능한 CPU 코어 수). 1부터 1024까지의 정수여야 합니다.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`노드 워커 실행 컨테이너 이미지`},help:{"v1-1oqx50o-5t":`컨테이너로 격리된 워커에 사용할 선택적 Node 24.16+ 또는 26.1+ 이미지입니다(기본값: "node:24.19.0-slim"). 필요에 따라 다이제스트로 고정된 이미지, 비공개 레지스트리 이미지 또는 미리 로드된 이미지를 사용하세요. 없는 이미지는 처음 사용할 때 가져옵니다.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`노드 워커 실행 활성화`},help:{"v1-b3t0xp-2t":`이 페어링된 노드가 해당 Gateway에서 설치한 정확한 번들로 세션을 호스팅하도록 허용합니다(기본값: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`노드 워커 실행 격리`},help:{"v1-19i6swo-58":`워커 세션의 프로세스 경계를 선택합니다. "none"은 노드 호스트에서 직접 실행합니다(기본값). "container"는 정상 작동하는 Docker 호환 엔진이 필요하며, 호스트 실행으로 대체되지 않습니다.`}},plugins:{label:{"v1-10renyj-7":`플러그인`},help:{"v1-1qbev2k-5c":`확장 기능 활성화, 로드 범위 제한, 항목 구성 및 설치 추적을 위한 플러그인 시스템 제어 설정입니다. 프로덕션 환경에서는 플러그인 정책을 명시적으로 설정하고 최소 권한 원칙을 유지하세요.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`플러그인 허용 목록`},help:{"v1-pupwbe-7z":`선택 사항인 플러그인 ID 허용 목록입니다. 설정하면 목록에 있는 플러그인만 로드할 수 있습니다. 단, 기본 제공 채팅 채널이 구성에서 명시적으로 활성화된 경우 해당 채널의 기본 제공 플러그인은 계속 활성화될 수 있습니다. 통제된 환경에서 승인된 확장 기능만 사용하도록 제한하려면 이 설정을 사용하세요.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`플러그인 차단 목록`},help:{"v1-4gyt4z-4i":`허용 목록이나 경로에 포함되어 있어도 차단되는 플러그인 ID의 선택적 목록입니다. 긴급 롤백이나 위험한 플러그인의 강제 차단에 차단 규칙을 사용하세요.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`플러그인 활성화`},help:{"v1-pnygd7-50":`시작 및 구성 다시 로드 시 플러그인/확장 기능 로드를 전역적으로 활성화하거나 비활성화합니다(기본값: true). 배포 환경에 확장 기능이 필요한 경우에만 활성화 상태로 유지하세요.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`플러그인 항목`},help:{"v1-cn74rf-54":`플러그인 ID를 키로 사용하는 플러그인별 설정으로, 활성화 여부와 플러그인별 런타임 구성 데이터를 포함합니다. 전역 로더 정책을 변경하지 않고 개별 플러그인을 조정하려면 이 설정을 사용하세요.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`플러그인 API 키`},help:{"v1-ctytg2-53":`항목 설정에서 직접 키 구성을 지원하는 플러그인이 사용하는 선택적 API 키 필드입니다. 비밀 값/환경 변수 치환을 사용하고 실제 자격 증명이 담긴 구성 파일을 커밋하지 마세요.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`플러그인 구성`},help:{"v1-1he672p-51":`플러그인 자체 스키마와 유효성 검사 규칙에 따라 해석되는 플러그인 정의 구성 데이터입니다. 설정이 무시되거나 유효하지 않게 되는 것을 방지하려면 플러그인 문서에 명시된 필드만 사용하세요.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`플러그인 활성화`},help:{"v1-12soc0h-9a":`특정 플러그인 항목의 활성화 여부를 전역 플러그인 정책보다 우선하여 적용하는 설정입니다. 기본 하이브리드 다시 로드 모드에서는 해당 플러그인이 이 경로에서 재시작을 요구하지 않는 한, Gateway를 재시작하지 않고 플러그인 런타임을 핫 리로드하여 새 에이전트 턴에 변경 사항을 적용합니다. 이 설정을 사용하면 환경별로 플러그인을 점진적으로 배포할 수 있습니다.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`플러그인 환경 변수`},help:{"v1-p39pu4-52":`해당 플러그인의 런타임 컨텍스트에만 주입되는 플러그인별 환경 변수 맵입니다. 전역 프로세스 환경을 공유하는 대신 공급자 자격 증명의 사용 범위를 하나의 플러그인으로 제한할 때 사용하세요.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`플러그인 훅 정책`},help:{"v1-1oslnrf-4c":`코어에서 강제하는 안전장치를 위한 플러그인별 타입 지정 훅 정책 설정입니다. 플러그인 전체를 비활성화하지 않고도 영향력이 큰 훅 범주를 제한할 수 있습니다.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`대화 접근 훅 허용`},help:{"v1-xqz31z-7e":"이 플러그인이 `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize`, `agent_end` 등의 타입 지정 훅을 통해 원본 대화 내용을 읽을 수 있는지 제어합니다. 기본 제공되지 않는 플러그인은 명시적으로 이 권한을 허용해야 합니다."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`프롬프트 주입 훅 허용`},help:{"v1-7y6cny-32":"이 플러그인이 타입 지정 훅을 통해 프롬프트를 수정할 수 있는지 제어합니다. `before_prompt_build`를 차단하려면 false로 설정하세요."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`플러그인 훅 시간 제한(ms)`},help:{"v1-4ra6b7-74":`이 플러그인의 타입 지정 훅에 대한 기본 제한 시간(밀리초)이며, 최댓값은 600000입니다. 설정하지 않으면 각 훅은 플러그인에 선언된 제한 시간 또는 Gateway의 훅별 정책을 사용합니다. 공통으로 적용되는 고정 기본값은 없습니다. hooks.timeouts의 훅별 값이 우선 적용됩니다.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`플러그인 훅 시간 제한 재정의`},help:{"v1-yphl9b-5s":`타입 지정 훅 이름을 키로 사용하는 훅별 시간 제한 재정의 값(밀리초)이며, 최대값은 600000입니다. 모든 훅의 시간 제한을 늘리는 대신 before_prompt_build 또는 agent_end처럼 느린 것으로 알려진 훅만 개별적으로 재정의하세요.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`플러그인 LLM 정책`},help:{"v1-dlca6c-4j":`모델 및 에이전트 재정의의 신뢰 여부를 제어하는 플러그인별 api.runtime.llm.complete 설정입니다. 플러그인이 호스트 소유의 완성 호출을 명시적으로 제어해야 하는 경우가 아니면 설정하지 마세요.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`플러그인 LLM 에이전트 재정의 허용`},help:{"v1-k8c08b-4n":`이 플러그인이 기본값이 아닌 에이전트 ID로 api.runtime.llm.complete를 요청할 수 있도록 명시적으로 허용합니다. 플러그인을 신뢰하여 다른 에이전트의 모델에 대한 접근을 허용할 수 있는 경우가 아니면 false로 유지하세요.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`플러그인 LLM 인증 프로필 재정의 허용`},help:{"v1-9ityw9-4x":`이 플러그인이 격리된 에이전트 런타임의 완성 작업에 기본값이 아닌 인증 프로필을 선택할 수 있도록 허용합니다. 플러그인을 신뢰하여 격리된 자격 증명의 명시적 라우팅을 허용할 수 있는 경우가 아니면 false로 유지하세요.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`플러그인 LLM 허용 완성 모델`},help:{"v1-1ul08he-54":`모든 플러그인 LLM 완성 호출에 허용되는 대상을 표준 "provider/model" 참조 형식으로 지정합니다. 호스트에서 결정한 기본값과 재정의도 포함됩니다. 모든 모델을 의도적으로 허용하려는 경우에만 "*"를 사용하세요.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`플러그인 LLM 허용 모델`},help:{"v1-154sk45-47":`신뢰할 수 있는 플러그인의 LLM 호출에 허용되는 재정의 대상을 표준 "provider/model" 참조 형식으로 지정합니다. 모든 모델로의 재정의를 의도적으로 허용하려는 경우에만 "*"를 사용하세요.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`플러그인 LLM 모델 재정의 허용`},help:{"v1-uw4jmc-47":`이 플러그인이 api.runtime.llm.complete에서 모델 재정의를 요청하도록 명시적으로 허용합니다. 모델 선택을 맡길 만큼 플러그인을 신뢰하는 경우가 아니라면 false로 유지하세요.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`플러그인 하위 에이전트 정책`},help:{"v1-wbf4m1-4d":`모델 재정의 신뢰 여부와 허용 목록을 관리하는 플러그인별 하위 에이전트 런타임 설정입니다. 플러그인이 하위 에이전트의 모델 선택을 명시적으로 제어해야 하는 경우가 아니라면 설정하지 마세요.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`플러그인 하위 에이전트 허용 모델`},help:{"v1-2pvkow-42":`신뢰할 수 있는 플러그인의 하위 에이전트 실행에 허용되는 재정의 대상을 표준 "provider/model" 참조 형식으로 지정합니다. 모든 모델을 의도적으로 허용하려는 경우에만 "*"를 사용하세요.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`플러그인 하위 에이전트 모델 재정의 허용`},help:{"v1-1r5tzm1-4g":`이 플러그인이 백그라운드 하위 에이전트 실행에서 제공자/모델 재정의를 요청하도록 명시적으로 허용합니다. 모델 선택을 맡길 수 있는 신뢰할 만한 플러그인이 아니라면 false로 유지하세요.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`플러그인 로더`},help:{"v1-1myjwbi-52":`플러그인을 검색할 파일 시스템 경로를 지정하는 플러그인 로더 설정 그룹입니다. 신뢰할 수 없는 확장이 실수로 로드되지 않도록 로드 경로를 명시하고 검토하세요.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`플러그인 로드 경로`},help:{"v1-o689p1-4z":`로더가 기본 내장 경로 외에 추가로 검색할 플러그인 파일 또는 디렉터리입니다. 전용 확장 디렉터리를 사용하고 관련 없는 실행 파일이 포함된 광범위한 경로는 피하세요.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`플러그인 슬롯`},help:{"v1-zx6crl-5f":`메모리와 같은 독점 런타임 슬롯을 소유할 플러그인을 선택하여 하나의 플러그인만 해당 기능을 제공하도록 합니다. 동작이 충돌하는 제공자가 중복되지 않도록 슬롯 소유권을 명시하세요.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`컨텍스트 엔진 플러그인`},help:{"v1-4v13iw-2t":`활성 컨텍스트 엔진 플러그인을 ID로 선택하여 하나의 플러그인이 컨텍스트 오케스트레이션을 수행하도록 합니다.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`메모리 플러그인`},help:{"v1-80ngcl-23":`활성 메모리 플러그인을 ID로 선택하거나, "none"을 선택하여 메모리 플러그인을 비활성화하세요.`}},presence:{label:{"v1-10fdwo4-8":`접속 상태`}},proxy:{label:{"v1-ji57pa-d":`관리형 프록시`},help:{"v1-vui6bx-58":`OpenClaw 런타임의 HTTP, HTTPS, WebSocket 및 지원되는 원시 아웃바운드 경로를 위한 운영자 관리형 포워드 프록시 라우팅입니다. 중앙 집중식 아웃바운드 제어가 배포 경계에 포함되는 경우 사용하세요.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`관리형 프록시 활성화`},help:{"v1-1456xdw-49":`관리형 프록시 설정을 명시적으로 재정의합니다. URL이 있으면 기본적으로 라우팅이 활성화됩니다. 설정된 프록시 URL이나 환경 변수의 프록시 URL을 삭제하지 않고 무시하려면 false로 설정하세요.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`관리형 프록시 루프백 모드`},help:{"v1-1kaiuh0-3c":`관리형 프록시 모드가 활성화된 동안 Gateway 루프백 제어 영역의 라우팅을 제어합니다. 값은 "gateway-only", "proxy" 또는 "block"입니다.`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`관리형 프록시 URL`},help:{"v1-p36b5l-3v":`관리형 정방향 프록시 URL입니다. 일반 CONNECT 프록시에는 http://를 사용하고, 프록시 엔드포인트 자체와의 연결에 TLS가 필요한 경우에는 https://를 사용하세요.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`관리형 프록시 TLS`},help:{"v1-6i0vu-3q":`관리형 프록시 엔드포인트에 연결할 때 사용하는 TLS 설정입니다. 이 설정은 프록시 TLS에 적용되며, CONNECT 이후의 대상 TLS에는 적용되지 않습니다.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`관리형 프록시 TLS CA 파일`},help:{"v1-1ntzjia-2p":`HTTPS 관리형 프록시 엔드포인트 인증서를 검증하는 데 사용하는 사용자 지정 CA 번들의 파일 시스템 경로입니다.`}},secrets:{label:{"v1-1sihgpy-7":`비밀 정보`},help:{"v1-jgn0o9-2l":`비밀 정보 참조 제공자, 공유 저장소 동작 및 선택적 하위 프로세스 아웃바운드 보호 기능입니다.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`비밀 정보 아웃바운드 프록시`},help:{"v1-1qfgid-4n":`아웃바운드 요청 시에만 공유 저장소의 비밀 정보 센티널을 대체하는 Gateway 소유의 루프백 프록시입니다. 시작 시 적용되는 이 섹션을 변경한 후에는 Gateway를 다시 시작하세요.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`비밀 정보 아웃바운드 프록시 허용 호스트`},help:{"v1-9ypodl-6t":`요청 및 CONNECT 터널에 선택적으로 적용하는 트래픽 허용 목록입니다. 설정하면 대상이 이 목록, 시크릿별 호스트 바인딩 또는 bypassHosts에 있어야 합니다. 빈 목록은 바인딩되거나 우회 대상으로 지정된 호스트만 허용합니다. 변경 후 Gateway를 다시 시작하세요.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`시크릿 아웃바운드 프록시 우회 호스트`},help:{"v1-1oiiomv-57":`인증서 고정을 사용하는 클라이언트를 위해 인증된 블라인드 CONNECT 터널을 사용하는 정확한 호스트 이름입니다. 센티널은 암호문으로 유지되며, 평문을 노출하는 대신 공급업체 인증에 실패하게 됩니다.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`시크릿 아웃바운드 프록시 활성화`},help:{"v1-u99b1i-2h":`Gateway에서 호스팅하는 에이전트 하위 프로세스의 아웃바운드 트래픽에서 시크릿 치환을 활성화합니다. 기본값: false.`}},session:{label:{"v1-8yh9jr-7":`세션`},help:{"v1-j86s32-5d":`대화 기록 동작을 위한 전역 세션 라우팅, 초기화, 전달 정책 및 유지 관리 설정입니다. 더 엄격한 격리, 보존 또는 전달 제약이 필요하지 않으면 기본값을 유지하세요.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`DM 세션 범위`},help:{"v1-ql362c-5l":`DM 세션 범위 설정: "main"은 연속성을 유지하고, "per-peer", "per-channel-peer", "per-account-channel-peer"는 격리 수준을 높입니다. 공유 받은편지함이나 다중 계정 배포에는 격리 모드를 사용하세요.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`그룹 세션 범위`},help:{"v1-1fdezx2-6i":`그룹/채널 세션 범위 설정: "per-group"은 dmScope와 무관하게 대화방을 분리하고 에이전트의 메인 세션이 백그라운드에서 이를 지켜보도록 합니다. "main"은 대화방 컨텍스트를 메인 세션에 통합하므로 별도로 지켜볼 필요가 없습니다. "main"은 신뢰할 수 있는 대화방에만 사용하세요.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`세션 ID 연결`},help:{"v1-1y5jnsm-5n":`동일한 사용자가 하나의 DM 스레드로 연결되도록 표준 ID를 제공자 접두사가 붙은 피어 ID에 매핑합니다(예: telegram:123456). 같은 사람이 여러 채널이나 계정에 나타나는 경우 사용하세요.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`세션 기본 키`},help:{"v1-18p638h-3q":`허용되지만 무시됩니다. 에이전트별 기본 세션 접미사는 항상 "main"입니다. 이 필드는 생략하세요. 전역 세션 범위에서는 대신 "global"을 사용합니다.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`세션 유지 관리`},help:{"v1-imr441-66":`대시보드 보관 처리, 오래된 항목 정리 기준, 항목 수 제한, 초기화 시 생성된 보관 파일의 보존 기간, 디스크 예산에 따른 정리를 위한 세션 저장소 자동 유지 관리 설정입니다. warn 모드로 시작하여 영향을 확인한 후, 임계값을 조정하고 나서 enforce 모드로 전환하세요.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`비활성 대시보드 세션 보관 처리 대기 시간`},help:{"v1-1frdtub-5n":"이 기간(예: `7d`)이 지나면 비활성 대시보드 세션을 보관 처리하여 활성 세션 목록을 복잡하게 만들지 않으면서도 계속 이용할 수 있게 합니다. 자동 대시보드 보관 처리를 비활성화하려면 `false` 또는 `0`으로 설정하세요."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`대화 기록 콜드 스토리지`},help:{"v1-1kp9s9h-5s":`세션 메타데이터를 유지하면서 비활성 대화 기록을 압축된 JSONL 아카이브로 이동합니다. 아카이브 파일은 필수 기록이 되므로 백업에 포함해야 합니다. 변경 사항은 Gateway를 다시 시작하지 않아도 적용됩니다.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`아카이브 전환 기준 비활성 일수`},help:{"v1-zay1q3-5b":`지정된 일수 동안 비활성 상태인 대화 기록을 아카이브로 이동합니다(양의 정수, 기본값 30). 진행 중인 작업은 보호됩니다. 기준을 변경하면 Gateway를 다시 시작하지 않아도 다음 작업 주기에 적용됩니다.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`오래된 대화 기록 자동 아카이브`},help:{"v1-6p6vmb-5a":`백그라운드 대화 기록 보관을 활성화합니다(기본값 false). 작업자가 매분 보관 대상 대화 기록을 확인합니다. 이 명시적 보관 정책은 삭제 및 디스크 사용량 한도에 따른 정리와 별개입니다.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`세션 디스크 상한 목표`},help:{"v1-143vh09-7z":`디스크 예산에 따른 정리 후의 목표 크기(상한 기준)입니다. 기본값은 maxDiskBytes의 80%입니다. 디스크 공간이 제한된 환경에서 공간 회수를 더 엄격하게 적용하려면 명시적으로 설정하세요. 값이 0으로 계산되면 기본값이 적용되며, 음수는 유효하지 않습니다. 예산을 비활성화하려면 대신 maxDiskBytes를 사용하세요.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`세션 최대 디스크 예산`},help:{"v1-147lxk3-cj":'SQLite 기본 파일/WAL 및 집계 대상 세션 디렉터리 산출물을 포함하는 에이전트별 물리 디스크 용량 한도입니다(예: `500mb`). 기본값은 `10gb`이며, 보호된 데이터로 인해 사용량이 목표치를 초과할 수 있습니다. 한도를 초과하면 warn 모드는 용량 부족을 보고하고, enforce 모드는 오래된 초기화/삭제 산출물, 참조되지 않는 기록, 한도 적용으로 생성된 아카이브 순으로 제거합니다. 수동, 보존 기간, 대시보드, 복구 및 레거시 아카이브는 계속 보호됩니다. 비활성화하려면 `false`, `0` 또는 `"0"`으로 설정하세요.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`최대 세션 항목 수`},help:{"v1-1w2egrh-7u":`아카이브되지 않은 세션 항목 수를 제한합니다(기본값 5000). 한도를 초과한 항목 중 아카이브 대상인 영구 보존 대화는 기록과 함께 아카이브되며, 일회성 자동화 항목은 제거됩니다. 기존 아카이브는 한도에 포함되지 않습니다. 보호된 활성 항목은 계속 집계되므로 저장소가 한도를 초과한 상태로 유지될 수 있습니다.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`세션 유지 관리 모드`},help:{"v1-bq39hk-6v":`오래된 항목 정리 및 디스크 사용량 한도 정책을 보고만 할지("warn"), 실제로 적용할지("enforce") 결정합니다. 도입 중에는 "warn"을 유지하고 안전한 임계값을 검증한 후 "enforce"로 전환하세요. 콜드 스토리지에는 별도의 명시적 enabled 설정이 있습니다.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`최근 세션 보존`},help:{"v1-138q5wx-89":"이 기간(예: `7d`) 내에 활동이 있었던 대화형 세션의 기록이 경과 시간, 항목 수 및 디스크 용량 한도에 따라 자동 제거되지 않도록 보호합니다. 설정하지 않거나 `false`로 설정하면 일반적인 오래된 항목 우선 정책이 유지됩니다. 합성 모델 실행, cron, hook, heartbeat, ACP 및 하위 에이전트 행은 계속 제한적 정리 대상이 됩니다."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`세션 정리 기준 경과 시간`},help:{"v1-1xn50w7-76":"이 기간보다 오래된 보관 대상 영구 대화를 아카이브하고 일회성 자동화 항목을 삭제합니다(기본값 `30d`, 예: `12h`). 아카이브된 대화는 기록이 유지되며 복원할 수 있습니다. 보호되거나 라우팅 가능한 대화는 활성 상태로 유지됩니다."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`세션 초기화 아카이브 보존 기간`},help:{"v1-16amrs1-7r":"아카이브된 대화 기록(`*.reset.<timestamp>` 및 `*.deleted.<timestamp>`)의 경과 시간 기준 보존 설정입니다. 기본적으로 디스크 용량 한도로 인해 오래된 순서대로 삭제될 때까지 아카이브를 보관합니다. 실제 경과 시간에 따라 삭제하려면 기간(예: `30d`)을 설정하고, 시간 기반 삭제를 명시적으로 비활성화하려면 `false`를 설정하세요."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`세션 생성 시 홈에 알림`},help:{"v1-c4prn5-8b":`세션이 생성되면 해당 세션을 소유한 에이전트의 홈 세션에 시스템 알림을 대기열로 추가합니다(기본값: true). 알림에는 사용 가능한 제목과 생성자 메타데이터가 포함되며, 다음 홈 턴 또는 하트비트에서 읽힙니다. 비활성화하려면 false로 설정하세요. 초안, 시크릿 세션, 내부 세션 및 예약된 cron 실행은 제외됩니다.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`세션 초기화 정책`},help:{"v1-1hmt7n3-6r":`유형별 또는 채널별 재정의가 적용되지 않을 때 사용하는 기본 초기화 정책 객체를 정의합니다. 기본적으로 세션은 자동 초기화되지 않습니다. 자동 초기화를 사용하려면 일일 또는 유휴 시간 기반 일정을 설정하세요. /new 및 /reset은 언제든 사용할 수 있습니다.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`세션 일일 초기화 시각`},help:{"v1-wry8cv-59":`일일 초기화 모드에서 현지 시각 기준 초기화 시간(0~23시)을 설정하여 예측 가능한 시각에 세션이 새로 시작되도록 합니다. mode=daily와 함께 사용하고, 동작을 쉽게 이해할 수 있도록 운영자가 기대하는 시간대에 맞추세요.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`세션 초기화 유휴 시간(분)`},help:{"v1-1kzj0id-5e":`유휴 모드에서 초기화 전까지 허용되는 비활성 시간을 설정하며, 일일 모드에서도 보조 조건으로 사용할 수 있습니다. 연속성을 유지하려면 큰 값을, 짧게 유지되는 스레드를 더 자주 새로 시작하려면 작은 값을 사용하세요.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`세션 초기화 모드`},help:{"v1-e5ie4w-5b":`초기화 전략을 선택합니다. "none"은 자동 초기화를 비활성화하고(기본값), "daily"는 설정된 시각에 초기화하며, "idle"은 비활성 상태가 지속되면 초기화합니다. 모든 모드에서 /new 및 /reset을 계속 사용할 수 있습니다.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`채널별 세션 초기화`},help:{"v1-1uxsulx-5h":`동작을 세밀하게 제어할 수 있도록 제공업체/채널 ID를 키로 하는 채널별 초기화 재정의 설정을 제공합니다. 특정 채널에 유형별 정책과 다른 예외적인 초기화 동작이 필요한 경우에만 사용하세요.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`채팅 유형별 세션 초기화`},help:{"v1-ypdr7u-52":`기본 설정만으로 충분하지 않을 때 채팅 유형(일대일, 그룹, 스레드)별로 초기화 동작을 재정의합니다. 그룹/스레드 대화에 일대일 메시지와 다른 초기화 주기가 필요한 경우 사용하세요.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`세션 초기화(일대일)`},help:{"v1-fjnlp5-56":`일대일 채팅의 초기화 정책을 정의하며, 해당 유형의 기본 session.reset 설정보다 우선 적용됩니다. 기존 dm 별칭 대신 일대일 메시지의 표준 재정의 설정으로 사용하세요.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`세션 초기화(그룹)`},help:{"v1-hl1200-4u":`대화의 연속성과 불필요한 메시지 발생 패턴이 일대일 메시지와 다른 그룹 채팅 세션의 초기화 정책을 정의합니다. 대화가 활발한 그룹에서 맥락 이탈이 문제가 된다면 비활성 시간 기준을 더 짧게 설정하세요.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`세션 초기화(스레드)`},help:{"v1-1hgpeke-4w":`특정 주제에 집중하는 채널 스레드 워크플로를 포함하여 스레드 단위 세션의 초기화 정책을 정의합니다. 스레드 세션이 다른 채팅 유형보다 더 빨리 또는 더 늦게 만료되어야 할 때 사용하세요.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`세션 초기화 트리거`},help:{"v1-rcabsw-5a":`수신 콘텐츠와 일치하면 세션을 강제로 초기화하는 메시지 트리거 목록입니다. 일반적인 대화 중에 컨텍스트가 예기치 않게 사라지지 않도록 명시적인 초기화 문구에만 제한적으로 사용하세요.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`세션 범위`},help:{"v1-axt4ds-5z":`기본 세션 그룹화 방식을 설정합니다. "per-sender"는 발신자별로 세션을 분리하고, "global"은 채널 컨텍스트당 하나의 세션을 공유합니다. 의도적으로 컨텍스트를 공유해야 하는 경우가 아니라면 다중 사용자 환경에서 더 안전하게 동작하도록 "per-sender"를 유지하세요.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`세션 전송 정책`},help:{"v1-17qpipb-5l":`channel, chatType 및 키 접두사를 기준으로 평가하는 허용/거부 규칙을 사용하여 세션 간 전송 권한을 제어합니다. 복잡한 환경에서 세션 도구가 메시지를 전달할 수 있는 대상을 제한하는 데 사용하세요.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`세션 전송 정책 기본 동작`},help:{"v1-15plhut-53":`일치하는 sendPolicy 규칙이 없을 때 적용할 기본 동작을 "allow" 또는 "deny"로 설정합니다. 간단한 구성에서는 "allow"를 유지하고, 모든 대상에 명시적인 허용 규칙이 필요한 경우에는 "deny"를 선택하세요.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`세션 전송 정책 규칙`},help:{"v1-o217za-5h":'기본 동작에 앞서 순서대로 평가되는 허용/거부 규칙입니다. 예: `{ action: "deny", match: { channel: "discord" } }`. 포괄적인 규칙이 예외 규칙을 가리지 않도록 가장 구체적인 규칙을 먼저 배치하세요.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`세션 전송 규칙 동작`},help:{"v1-178vm80-54":`해당 일치 조건이 충족되면 규칙의 결정을 "allow" 또는 "deny"로 정의합니다. 명시적인 허용 예외를 두고 엄격한 경계를 적용하려면 거부 규칙을 먼저 배치하세요.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`세션 전송 규칙 일치 조건`},help:{"v1-18qh5qg-5d":`channel, chatType, 키 접두사 제약 조건을 조합할 수 있는 선택적 규칙 일치 조건을 정의합니다. 정책의 의도를 쉽게 파악하고 간편하게 디버깅할 수 있도록 일치 범위를 좁게 유지하세요.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`세션 전송 규칙 채널`},help:{"v1-u5erwx-50":`특정 채널/제공자 ID(예: discord, telegram, slack)에 규칙을 적용합니다. 한 채널에서 다른 채널과 독립적으로 전달을 허용하거나 거부해야 할 때 사용하세요.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`세션 전송 규칙 채팅 유형`},help:{"v1-7cv4f9-4z":`채팅 유형(direct, group, thread)에 따라 규칙을 적용하여 대화 형태별로 동작을 다르게 지정합니다. DM과 그룹 대상에 서로 다른 안전 경계가 필요할 때 사용하세요.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`세션 전송 규칙 키 접두사`},help:{"v1-ac4dee-5n":`정책을 사용하는 구성 요소에서 내부 키 정규화 단계를 거친 후 정규화된 세션 키 접두사를 기준으로 일치 여부를 판단합니다. 일반적인 접두사 제어에 사용하고, 전체 키를 정확히 일치시켜야 할 때는 rawKeyPrefix를 우선 사용하세요.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`세션 전송 규칙 원시 키 접두사`},help:{"v1-1g9w044-5e":`정규화되지 않은 원본 세션 키 접두사와 일치시켜 전체 키를 기준으로 정책 대상을 정확하게 지정합니다. 정규화된 keyPrefix의 범위가 너무 넓어 에이전트 접두사나 전송 방식별로 정밀하게 지정해야 할 때 사용하세요.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`세션 공유 모드`},help:{"v1-xbh52d-5a":`세션 소유자와 관리자가 선택할 수 있는 협업 모드를 제어합니다. 생략된 불리언 값은 기본적으로 활성화됩니다. 모드를 false로 설정하면 선택 목록에서 제거되고 새로 선택할 수 없게 됩니다.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`초안 세션 허용`},help:{"v1-1lzap27-2p":`초안 공개 범위를 허용합니다. 이 설정은 소유자나 관리자가 아닌 운영자에게 세션을 숨깁니다. 기본값: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`읽기 전용 세션 허용`},help:{"v1-upl3nu-21":`참여자가 아닌 사용자에게 세션을 읽기 전용으로 제공할 수 있도록 허용합니다. 기본값: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`제안 세션 허용`},help:{"v1-4i8owu-4g":`제안 공개 범위를 허용합니다. 현재 단계에서는 읽기 전용과 동일한 접근 허용 정책이 적용됩니다. 제안 대기열은 추후 기능에서 구성됩니다. 기본값: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`세션 저장소 경로`},help:{"v1-hreznz-56":`재시작 후에도 세션 기록을 유지하는 데 사용할 세션 저장 파일 경로를 설정합니다. 사용자 지정 디스크 구성, 백업 경로 지정 또는 마운트된 볼륨 저장소가 필요한 경우에만 경로를 명시적으로 지정하세요.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`세션 스레드 바인딩`},help:{"v1-zbzihu-4s":`지원되는 채널 전반에서 스레드에 연결된 세션 생성 및 라우팅에 적용되는 공통 기본값입니다. 여기에서 전역 기본값을 구성하고, 동작이 다른 경우에만 채널별로 재정의하세요.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`스레드 생성 컨텍스트`},help:{"v1-1set6nw-4c":`스레드에 연결된 세션 생성 시 사용할 기본 네이티브 하위 에이전트 컨텍스트입니다. 요청자의 대화 기록에서 시작하려면 "fork"를, 빈 하위 세션으로 시작하려면 "isolated"를 사용하세요. 기본값: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`스레드 연결 활성화`},help:{"v1-foomtc-3f":`스레드에 연결된 세션의 생성, 라우팅 및 전달을 제어하는 전역 마스터 스위치입니다. 비활성화하면 스레드 연결이 전역적으로 꺼집니다.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`스레드 연결 유휴 시간 제한(시간)`},help:{"v1-gffnx3-3h":`제공업체/채널 전반에서 스레드에 연결된 세션에 적용되는 기본 비활성 허용 시간입니다(0이면 유휴 상태로 인한 만료 비활성화). 기본값: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`스레드 연결 최대 유지 시간(시간)`},help:{"v1-1xfcyhw-39":`제공업체/채널 전반에서 스레드에 연결된 세션에 적용할 수 있는 절대 최대 유지 시간입니다(0이면 절대 상한 비활성화). 기본값: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`스레드에 연결된 세션 생성`},help:{"v1-1lqwbdl-46":`sessions_spawn 및 ACP 스레드 생성을 통해 스레드에 연결된 작업 세션을 만들 수 있는지 제어하는 전역 기본 설정입니다. 기본값: 스레드 연결이 활성화된 경우 true.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`허용된 스킬 심볼릭 링크 대상`},help:{"v1-xzybiq-4t":`스킬 심볼릭 링크가 설정된 소스 루트 외부를 가리킬 때 허용되는 신뢰할 수 있는 실제 대상 루트입니다. 인접 저장소의 스킬 디렉터리처럼 범위를 좁게 유지하세요.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`추가 스킬 디렉터리`},help:{"v1-11o7opu-53":`가장 낮은 우선순위로 검색할 추가 공유 스킬 루트입니다. OpenClaw 작업 공간에 복사하지 않고도 사용할 수 있어야 하는 인접 저장소나 공유 스킬 팩에 사용하세요.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Skills 변경 감시`},help:{"v1-1ckr2l5-5d":`스킬 정의 변경에 대한 파일 시스템 감시를 활성화하여 전체 프로세스를 다시 시작하지 않고도 업데이트를 적용할 수 있게 합니다. 개발 워크플로에서는 활성화하고 변경 불가능한 프로덕션 이미지에서는 비활성화하세요.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Skill Workshop 자율 모드`},help:{"v1-1s3kgit-6j":`백그라운드 학습을 제어합니다. "off"는 제안 알림만 유지하고, "propose"는 대기 중인 제안을 생성하며, "auto"는 수집된 제안을 적용하고 일반적인 파일 편집 방식으로 Workshop 소유 스킬을 매주 검토합니다. 기본값: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`서피스 정책`},help:{"v1-vgtjbs-50":`확인된 전달 서피스 ID를 키로 사용하는 서피스별 메시지 정책 재정의입니다. 배포된 특정 서피스에 에이전트 기본값보다 엄격한 무응답 처리가 필요한 경우에만 사용하세요.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`서피스 무응답 정책`},help:{"v1-12zgc3n-60":`확인된 특정 전달 서피스의 무응답 정책을 재정의합니다. 설정하지 않은 필드는 agents.defaults.silentReply를 상속합니다. 내부 또는 특정 그룹의 동작이 다른 대상에 영향을 주지 않도록 범위가 좁은 서피스 ID를 사용하세요.`}},talk:{label:{"v1-15ukbjj-4":`음성 대화`},help:{"v1-1gx10xa-5g":`음성 특성, 모델 선택, 출력 형식 및 중단 동작을 위한 Talk 모드 음성 합성 설정입니다. 이 섹션에서 지연 시간과 비용을 관리하면서 사용자 대상 음성 UX를 조정하세요.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Talk 에이전트`},help:{"v1-iee5l9-2b":`명시적인 에이전트 범위 세션 키 없이 생성된 Talk 세션을 소유하는 에이전트입니다.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Talk 자문 고속 모드`},help:{"v1-syf3xk-2o":`Talk 실시간 자문을 처리하는 일반 에이전트 실행의 고속 모드를 true 또는 false로 설정합니다.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Talk 자문 사고 수준`},help:{"v1-1ft5njw-2o":`Talk 실시간 자문을 처리하는 일반 에이전트 실행의 사고 수준을 재정의합니다.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Talk에서 사용자 발화 시 중단`},help:{"v1-8n9q4o-3l":`true(기본값)이면 Talk 모드에서 사용자가 말하기 시작할 때 어시스턴트의 음성 출력을 중단합니다. 서로 번갈아 대화하려면 활성화 상태로 유지하세요.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Talk 활성 제공업체`},help:{"v1-wgnxhg-1g":`활성 Talk 제공업체 ID입니다(예: "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Talk 제공업체 설정`},help:{"v1-oh0yuv-30":`제공업체 ID를 키로 사용하는 제공업체별 Talk 설정입니다. 마이그레이션 시 기존 talk.* 키보다 이 설정을 우선 사용하세요.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Talk 제공업체 구성`},help:{"v1-36pblg-1r":`해당 제공업체 ID에 대해 제공업체가 정의하는 Talk 구성 필드입니다.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Talk 제공업체 API 키`},help:{"v1-1a1p9wp-v":`Talk 모드용 제공업체 API 키입니다.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`실시간 대화`},help:{"v1-c2re7j-3z":`실시간 대화 제공업체, 모델, 음성, 모드, 전송 방식 및 추론 전략입니다. 음성/TTS 제공업체 설정은 talk.provider 및 talk.providers에 유지하세요.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`실시간 대화 추론`},help:{"v1-opsatw-37":`대화 추론 전략입니다. Gateway를 통한 에이전트 지원에는 agent-consult, 로컬 도구 호출에는 direct-tools를 사용하고, 사용하지 않으려면 none을 선택하세요.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`실시간 대화 자문 라우팅`},help:{"v1-10qjcvk-5f":`실시간 제공업체가 openclaw_agent_consult를 건너뛸 때 최종 사용자 음성 전사문에 적용할 Gateway 중계 대체 처리입니다. provider-direct는 제공업체의 응답을 유지하고, force-agent-consult는 OpenClaw를 통해 라우팅합니다.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`실시간 대화 지침`},help:{"v1-1jaaj84-5p":`OpenClaw의 기본 실시간 대화 프롬프트에 추가되는 시스템 지침입니다. agent-consult 지침을 그대로 유지하면서 음성 스타일, 어조 및 기타 제공업체의 실시간 동작을 지정하는 데 사용하세요.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`실시간 대화 모드`},help:{"v1-1u2xui1-1l":`대화 실행 모드: realtime, stt-tts 또는 transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`실시간 대화 모델`},help:{"v1-amou5a-27":`브라우저 또는 Gateway가 소유한 대화 세션에 사용할 실시간 제공업체 모델 ID 재정의입니다.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`실시간 대화 앞부분 패딩(ms)`},help:{"v1-1cwg07n-22":`실시간 음성 활동이 감지되기 전에 보존할 오디오 길이(밀리초)입니다.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`실시간 대화 제공업체`},help:{"v1-wwsmpt-1o":`활성 실시간 음성 제공업체 ID입니다. 예: openai 또는 google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Talk 실시간 제공업체 설정`},help:{"v1-ruagcu-1r":`제공업체 ID를 키로 사용하는 제공업체별 실시간 음성 설정입니다.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Talk 실시간 제공업체 구성`},help:{"v1-edfpxm-1u":`해당 제공업체 ID에 대응하는 제공업체 고유의 실시간 음성 구성입니다.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Talk 실시간 제공업체 API 키`},help:{"v1-1fbmgpx-z":`실시간 Talk용 제공업체 API 키입니다.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Talk 실시간 추론 수준`},help:{"v1-157xd3e-2t":`실시간 Talk 세션의 제공업체별 추론 수준입니다. 예: minimal, low, medium 또는 high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Talk 실시간 무음 지속 시간(ms)`},help:{"v1-1grnu06-1y":`실시간 Talk에서 사용자 발화가 확정되기 전까지의 무음 시간(밀리초)입니다.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talk 실시간 화자 음성`},help:{"v1-1kgb166-2h":`브라우저 또는 Gateway에서 관리하는 Talk 세션에 사용할 실시간 제공업체의 화자 음성 이름을 재정의합니다.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talk 실시간 화자 음성 ID`},help:{"v1-1k8w6vk-2f":`브라우저 또는 Gateway에서 관리하는 Talk 세션에 사용할 실시간 제공업체의 화자 음성 ID를 재정의합니다.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Talk 실시간 전송 방식`},help:{"v1-2otjgn-2g":`Talk 바이트/세션 전송 방식: webrtc, provider-websocket, gateway-relay 또는 managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Talk 실시간 VAD 임계값`},help:{"v1-nf5l2t-2j":`실시간 음성 활동 감지 임계값입니다. 0(가장 민감)부터 1(가장 둔감)까지 설정할 수 있습니다.`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Talk 무음 대기 시간(ms)`},help:{"v1-1kim32f-59":`사용자가 말을 멈춘 후 Talk 모드가 현재 음성 인식 텍스트를 확정하고 전송할 때까지의 대기 시간(밀리초)입니다. 설정하지 않으면 플랫폼 기본 대기 시간(macOS 및 Android는 700ms, iOS는 900ms)을 유지합니다.`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Talk 음성 로케일`},help:{"v1-1un3x4l-4c":`기기 노드의 Talk 음성 인식과 iOS 시스템 음성 대체 기능에 사용할 BCP 47 로케일 ID입니다. 예: "ru-RU". 설정하지 않으면 각 기기의 기본값을 사용합니다.`}},telemetry:{label:{"v1-sqprmo-9":`원격 측정`},help:{"v1-1o5tru3-55":`매일 업데이트를 확인할 때 함께 전송되는 익명 기능 통계에 대한 명시적 동의입니다. 기능 통계는 기본적으로 비활성화되어 있으며 메시지, 자격 증명 또는 식별자를 절대 포함하지 않습니다.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`기능 통계 동의 타임스탬프`},help:{"v1-1t051az-3t":`운영자가 익명 기능 통계 수집에 동의하거나 거부한 시점을 기록하는 ISO 타임스탬프입니다. 설정 마법사가 다시 묻지 않도록 합니다.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`익명 기능 통계`},help:{"v1-1ptrwuq-4r":`매일 업데이트를 확인할 때 활성화된 채널 및 제공업체 이름, 플러그인 수, 최근 세션 수를 함께 공유합니다. 기본적으로 비활성화되어 있으며 DO_NOT_TRACK=1이면 항상 비활성화됩니다.`}},tools:{label:{"v1-15cdqf0-5":`도구`},help:{"v1-1el54kl-5h":`도구 인프라 및 에이전트 간 기본값입니다. 루트의 동위 항목은 인프라와 에이전트 간 기본값을 담당하고, agents.defaults는 에이전트 루프 동작을 담당합니다. 지원되는 경우 에이전트 항목에서 둘 중 어느 쪽이든 재정의할 수 있습니다.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`에이전트 간 도구 접근`},help:{"v1-1ynpa5f-cf":`에이전트 간 세션 도구 호출(전송, 목록 조회, 기록 조회, 검색 및 상태 조회)에 대한 정책입니다(기본값: 활성화). allow를 사용하여 에이전트 쌍을 제한할 수 있으며, enabled=false는 일반적인 에이전트 간 접근을 차단합니다. 요청자 소유의 네이티브 하위 에이전트 세션과 ACP 하위 세션은 가시성이 tree 또는 all인 경우 계속 접근할 수 있습니다. 엄격하게 분리하려면 tools.sessions.visibility를 agent 또는 self로 설정하거나(tree는 여전히 요청자 소유의 네이티브/ACP 하위 세션을 허용함), 별도의 Gateway를 사용하세요.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`에이전트 간 대상 허용 목록`},help:{"v1-1jt2ari-76":`에이전트 간 호출에 참여할 수 있는 에이전트 ID 또는 * 패턴입니다. 요청 에이전트와 대상 에이전트가 모두 일치해야 합니다. 에이전트 간 접근은 기본적으로 활성화되어 있으며, allow를 생략하거나 비워 두면 모든 쌍이 허용됩니다. 접근을 제한하려면 명시적인 목록을 설정하세요. 빈 항목은 접근을 거부합니다.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`에이전트 간 도구 활성화`},help:{"v1-w950oq-ba":`에이전트 간 세션 도구 접근을 활성화합니다(기본값: true). allow를 생략하거나 비워 두면 모든 에이전트 쌍이 허용됩니다. 일반적인 에이전트 간 접근을 차단하려면 false로 설정하세요. 요청자 소유의 네이티브 하위 에이전트 세션과 ACP 하위 세션은 가시성이 tree 또는 all인 경우 계속 접근할 수 있습니다. 엄격하게 분리하려면 tools.sessions.visibility를 agent 또는 self로 설정하거나(tree는 여전히 요청자 소유의 네이티브/ACP 하위 세션을 허용함), 별도의 Gateway를 사용하세요.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`도구 허용 목록`},help:{"v1-1is3eaq-4v":`엄격한 환경에서 프로필 기반 기본값을 대체하는 절대적 도구 허용 목록입니다. 엄선된 일부 도구 기능만 의도적으로 실행하는 경우에만 사용하세요.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`도구 허용 목록 추가 항목`},help:{"v1-1xw9zp8-57":`선택한 도구 프로필과 기본 정책에 병합되는 추가 도구 허용 목록 항목입니다. 감사 시 의도적인 정책 예외를 빠르게 파악할 수 있도록 이 목록은 작고 명확하게 유지하세요.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`제공업체별 도구 정책`},help:{"v1-1ecljob-4y":`채널/제공업체 ID를 키로 사용하는 제공업체별 도구 허용/거부 재정의 설정으로, 사용 환경에 맞게 기능을 조정합니다. 특정 제공업체에 전역 도구 정책보다 엄격한 제어가 필요한 경우 사용하세요.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`코드 모드`},help:{"v1-1ecc39k-6k":'일반 OpenClaw Code Mode입니다. 전역 설정에서 생략하면 기본값은 `"auto"`이며, 명시적으로 작성한 객체에 `enabled`가 없으면 비활성 상태로 유지됩니다. 이 모드가 활성화된 에이전트 실행에서는 모델에 `exec`와 `wait`만 노출하고, 카탈로그 브리지를 통해 일반 도구에 접근합니다.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`코드 모드 활성화`},help:{"v1-rgstxz-aj":'전역 OpenClaw Code Mode 활성화 설정입니다. 전역 설정이 아예 없으면 기본값은 `"auto"`이며, 명시적으로 작성한 객체에 `enabled`가 없으면 비활성 상태로 유지됩니다. `"auto"`는 카탈로그를 선호하는 모델에서 활성화하고, `true`는 도구를 사용할 수 있는 실행에서 활성화합니다. 에이전트 및 모델별 활성화 재정의 설정이 우선 적용됩니다. 활성화된 실행에서 런타임을 사용할 수 없으면 전체 도구 목록을 노출하는 대신 안전을 위해 실행을 차단합니다.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Code Mode 실행기`},help:{"v1-l8nlk2-6x":`JavaScript 실행기: "node"(기본값)는 신뢰할 수 있는 코드에 Node vm을 사용하며 보안 샌드박스가 아닙니다. "quickjs"는 번들로 제공되는 QuickJS WASM 플러그인을 사용하여 보안이 강화된 게스트 실행 환경을 제공합니다. 도구 권한은 두 실행기 모두에 적용됩니다. 선택한 실행기가 없으면 실행이 차단됩니다.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`코드 모드 출력 제한`},help:{"v1-1hmij9q-1n":`코드 모드 출력을 통해 반환되는 직렬화된 데이터의 최대 바이트 수입니다.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`코드 모드 대기 중인 도구 호출 한도`},help:{"v1-3b5tyd-2i":`코드 모드 VM이 실행을 나중에 재개해야 하기 전까지 동시에 시작할 수 있는 중첩 도구 호출의 최대 수입니다.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`코드 모드 최대 검색 결과 수`},help:{"v1-1gpue5r-28":`코드 모드 프로그램이 요청할 수 있는 숨겨진 카탈로그 검색 결과의 최대 수입니다.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`코드 모드 스냅샷 한도`},help:{"v1-1mmgkqy-1x":`일시 중단된 QuickJS 스냅샷 하나에 대해 보관되는 직렬화된 데이터의 최대 바이트 수입니다.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`코드 모드 메모리 한도`},help:{"v1-xetora-6n":`QuickJS 게스트 힙 한도 또는 가능한 범위 내에서 적용되는 Node 워커의 V8 힙 예산(바이트)입니다. Node 런타임 오버헤드와 엔진의 최소 메모리 할당량이 실제 예산에 영향을 미치며, 외부 버퍼와 프로세스 RSS는 제외됩니다. 이는 보안을 보장하지 않습니다.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`코드 모드 노출 인터페이스`},help:{"v1-dsp2b9-2x":'모델에 노출되는 인터페이스입니다. "only"만 지원됩니다. 코드 모드의 `exec`와 `wait`를 노출하고 일반 도구는 숨깁니다.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`코드 모드 기본 검색 결과 수`},help:{"v1-1io42lu-2m":"코드 모드 내에서 `catalog.search`가 반환하는 숨겨진 카탈로그 검색 결과의 기본 수입니다."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`코드 모드 스냅샷 TTL`},help:{"v1-1nxfczz-28":"일시 중단된 Code Mode 실행이 만료되기 전까지 `wait`로 재개할 수 있는 기간입니다."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`코드 모드 제한 시간`},help:{"v1-8csycm-1p":"코드 모드의 `exec` 또는 `wait` 호출 한 번에 허용되는 최대 시간(밀리초)입니다."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`도구 차단 목록`},help:{"v1-wilr1b-4p":`프로필 또는 제공자 규칙에서 허용하더라도 목록에 있는 도구를 차단하는 전역 도구 차단 목록입니다. 긴급 차단 및 장기적인 심층 방어를 위해 차단 규칙을 사용하세요.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`도구의 권한 상승 접근`},help:{"v1-ehcm0r-5a":`신뢰할 수 있는 발신자만 접근할 수 있어야 하는 특권 명령 인터페이스에 대한 도구의 권한 상승 접근 제어입니다. 운영자 워크플로에서 권한 상승 작업을 명시적으로 요구하지 않는 한 비활성화 상태로 유지하세요.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`권한 상승 도구 허용 규칙`},help:{"v1-1u9bhih-54":`권한 상승 도구에 대한 발신자 허용 규칙으로, 일반적으로 채널/제공자 식별자 형식을 키로 사용합니다. 의도하지 않은 사용자가 권한 상승 명령을 실행할 수 없도록 허용 대상을 좁히고 명시적인 식별자를 사용하세요.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`도구의 권한 상승 접근 활성화`},help:{"v1-1n8oyal-4l":`발신자 및 정책 검사를 통과하면 도구의 권한 상승 실행 경로를 활성화합니다. 공개/공유 채널에서는 비활성화 상태로 유지하고, 신뢰할 수 있는 소유자가 운영하는 환경에서만 활성화하세요.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec 도구`},help:{"v1-p5piic-56":`셸 실행 호스트, 보안 모드, 승인 동작 및 런타임 바인딩에 대한 Exec 도구 정책 그룹입니다. 프로덕션 환경에서는 보수적인 기본값을 유지하고 권한 상승 실행 경로에 대한 통제를 강화하세요.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`apply_patch 모델 허용 목록`},help:{"v1-4q5ovf-1x":`선택 사항인 모델 ID 허용 목록입니다(예: "gpt-5.4" 또는 "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`apply_patch 활성화`},help:{"v1-1erkir4-31":`도구 정책에서 허용하는 경우 OpenAI 및 OpenAI Codex 모델에 대해 apply_patch를 활성화하거나 비활성화합니다(기본값: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch 작업 공간으로 제한`},help:{"v1-x2z207-3o":`apply_patch 경로를 작업 공간 디렉터리로 제한합니다(기본값: true). 작업 공간 외부에 쓰기를 허용하려면 false로 설정하세요(위험).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`실행 승인 후 진행 알림 지연(ms)`},help:{"v1-1gwwann-4z":`실행이 승인된 후 진행 중 알림을 표시하기까지의 지연 시간(밀리초)입니다. 빠르게 완료되는 명령의 깜박임을 줄이려면 값을 높이고, 운영자에게 더 빨리 피드백을 제공하려면 값을 낮추세요.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`실행 승인 요청`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`실행 명령 강조 표시`},help:{"v1-kyxd4o-4n":`실행 승인 프롬프트에 파서 분석에 따른 명령 강조 표시를 적용합니다(기본값: false). 실행 승인 정책을 변경하지 않고 명령 텍스트를 강조 표시하려면 이 옵션을 활성화하세요.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`상시 권한 만료 기간(일)`},help:{"v1-5uxe2j-6r":`자동화 승인 시 항상 허용으로 부여되는 상시 권한의 기본 유효 기간(1~3650일)입니다. 설정하지 않으면 권한이 취소되거나 해당 자동화가 변경될 때까지 유효합니다. 조건은 권한 부여 시 확정되므로 이 설정을 변경해도 이후에 부여되는 권한에만 적용됩니다.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`실행 대상`},help:{"v1-rno1mf-5q":`셸 명령의 실행 대상 선택 전략을 설정합니다. 런타임 환경에 맞게 동작하려면 "auto"를 사용하세요(사용 가능한 경우 sandbox, 그렇지 않으면 gateway). 고정된 실행 환경이 필요하면 sandbox/gateway/node를 명시적으로 지정하세요.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`실행 모드`},help:{"v1-1wi6t4l-5q":`정규화된 실행 정책 선택기입니다. 승인 조건을 충족하지 못한 명령을 분류기가 검토하게 하려면 "auto", 사람이 검토하게 하려면 "ask", 안전하다고 확정된 명령만 허용하려면 "allowlist", 신뢰할 수 있는 로컬 작업에는 "full"을 사용하세요.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`실행 노드 바인딩`},help:{"v1-rfnz54-4s":`연결된 노드에 명령 실행을 위임할 때 실행 도구에 사용할 노드 바인딩 설정입니다. 다중 노드 라우팅이 필요한 경우에만 노드 바인딩을 명시적으로 지정하세요.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`실행 종료 시 알림`},help:{"v1-1ounlvx-3q":`true(기본값)이면 백그라운드 실행 세션이 종료되거나 노드 실행 수명 주기 이벤트가 발생할 때 시스템 이벤트를 대기열에 추가하고 하트비트를 요청합니다.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`출력 없이 실행 성공 시 알림`},help:{"v1-1wx4xxd-3d":`true이면 백그라운드 실행이 출력 없이 성공적으로 종료되어도 완료 시스템 이벤트를 대기열에 추가합니다(기본값: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`실행 PATH 앞에 추가`},help:{"v1-s1aimc-1r":`명령 실행(gateway/sandbox) 시 PATH 앞에 추가할 디렉터리입니다.`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`실행 검토자`},help:{"v1-12y548k-4x":`자동 모드에서 사람의 승인으로 전환하기 전에 사용하는 모델 기반 실행 검토기입니다. 실행 검토를 기본 에이전트 모델과 분리하려면 여기에서 검토 전용 모델을 지정하세요.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`실행 검토자 빠른 모드`},help:{"v1-175bx14-8u":`OpenClaw 승인 검토를 위한 선택적 빠른 모드입니다. true는 지원되는 OpenAI Responses 및 ChatGPT/OAuth 경로에서 우선 처리를 요청하고, false는 표준 처리를 요청합니다. 제공업체 기본값을 유지하려면 생략하세요. 빠른 모드는 비용이 더 많이 들 수 있으며, 제공업체의 지원 여부에 따라 이용이 제한될 수 있습니다. 네이티브 Codex Guardian은 구성하지 않습니다.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`실행 검토기 모델`},help:{"v1-1lltiy5-3i":`실행 검토기 에이전트에 사용할 공급자/모델을 선택적으로 재정의합니다. 생략하면 대상 에이전트에 구성된 기본 모델을 재사용합니다.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`실행 검토자 사고 수준`},help:{"v1-yg2gby-6u":`OpenClaw 모델 기반 승인 검토를 위한 선택적 추론 강도입니다. minimal, low, medium, high, xhigh 또는 max를 지정할 수 있습니다. 제공업체 기본값을 유지하려면 생략하세요. 지원되는 수준은 선택한 모델에 맞게 정규화됩니다. 네이티브 Codex Guardian은 구성하지 않습니다.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`실행 검토기 제한 시간(ms)`},help:{"v1-1o30chi-3w":`사람의 승인으로 전환하기 전, 실행 검토기의 모델 준비 및 응답 완료에 적용되는 단계별 제한 시간입니다. 밀리초 단위로 지정합니다(기본값: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`실행용 안전 바이너리 프로필`},help:{"v1-4cdcwe-29":`바이너리별로 선택적으로 설정하는 안전 바이너리 프로필입니다(위치 인수 제한 + 허용/거부 플래그).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`실행용 안전 바이너리`},help:{"v1-1of1m2s-21":`표준 입력만 사용하는 안전한 바이너리를 명시적인 허용 목록 항목 없이 실행할 수 있도록 허용합니다.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`실행용 안전 바이너리 신뢰 디렉터리`},help:{"v1-zljbcn-2v":`안전 바이너리 경로 검사에서 신뢰할 디렉터리를 명시적으로 추가합니다(PATH 항목은 자동으로 신뢰되지 않습니다).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`실행 보안`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`인라인 코드 실행 승인 요구`},help:{"v1-jkmgo7-5z":"`python -c`, `node -e`, `ruby -e`, `osascript -e`와 같은 인터프리터의 인라인 코드 실행 형식에 대해 명시적인 승인을 요구합니다. 이러한 형식에서는 별도 확인 없이 허용 목록을 재사용하지 못하도록 하며, 항상 허용을 매번 확인으로 제한합니다."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`실행 시간 제한(초)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`작업 공간 전용 파일 시스템 도구`},help:{"v1-1mhuvka-2s":`파일 시스템 도구(read/write/edit/apply_patch)를 작업 공간 디렉터리로 제한합니다(기본값: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI 계정 및 Git 작성자`},help:{"v1-1fl77im-5s":`에이전트 도구용 관리형 로컬 GitHub CLI 프로필과 선택적 Git 작성자입니다. Gateway 실행 사용자의 기본 계정과 작성자를 유지하려면 이 객체를 생략하세요. 저장소의 원격 인증 정보는 절대 덮어쓰지 않습니다.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Git 작성자 이메일`},help:{"v1-kol5g6-1i":`해당 프로세스에서만 사용하는 선택적 Git 작성자 및 커미터 이메일입니다.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Git 작성자 이름`},help:{"v1-z5bl1f-1h":`해당 프로세스에서만 사용하는 선택적 Git 작성자 및 커미터 이름입니다.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`GitHub 인증 정보 유형`},help:{"v1-qi3qun-3q":`Gateway가 순환 갱신 인증 정보를 소유하는 관리형 OAuth 프로필임을 표시합니다. 이 항목이 생략된 프로필은 개인 액세스 토큰을 사용합니다.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub 프로필 버전`},help:{"v1-4lzl0-27":`관리형 인증 정보를 원자적으로 전환하는 데 사용되는, 내부 의미를 드러내지 않는 자동 생성 프로필 버전입니다.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`링크 이해 활성화`},help:{"v1-23t2io-59":`에이전트 추론 전에 URL 내용을 요약할 수 있도록 자동 링크 이해 전처리를 활성화합니다. 더 풍부한 맥락을 얻으려면 활성화 상태를 유지하고, 처리를 엄격히 최소화해야 하는 경우 비활성화하세요.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`링크 이해 최대 링크 수`},help:{"v1-ksxmcv-52":`링크 이해 중 턴당 내용을 확인할 최대 링크 수입니다. 대화가 많은 스레드에서는 값을 낮춰 지연 시간과 비용을 관리하고, 여러 링크의 맥락이 중요한 경우에는 값을 높이세요.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`링크 이해 모델`},help:{"v1-6j3mnw-5a":`링크 이해 작업에 사용할 선호 모델 목록입니다. 지원되는 경우 목록 순서대로 대체 모델을 시도합니다. 일반적인 요약에는 경량 모델을 먼저 사용하고, 고성능 모델은 필요할 때만 사용하세요.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`링크 이해 범위`},help:{"v1-183cwpa-55":`대화 맥락과 메시지 유형에 따라 링크 이해를 실행할 시점을 제어합니다. 링크를 활용할 필요가 없는 메시지에서 불필요하게 내용을 가져오지 않도록 범위를 보수적으로 설정하세요.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`링크 이해 제한 시간(초)`},help:{"v1-61v30o-4p":`각 링크의 이해 작업에 허용되는 시간(초)이며, 이 시간이 지나면 처리되지 않은 링크는 건너뜁니다. 외부 사이트가 느리거나 접속할 수 없을 때 오래 대기하지 않도록 제한 시간을 적절히 설정하세요.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`도구 호출 루프 감지`},help:{"v1-1e3rls8-5g":`최근 이력 기반 도구 호출 루프 감지 및 압축 후 보호 기능을 제어합니다. 생략하면 최근 이력 기반 감지는 꺼진 상태로, 압축 후 보호는 켜진 상태로 유지됩니다. 둘 다 활성화하려면 true로, 둘 다 비활성화하려면 false로 설정하세요.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`오디오 이해 첨부 파일 정책`},help:{"v1-1s3t9s5-3o":`조건에 맞는 오디오 첨부 파일 중 처리할 대상을 선택합니다. 여러 첨부 파일을 전사하려는 경우가 아니라면 첫 번째 파일만 처리하도록 설정하세요.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`전사문 에코 형식`},help:{"v1-glpdzh-3i":`{transcript} 플레이스홀더를 사용해 채팅에 표시할 전사문 형식을 지정합니다. 전달되는 메시지에 전사문이 포함되도록 플레이스홀더를 그대로 유지하세요.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`채팅에 전사문 표시`},help:{"v1-1dedp8c-3r":`에이전트가 처리하기 전에 오디오 전사문을 원래 채팅에 표시합니다. 사용자가 시스템이 인식한 내용을 확인해야 하는 경우 활성화하세요.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`오디오 이해 활성화`},help:{"v1-1v0x7te-2m":`음성 메모나 오디오 클립을 전사하여 에이전트 컨텍스트로 사용할 수 있도록 오디오 이해 기능을 활성화합니다.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`오디오 이해 언어`},help:{"v1-1ruqt97-3z":`오디오 전사 제공업체에 전달할 기본 언어 힌트입니다. 주로 사용하는 음성 언어를 알고 있고 제공업체의 언어 감지가 정확하지 않은 경우 설정하세요.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`오디오 이해 최대 바이트 수`},help:{"v1-1mcckc8-43":`설정된 모델과 자동 감지된 모델에 적용할 기본 오디오 입력 크기 제한입니다. 제공업체와 네트워크에서 허용할 녹음의 최대 크기로 설정하세요.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`오디오 이해 최대 문자 수`},help:{"v1-eo1dp-43":`설정된 모델과 자동 감지된 모델에 적용할 기본 최대 전사문 길이입니다. 긴 음성 메모로 인해 에이전트 컨텍스트가 커지지 않도록 하려면 더 낮은 값을 사용하세요.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`선호하는 오디오 이해 모델`},help:{"v1-1n5zya1-3c":`오디오 전사 시 나머지 호환 가능한 대체 항목보다 기능 태그가 지정된 tools.media.models 항목 하나를 우선 사용합니다.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`오디오 이해 프롬프트`},help:{"v1-1v5jtay-4b":`모델 항목에서 재정의하지 않을 때 사용하는 기본 오디오 전사 프롬프트입니다. 후속 워크플로가 전사문 스타일에 의존하는 경우 지침을 일관되게 유지하세요.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`오디오 이해 범위`},help:{"v1-1pptfg0-3w":`채널, 채팅 유형 또는 소스 키별로 오디오 이해를 제한합니다. 자동 전사가 민감하거나 비용이 많이 드는 경우 범위를 좁게 유지하세요.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`오디오 이해 제한 시간(초)`},help:{"v1-n8wc6c-3b":`오디오 이해 요청의 기본 제한 시간입니다. 긴 녹음이나 느린 로컬 전사 모델을 사용하는 경우 값을 늘리세요.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`미디어 이해 동시 실행 수`},help:{"v1-13kr9np-58":`이미지, 오디오, 동영상 작업 전체에서 턴당 동시에 실행할 수 있는 미디어 이해 작업의 최대 수입니다. 리소스가 제한된 배포 환경에서는 CPU/네트워크 포화를 방지하도록 이 값을 낮추세요.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`이미지 이해 첨부 파일 정책`},help:{"v1-11hofbw-3e":`조건에 맞는 이미지 첨부 파일 중 처리할 항목을 선택합니다. 여러 이미지의 분석이 목적이 아니라면 첫 번째 항목만 처리하세요.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`이미지 이해 활성화`},help:{"v1-1b2zw34-50":`첨부되거나 참조된 이미지를 텍스트 맥락으로 해석할 수 있도록 이미지 이해 기능을 활성화합니다. 텍스트 전용 작업이 필요하거나 이미지 처리 비용을 피하려면 비활성화하세요.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`이미지 이해 최대 바이트 수`},help:{"v1-jwwpd1-3v":`설정된 모델과 자동 감지된 모델의 기본 이미지 입력 크기 제한입니다. 제공업체의 페이로드 제한과 배포 환경의 대역폭에 맞게 설정하세요.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`이미지 이해 최대 문자 수`},help:{"v1-ebnxhk-3q":`이미지 설명의 기본 최대 길이입니다. 간결한 맥락을 원하면 낮은 값을, 상세한 OCR 및 장면 분석을 원하면 높은 값을 사용하세요.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`선호하는 이미지 이해 모델`},help:{"v1-1o2uwo6-3c":`이미지 이해에 사용할 때 나머지 호환 가능한 대체 모델보다 기능 태그가 지정된 tools.media.models 항목 하나를 우선합니다.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`이미지 이해 프롬프트`},help:{"v1-1jdcu8b-3u":`항목에서 별도로 재정의하지 않을 때 사용하는 기본 이미지 이해 프롬프트입니다. 결과를 사용하는 시스템이 일관된 설명에 의존하는 경우, 이 프롬프트가 일관된 결과를 생성하도록 유지하세요.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`이미지 이해 범위`},help:{"v1-tievo1-3s":`채널, 채팅 유형 또는 소스 키를 기준으로 이미지 이해를 제한합니다. 활동이 많거나 신뢰할 수 없는 채널에서는 처리량을 제어할 수 있도록 범위를 좁게 유지하세요.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`이미지 이해 시간 제한(초)`},help:{"v1-1wcm84x-31":`이미지 이해 요청의 기본 제한 시간입니다. 이미지가 크거나 로컬 비전 모델이 느린 경우 이 값을 늘리세요.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`미디어 이해 공통 모델`},help:{"v1-f34u65-47":`미디어 이해에 사용하는 기준 모델 목록입니다. 각 파이프라인이 호환되는 대체 모델만 선택하도록 모든 항목에 image, audio 또는 video 기능 태그를 지정하세요.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`동영상 이해 첨부 파일 정책`},help:{"v1-1qm1qrc-3e":`조건에 맞는 동영상 첨부 파일 중 처리할 대상을 선택하세요. 여러 동영상을 분석하려는 경우가 아니라면 첫 번째 파일만 처리하도록 설정하세요.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`동영상 이해 활성화`},help:{"v1-1ltx5gl-58":`동영상 이해를 활성화하면 클립을 텍스트로 요약하여 후속 추론과 응답에 활용할 수 있습니다. 동영상 처리가 정책에 어긋나거나 배포 환경에서 비용 부담이 너무 큰 경우 비활성화하세요.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`동영상 이해 최대 바이트 수`},help:{"v1-2mp77v-3v":`설정된 모델과 자동 감지된 모델에 적용되는 기본 동영상 입력 크기 제한입니다. 제공업체의 페이로드 제한과 배포 환경의 대역폭에 맞게 설정하세요.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`동영상 이해 최대 문자 수`},help:{"v1-1j0x40b-3j":`동영상 설명의 기본 최대 길이입니다. 간결한 컨텍스트가 필요하면 낮은 값을, 자세한 장면 요약이 필요하면 높은 값을 사용하세요.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`동영상 이해 우선 모델`},help:{"v1-1cygq5k-3c":`동영상 이해에 사용할 기능 태그가 지정된 tools.media.models 항목 하나를 나머지 호환 가능한 대체 항목보다 우선합니다.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`동영상 이해 프롬프트`},help:{"v1-ul2jx4-3r":`항목에서 별도로 지정하지 않은 경우 사용할 기본 동영상 이해 프롬프트입니다. 이를 사용하는 측에서 일관된 요약이 필요한 경우, 결과가 일정하게 나오도록 유지하세요.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`동영상 이해 범위`},help:{"v1-7gfrx3-3s":`채널, 채팅 유형 또는 소스 키별로 동영상 이해를 제한합니다. 활동이 많거나 신뢰할 수 없는 채널에서는 처리량을 제어할 수 있도록 범위를 좁게 유지하세요.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`동영상 이해 제한 시간(초)`},help:{"v1-e8rzsy-33":`동영상 이해 요청의 기본 제한 시간입니다. 클립이 길거나 로컬 분석 모델이 느린 경우 늘리세요.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`메시지 작업 허용 목록`},help:{"v1-1iceqwa-5c":`메시지 도구의 전역 메시지 작업 허용 목록입니다. 전체 런타임에서 축소된 작업 집합만 노출하고 허용해야 할 때만 사용하세요. 공개 에이전트나 샌드박스 에이전트에는 에이전트별 허용 목록을 우선 사용하세요.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`메시지 브로드캐스트 활성화`},help:{"v1-1ms74z7-14":`브로드캐스트 작업을 활성화합니다(기본값: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`컨텍스트 간 전송 허용(서로 다른 제공업체 간)`},help:{"v1-276qxo-2s":`서로 다른 제공업체 간 전송을 허용합니다(기본값: true). 제공업체 간 메시지 전송을 차단하려면 false로 설정하세요.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`컨텍스트 간 전송 허용(동일 제공업체)`},help:{"v1-1sg4x49-1z":`동일한 제공업체 내 다른 채널로 전송을 허용합니다(기본값: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`컨텍스트 간 전송 표시`},help:{"v1-1fg6jrp-1z":`컨텍스트 간 전송 시 출처를 나타내는 표시를 추가합니다(기본값: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`컨텍스트 간 전송 표시 접두사`},help:{"v1-eblsru-1p":`컨텍스트 간 전송 표시의 텍스트 접두사입니다("{channel}" 지원).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`컨텍스트 간 전송 표시 접미사`},help:{"v1-1nk0jub-1p":`컨텍스트 간 전송 표시의 텍스트 접미사입니다("{channel}" 지원).`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`도구 프로필`},help:{"v1-h6k98q-5k":`허용/거부 재정의를 적용하기 전에 사전 정의된 도구 정책의 기본 구성을 선택하는 데 사용하는 전역 도구 프로필 이름입니다. 에이전트 전반에서 일관된 환경 설정을 유지하는 데 사용하고, 프로필 이름은 일정하게 유지하세요.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`샌드박스 도구 정책`},help:{"v1-ea7awo-4k":`샌드박스에서 실행되는 에이전트에 별도의 기능 범위를 설정할 수 있도록 하는 도구 정책 래퍼입니다. 샌드박스 컨텍스트에서 더 강력한 안전 조치를 적용하는 데 사용하세요.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`샌드박스 도구 허용/거부 정책`},help:{"v1-ub701o-4t":`에이전트가 샌드박스 실행 환경에서 실행될 때 적용되는 도구 허용/거부 정책입니다. 샌드박스 작업이 불필요한 외부 작업으로 확대되지 않도록 정책을 최소한으로 유지하세요.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`세션 도구 접근 범위`},help:{"v1-1vtq2rh-c5":`sessions_list/sessions_history/sessions_search/sessions_send/session_status에서 대상으로 지정할 수 있는 세션을 제어합니다. (기본값 "all" = 다른 에이전트와 사용자의 세션을 포함한 Gateway의 모든 세션; "agent" = 현재 에이전트 ID의 모든 세션; "self" = 현재 세션만; "tree" = 현재 세션 + 생성된 하위 에이전트 세션). 에이전트 간 접근은 기본적으로 켜져 있으며 tools.agentToAgent에 따라 범위가 지정됩니다. 접근을 제한하려면 더 좁은 접근 범위를 사용하세요.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`하위 에이전트 도구 정책`},help:{"v1-1xoug01-4z":`생성된 하위 에이전트의 도구 사용 범위를 상위 에이전트의 기본값보다 제한하거나 확장하는 도구 정책 래퍼입니다. 위임된 에이전트의 기능을 작업 목적에 맞게 제한하는 데 사용하세요.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`하위 에이전트 도구 허용/거부 정책`},help:{"v1-7vxsbf-5d":`생성된 하위 에이전트 런타임에 적용되는 도구 허용/거부 정책입니다. 상위 에이전트보다 범위를 좁게 유지하세요. progress_card와 같은 상위 에이전트 소유 도구는 allow/alsoAllow를 통해 지정하더라도 항상 거부됩니다.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`스웜`},help:{"v1-1q96vvs-45":`수집기 모드 하위 에이전트 오케스트레이션입니다. 기본적으로 활성화되어 있으며, 사용하지 않으려면 false로 설정하세요. 도구 권한은 agents_wait 및 스웜 생성 옵션에도 계속 적용됩니다.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`스웜 기본 에이전트`},help:{"v1-p4alpg-2m":`agentId를 생략한 스웜 생성의 기본 대상 에이전트입니다. 하위 에이전트 허용 목록은 계속 적용됩니다.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`스웜 활성화`},help:{"v1-1nnnrq9-2e":`수집기 모드 하위 에이전트와 agents_wait를 활성화합니다. 기본적으로 켜져 있으며, 사용하지 않으려면 false로 설정하세요.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`스웜 그룹당 활성 하위 수집기 수`},help:{"v1-kfx6qp-1c":`스웜 그룹당 활성 상태로 유지할 수 있는 최대 하위 수집기 수입니다.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`스웜 동시 실행 하위 수집기 수`},help:{"v1-1d46jtm-1s":`스웜 그룹당 동시에 실행할 수 있는 최대 하위 수집기 수입니다.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`스웜 그룹당 총 하위 수집기 수`},help:{"v1-1gc9vl1-1e":`스웜 그룹의 전체 수명 동안 생성할 수 있는 최대 수집기 수입니다.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`스웜 최대 대기 제한 시간`},help:{"v1-bog18y-1g":`agents_wait에서 허용하는 최대 제한 시간(초)입니다.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`도구 검색`},help:{"v1-s0kx04-7y":`대규모 OpenClaw, MCP 및 클라이언트 도구 카탈로그를 압축합니다. 설정하지 않으면 OpenClaw 런타임은 구조화된 Tool Search를 자동으로 사용합니다. Code Mode가 활성화된 경우 우선 적용되며, Codex는 자체 검색을 사용합니다. 비활성화하려면 false로, 코드 브리지를 사용하려면 true로 설정하거나, 객체 형식으로 모드를 선택하세요.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`도구 검색 코드 제한 시간`},help:{"v1-105r499-34":"`tool_search_code` 1회 실행의 최대 시간(밀리초)입니다. 런타임은 값을 지원 범위인 1초~60초로 제한합니다."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`도구 검색 활성화`},help:{"v1-1vm3hfr-4h":"도구 검색을 활성화합니다. 활성화하면 OpenClaw는 내장 런타임 실행 중 대규모 도구 카탈로그를 직접 노출하지 않고 `tool_search_code` 또는 구조화된 검색/설명/호출 도구를 통해 제공합니다."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`도구 검색 최대 결과 수`},help:{"v1-7du4kh-32":`모델이 요청할 수 있는 도구 검색 결과의 최대 개수입니다. 런타임에서 값을 지원 범위인 1..50으로 제한합니다.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`도구 검색 인터페이스`},help:{"v1-jybcbe-7x":'모델에 제공할 인터페이스를 선택합니다. "code"는 `tool_search_code`를 노출합니다. "tools"는 구조화된 검색/설명/호출 대체 도구를 노출합니다. "directory"는 크기가 제한된 도구 디렉터리를 표시하고, 사용 가능성이 높거나 필수인 스키마를 제한된 수만큼 노출하며, 나머지는 검색/설명/호출을 통해서만 접근하도록 합니다.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`도구 검색 기본 결과 수`},help:{"v1-1uchq7t-39":"모델이 제한을 지정하지 않았을 때 반환되는 도구 검색 결과의 기본 개수입니다. 런타임에서 이 값을 `maxSearchLimit` 이하로 제한합니다."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`구조화된 계획 도구 활성화`},help:{"v1-1xgegme-4o":"상위 세션에서 지속적으로 보존되는 계획과 서술형 메모를 위한 통합 `progress_card` 상태 도구입니다. 기본적으로 활성화되어 있으며, 사용하지 않으려면 false로 설정하세요. 하위 에이전트는 항상 사용할 수 없습니다."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`웹 도구`},help:{"v1-fpsy5-4y":`검색/가져오기 제공업체, 제한, 대체 동작을 조정하기 위한 웹 도구 정책 그룹입니다. 활성화 설정을 API 키 가용성 및 아웃바운드 네트워킹 정책에 맞게 유지하세요.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`웹 가져오기 캐시 TTL(분)`},help:{"v1-1hk89qp-17":`web_fetch 결과의 캐시 TTL(분 단위)입니다.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`웹 가져오기 도구 활성화`},help:{"v1-yrswld-1f":`web_fetch 도구(경량 HTTP 가져오기)를 활성화합니다.`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`웹 가져오기 요청 헤더`},help:{"v1-16bjkv5-me":"직접 web_fetch 요청에 함께 전송되는 추가 요청 헤더입니다. 예를 들어 게이트웨이 라우팅 또는 인증 헤더를 지정할 수 있습니다. 설정된 모든 값은 민감한 정보로 취급되며, 외부에 노출되는 설정과 디버그 캡처에서 가려집니다. 값은 일반 문자열이며 ${VAR} 치환과 전역 $${VAR} 리터럴 이스케이프를 지원하고, 모델이 선택한 URL로 전송됩니다. 항목은 설정을 불러올 때가 아니라 요청을 구성할 때 검증되므로, 이름이 잘못되었거나 값을 전송할 수 없는 경우 기능을 비활성화하는 대신 해당 항목을 제외하고 로그에 기록합니다. Accept, Accept-Language, User-Agent 및 Transfer-Encoding 같은 프레이밍 헤더도 제외됩니다. 사용자 에이전트를 변경하려면 tools.web.fetch.userAgent를 사용하세요. 교차 출처 리디렉션에서는 guarded-fetch의 안전한 헤더 허용 목록에 있는 항목만 유지되며, 실제로 전송되는 헤더가 변경되면 가져오기 캐시가 별도로 구분됩니다."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`웹 가져오기 최대 문자 수`},help:{"v1-12d1fw7-1d":`web_fetch가 반환하는 최대 문자 수입니다(초과분은 잘림).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`웹 가져오기 문자 수 절대 상한`},help:{"v1-cl2mf1-1v":`web_fetch의 maxChars에 대한 절대 상한입니다(설정 및 도구 호출에 적용).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`웹 가져오기 최대 리디렉션 횟수`},help:{"v1-t6eak9-1h":`web_fetch에 허용되는 최대 리디렉션 횟수입니다(기본값: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`웹 가져오기 최대 다운로드 크기(바이트)`},help:{"v1-q6ld9c-10":`잘림 처리 전 최대 다운로드 크기입니다.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`웹 가져오기 제공업체`},help:{"v1-6pb3nv-v":`웹 가져오기 대체 제공자 ID입니다.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`웹 가져오기 Readability 추출`},help:{"v1-19exqzx-2c":`Readability를 사용하여 HTML에서 주요 콘텐츠를 추출합니다(실패 시 기본 HTML 정리로 대체).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`웹 가져오기 SSRF 정책`},help:{"v1-qtn7zx-3c":`web_fetch에 한정하여 적용할 SSRF 정책 재정의입니다. 적용 범위를 좁게 유지하고, 알려진 로컬 네트워크 프록시 환경에서만 활성화하세요.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`웹 가져오기 허용 호스트 이름`},help:{"v1-1j9ctya-35":`web_fetch에서 허용할 정확한 호스트 이름 또는 IP 리터럴입니다. 원래 차단되는 대상도 포함됩니다. 목록을 최소한으로 유지하세요.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`웹 가져오기 IPv6 고유 로컬 범위 허용`},help:{"v1-1eyz55i-3b":`sing-box, Clash, Surge 등 신뢰할 수 있는 가상 IP 프록시와의 호환성을 위해 IPv6 고유 로컬 주소(fc00::/7)를 허용합니다.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`웹 가져오기 RFC 2544 벤치마크 범위 허용`},help:{"v1-u5asdb-2y":`Clash, Surge 등 가상 IP 프록시와의 호환성을 위해 RFC 2544 벤치마크 범위 IP(198.18.0.0/15)를 허용합니다.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`웹 가져오기 차단 호스트 이름`},help:{"v1-1164vvk-66":`web_fetch의 모든 리디렉션에서 DNS 조회 및 허용 규칙 적용 전에 차단할 호스트 이름 패턴입니다. 정확한 호스트 이름과 하위 도메인 전용 패턴인 "*.example.com"을 지원합니다. 루트 도메인을 차단하려면 "example.com"을 별도로 추가하세요. 비어 있거나 설정되지 않은 경우 추가로 차단하지 않습니다.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`웹 가져오기 사설 네트워크 허용(위험)`},help:{"v1-2s6mv7-3t":`web_fetch가 사설 및 내부 네트워크 대상에 접근하도록 허용합니다. 이 배포 환경에서 모델이 선택한 URL을 신뢰할 수 있는 경우가 아니라면 비활성화 상태로 유지하세요.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`웹 가져오기 제한 시간(초)`},help:{"v1-1c3yfr4-16":`web_fetch 요청의 제한 시간(초)입니다.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`웹 가져오기 User-Agent`},help:{"v1-s7pe8j-1e":`web_fetch 요청의 User-Agent 헤더를 재정의합니다.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`웹 가져오기 신뢰할 수 있는 환경 변수 프록시`},help:{"v1-1ypkqj7-54":`신뢰할 수 있는 환경 변수 기반 HTTP(S) 프록시를 통해 web_fetch를 라우팅하고 프록시가 DNS를 확인하도록 합니다. 해당 프록시를 운영자가 제어하고 DNS 확인 후 아웃바운드 정책을 적용하는 경우에만 활성화하세요.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`웹 검색 캐시 TTL(분)`},help:{"v1-6trzlf-18":`web_search 결과의 캐시 TTL(분)입니다.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`웹 검색 도구 활성화`},help:{"v1-n1cm4y-27":`지원되는 모델에 대해 관리형 web_search와 선택적 Codex 기본 검색을 활성화합니다.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`웹 검색 최대 결과 수`},help:{"v1-mrw7mi-z":`반환할 결과 수(1-10)입니다.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Codex 허용 도메인`},help:{"v1-1cv4y44-43":`네이티브 Codex web_search의 도메인 허용 목록입니다. 네이티브 호스팅 검색을 사용하는 턴에서는 관리형 web_fetch에도 이 제한이 적용되며, 관리형 제공업체를 사용하는 턴에는 변경 사항이 없습니다.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Codex 검색 컨텍스트 크기`},help:{"v1-antack-1u":`네이티브 Codex 검색 컨텍스트 크기 힌트: "low", "medium" 또는 "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`네이티브 Codex 웹 검색 활성화`},help:{"v1-ek2jzd-1k":`Codex 지원 모델에서 네이티브 Codex 웹 검색을 활성화합니다.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Codex 웹 검색 모드`},help:{"v1-1ahyq9f-32":`네이티브 Codex 웹 검색 기본 설정: "cached"(기본값이며, 제한 없는 Codex 턴에서는 live로 적용됨) 또는 "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Codex 사용자 도시`},help:{"v1-1y95orp-1d":`네이티브 Codex 웹 검색에 전송되는 대략적인 도시 정보입니다.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Codex 사용자 국가`},help:{"v1-1xkm5ms-1g":`네이티브 Codex 웹 검색에 전송되는 대략적인 국가 정보입니다.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Codex 사용자 지역`},help:{"v1-lhar02-1l":`네이티브 Codex 웹 검색에 전송되는 대략적인 지역/주입니다.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Codex 사용자 시간대`},help:{"v1-fgv9fh-1h":`네이티브 Codex 웹 검색에 전송되는 대략적인 시간대입니다.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`웹 검색 제공업체`},help:{"v1-10omglr-1x":`검색 제공업체 ID입니다. 생략하면 사용 가능한 API 키를 통해 자동으로 감지됩니다.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`웹 검색 제한 시간(초)`},help:{"v1-i0egvw-17":`web_search 요청의 제한 시간(초)입니다.`}},transcripts:{label:{"v1-1iqk6o8-b":`전사 기록`},help:{"v1-1i0sc09-66":`회의록, 녹음 가능한 에이전트 도구, 설정된 실시간 회의 자동 시작 소스의 핵심 전사 기록 수집 설정입니다. 회의 플러그인은 기본적으로 회의록을 영구 저장합니다. 전체적으로 비활성화하려면 enabled를 false로 설정하세요.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`전사 기록 자동 시작 소스`},help:{"v1-1mzsl79-5s":`Gateway 시작 시부터 자동으로 관리되는 실시간 전사 기록 소스입니다. 각 항목은 목록에 있으면 활성화됩니다. 소스를 비활성화하려면 해당 항목을 제거하세요. whenOccupied가 활성화되어 있지 않으면 소스는 계속 기록을 수집합니다.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`전사 기록 계정 ID`},help:{"v1-6g2kjj-4b":`계정 구분이 필요한 전사 기록 소스에 사용하는 선택적 제공업체 계정 또는 워크스페이스 식별자입니다. 제공업체 문서에 명시된 계정 ID 형식을 사용하세요.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`전사 기록 채널 ID`},help:{"v1-1lk9d5o-4u":`Discord 음성 채널이나 Slack 허들 채널과 같은 실시간 전사 소스의 제공업체 채널 ID입니다. 자동 시작을 활성화하기 전에 제공업체별 ID의 의미를 확인하세요.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Discord 길드 ID`},help:{"v1-fyfgnk-4l":`Discord 음성 전사 소스에 사용할 선택적 Discord 길드 ID입니다. 제공업체가 길드 범위의 음성 채널 조회를 필요로 하는 경우, 일치하는 channelId와 함께 설정하세요.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`전사할 회의 URL`},help:{"v1-1xtt9ci-4f":`채널 ID 대신 URL로 참여하는 제공업체에 사용할 선택적 회의 URL입니다. 자동 시작 시 해당 회의에 참여하여 내용을 수집할 수 있으므로 신뢰할 수 있는 회의 링크만 사용하세요.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`전사 소스 제공업체 ID`},help:{"v1-1uur06p-3s":`Discord 음성 제공업체나 향후 지원될 Slack 허들 제공업체와 같은 전사 소스 제공업체의 ID입니다. 제공업체 플러그인에서 제공하는 정확한 ID를 사용하세요.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`전사 세션 ID`},help:{"v1-xyo4x5-5o":`이 자동 시작 소스에 사용할 선택적 고정 전사 세션 ID입니다. whenOccupied가 true이면 무시됩니다. 고정된 일별 선택자가 필요하고 같은 날의 ID 충돌을 방지할 수 있는 경우가 아니라면, ID가 자동 생성되도록 설정하지 않은 상태로 두세요.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`전사 제목`},help:{"v1-ycjnmp-5y":`향후 대화 기록 수집에 사용할 선택적 제목입니다. 제목만 변경하면 현재 수집은 계속 실행되며, 수집 시작 시 지정된 제목이나 저장된 노트의 이름은 변경되지 않습니다. 다른 소스 변경 사항에는 기존의 재시작 처리 방식이 적용됩니다.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`참여자가 있을 때 대화 기록 수집`},help:{"v1-34jid4-78":`소스에 사람이 참여할 때마다 새 대화 기록 세션을 시작하고, 마지막 사람이 나가면 세션을 중지하고 노트를 생성합니다. discord-voice처럼 참여자 유무를 보고하는 제공업체가 필요합니다. 기본값: false(Gateway 시작 시부터 지속적으로 수집).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`대화 기록 활성화`},help:{"v1-fyqqr0-6d":`자동 회의 노트의 영구 저장, transcripts 에이전트 도구, 설정된 자동 시작 소스를 활성화합니다. 기본값: true. 영구 저장과 도구를 비활성화하려면 false로 설정하세요. 명시적으로 지정한 회의 전사 모드에서는 제한된 범위의 최근 실시간 기록이 유지됩니다.`}},tts:{label:{"v1-bmxkk9-e":`텍스트 음성 변환`},help:{"v1-1o27tk2-4n":`지원되는 음성 또는 오디오 환경에서 에이전트 응답을 소리 내어 읽기 위한 텍스트 음성 변환 정책입니다. 음성 재생이 운영자나 사용자의 작업 흐름에 포함되지 않는다면 비활성화 상태로 유지하세요.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS 페르소나`},help:{"v1-1r0opcb-29":`기본 TTS 페르소나 ID입니다. 호스트별 로컬 TTS 페르소나 환경설정으로 이 값을 재정의할 수 있습니다.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS 페르소나 목록`},help:{"v1-19aybhl-2l":`일관된 음성 정체성과 제공업체별 음성 연결 설정을 정의하는, 이름이 지정된 TTS 페르소나입니다.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS 페르소나`},help:{"v1-10s52ah-2l":`개별 TTS 페르소나입니다. 특정 음성/모델과 프롬프트 템플릿을 지정하려면 제공업체별 연결 설정을 사용하세요.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`TTS 페르소나 제공업체 바인딩`},help:{"v1-993jop-3e":`음성 제공업체 ID를 키로 사용하는 제공업체별 TTS 페르소나 바인딩입니다. 활성 페르소나의 경우 이 바인딩이 tts.providers 설정보다 우선하여 병합됩니다.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`TTS 제공업체 설정`},help:{"v1-1k80nl4-4y":`음성 제공업체 ID를 키로 사용하는 제공업체별 TTS 설정입니다. 음성 플러그인이 핵심 구성 스키마와 분리된 상태를 유지하도록 번들로 제공되는 제공업체별 최상위 키 대신 이 설정을 사용하세요.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`TTS 제공업체 구성`},help:{"v1-dwapva-3d":`단일 음성 제공업체 ID에 대한 제공업체별 TTS 구성입니다. 필드의 범위는 해당 제공업체를 담당하는 플러그인으로 한정하세요.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`TTS 제공업체 API 키`},help:{"v1-1m2fj0i-2o":`음성 제공업체의 플러그인이 인증된 TTS 액세스를 요구할 때 해당 제공업체가 사용하는 API 키입니다.`}},tui:{label:{"v1-c8hus1-b":`터미널 UI`},help:{"v1-1fg9vw2-3s":`터미널 UI 표시 설정입니다. Gateway나 다른 UI의 동작을 변경하지 않고 터미널 전용 표시 환경설정을 지정하려면 이 섹션을 사용하세요.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`터미널 UI 바닥글`},help:{"v1-6e12l3-3k":`터미널 UI 바닥글 표시 설정입니다. 세션, 모델, 목표 및 토큰 정보를 쉽게 읽을 수 있도록 선택적 컨텍스트는 간결하게 유지하세요.`}},ui:{label:{"v1-ye4dff-2":`UI`},help:{"v1-dt1924-42":`강조 표시 및 운영자 표시 환경설정을 위한 UI 표시 설정입니다. 런타임 동작을 변경하지 않고 가독성을 맞춤 설정하려면 이 설정을 사용하세요.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`사용자 강조 색상`},help:{"v1-16klzws-4z":`Control UI 강조색: 사용자 지정 색상은 #RRGGBB, 선택한 테마의 팔레트는 'theme'를 사용하세요. ui.seamColor보다 우선 적용됩니다. 설정된 경계 색상 또는 테마 기본값을 상속하려면 이 값을 지우세요.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`강조 색상`},help:{"v1-14q3r4h-4g":`UI 화면에서 강조, 배지, 시각적 정체성 표현에 사용하는 기본 강조 색상입니다. 밝은 테마와 어두운 테마 모두에서 가독성을 유지하는 고대비 값을 사용하세요.`}},update:{label:{"v1-k12u1x-7":`업데이트`},help:{"v1-11c5k8v-5c":`OpenClaw 런타임을 최신 버전으로 유지하기 위한 업데이트 채널 및 시작 시 확인 동작입니다. 프로덕션에서는 안정성 위주의 채널을 사용하고, 실험적인 채널은 통제된 환경에서만 사용하세요.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`자동 업데이트 활성화`},help:{"v1-49xs2h-3c":`stable 및 beta 패키지 설치의 백그라운드 자동 업데이트를 활성화합니다. extended-stable은 자동 적용되지 않습니다(기본값: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`업데이트 채널`},help:{"v1-lqtdvf-5b":`git + npm 설치의 업데이트 채널입니다("stable", "extended-stable", "beta" 또는 "dev"). extended-stable은 패키지 전용입니다. 설치는 포그라운드에서만 진행되며, 시작 시 읽기 전용 안내를 선택적으로 표시할 수 있습니다.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`시작 시 업데이트 확인`},help:{"v1-qy3q9g-5v":`Gateway 시작 시 읽기 전용 extended-stable 안내를 포함하여 업데이트를 확인합니다(기본값: true). Gateway 및 헤드리스 노드의 자동 업데이트 확인, 적용, 익명 업데이트 핑을 비활성화하려면 false로 설정하세요.`}},voicewake:{label:{"v1-txt1wb-a":`음성 호출`}},web:{label:{"v1-1ae9z56-b":`웹 채널`}},wizard:{label:{"v1-28jonk-h":`설정 환경설정`},help:{"v1-14jh6rm-3b":`사용자별 설정 환경설정입니다. 기기별 마법사 기록과 확인 상태는 공유 상태 데이터베이스에 저장됩니다.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`설정 검색 접근`},help:{"v1-1nqxt0w-38":`안내형 설정의 탐색 동의 방식입니다. "full"은 별도 확인 없이 스캔하고, "guarded"는 로컬 애플리케이션을 검사하기 전에 동의를 요청합니다.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`설정 시 앱 추천`},help:{"v1-ub8uoi-30":`안내형 설정에서 설치된 애플리케이션의 이름을 사용하여 관련 플러그인과 스킬을 추천할 수 있는지 제어합니다.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`마법사 마지막 실행 타임스탬프`},help:{"v1-1y0fbk-1k":`결과가 성공적으로 저장된 마지막 마법사 실행의 타임스탬프입니다.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`마법사 마지막 실행 명령`},help:{"v1-x2pfkk-15":`마법사를 마지막으로 실행한 명령입니다.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`마법사 마지막 실행 커밋`},help:{"v1-h0jkmt-1i":`마지막 개발용 마법사 실행에 사용된 소스 커밋입니다.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`마법사 마지막 실행 모드`},help:{"v1-16508qy-1r":`마지막 마법사 실행이 "local" 설정과 "remote" 설정 중 어느 것을 대상으로 했는지 나타냅니다.`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`마법사 마지막 실행 버전`},help:{"v1-1tr4z9d-19":`마지막 마법사 실행에 사용된 OpenClaw 버전입니다.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`마법사 보안 확인 타임스탬프`},help:{"v1-86i182-2a":`설정 중 보안 사항을 확인한 타임스탬프로, 대상 구성과 함께 저장됩니다.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`작업 트리 가속`},help:{"v1-9es3gc-4r":`지원되는 경우 새 관리형 작업 트리에 파일 시스템 가속을 사용합니다(기본값: true). 일반 Git 체크아웃과 파일 복사를 사용하려면 false로 설정하세요. 새 작업 트리에만 적용됩니다.`}},worktreeRoot:{label:{"v1-bqutg0-d":`워크트리 루트`},help:{"v1-1tgti9j-5d":`새로 생성되는 관리형 워크트리의 전역 디렉터리입니다. 절대 경로를 사용하거나 홈 디렉터리를 나타내는 ~를 사용하세요. 기본값은 <state-dir>/worktrees입니다. 이 값을 변경해도 기존 워크트리는 기록된 경로를 유지합니다.`}}}}})))()}export{t as n,n as t};